import type { Series } from '../types'
import { seededRandom } from './utils'

export interface CoverArt {
  bg: string // css gradient
  glow: string
  ink: string // text color over cover
  motif: 'arc' | 'rings' | 'peaks' | 'grid' | 'sun' | 'rift'
  band: string // accent band color
}

/**
 * Build a deterministic, editorial cover palette + motif from a series.
 * Every title gets a stable, distinctive look without any external image.
 */
export function coverArt(series: Series): CoverArt {
  const rand = seededRandom(series.id + series.title)
  const h = series.hue
  const h2 = series.accentHue
  const dark = 14 + Math.floor(rand() * 12)
  const mid = 26 + Math.floor(rand() * 14)

  const bg = `linear-gradient(150deg,
    hsl(${h} 38% ${dark}%) 0%,
    hsl(${h} 34% ${mid}%) 46%,
    hsl(${h2} 40% ${mid + 8}%) 100%)`

  const glow = `radial-gradient(120% 90% at 78% 12%,
    hsl(${h2} 70% 62% / 0.55) 0%,
    hsl(${h2} 60% 48% / 0) 55%)`

  const motifs: CoverArt['motif'][] = ['arc', 'rings', 'peaks', 'grid', 'sun', 'rift']
  const motif = motifs[Math.floor(rand() * motifs.length)]

  return {
    bg,
    glow,
    ink: 'rgba(247,246,242,0.96)',
    motif,
    band: `hsl(${h2} 65% 58%)`,
  }
}

/** Two- or three-letter monogram used on compact covers. */
export function monogram(title: string): string {
  const words = title
    .replace(/[^A-Za-z0-9 ]/g, '')
    .split(/\s+/)
    .filter((w) => !['the', 'of', 'a', 'an', 'at', 'in', 'and'].includes(w.toLowerCase()))
  if (words.length === 0) return title.slice(0, 2).toUpperCase()
  if (words.length === 1) return words[0].slice(0, 2).toUpperCase()
  return (words[0][0] + words[1][0]).toUpperCase()
}
