import type { Series, SeriesStatus, WeekDay, Genre } from '../types'
import { seededRandom, slugify } from './utils'

/**
 * AniList public GraphQL API client — free, no key required.
 * Docs: https://docs.anilist.co
 *
 * Rate limit is 90 req/min, so every response is cached aggressively:
 *  - catalog  → localStorage, 6h TTL
 *  - searches → in-memory Map per query
 */

const ENDPOINT = 'https://graphql.anilist.co'
const CATALOG_CACHE_KEY = 'manhwas:anilist:catalog:v1'
const CATALOG_TTL = 6 * 60 * 60 * 1000 // 6 hours

const MEDIA_FIELDS = `
  id
  title { romaji english native }
  status
  chapters
  genres
  popularity
  trending
  averageScore
  description(asHtml: false)
  siteUrl
  updatedAt
  startDate { year month day }
  coverImage { extraLarge color }
  staff(perPage: 4, sort: [RELEVANCE]) { edges { role node { name { full } } } }
`

interface StaffEdge {
  role: string
  node: { name: { full: string } }
}

interface Media {
  id: number
  title: { romaji: string; english: string | null; native: string }
  status: string
  chapters: number | null
  genres: string[]
  popularity: number
  trending: number | null
  averageScore: number | null
  description: string | null
  siteUrl: string
  updatedAt: number
  startDate: { year: number; month: number; day: number } | null
  coverImage: { extraLarge: string; color: string | null } | null
  staff: { edges: StaffEdge[] }
}

async function gql<T>(query: string, variables: Record<string, unknown> = {}): Promise<T> {
  const res = await fetch(ENDPOINT, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
    body: JSON.stringify({ query, variables }),
  })
  if (res.status === 429) {
    // rate limited — wait the advertised retry window once, then retry
    const wait = Number(res.headers.get('Retry-After') ?? 2) * 1000
    await new Promise((r) => setTimeout(r, wait))
    const retry = await fetch(ENDPOINT, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify({ query, variables }),
    })
    if (!retry.ok) throw new Error(`AniList ${retry.status}`)
    return (await retry.json()).data
  }
  if (!res.ok) throw new Error(`AniList ${res.status}`)
  const json = await res.json()
  if (json.errors) throw new Error(json.errors[0]?.message ?? 'AniList error')
  return json.data as T
}

/* ------------------------------------------------------------------ *
 * Mapping AniList media → our Series model                           *
 * ------------------------------------------------------------------ */

function stripHtml(html: string | null): string {
  if (!html) return ''
  return html
    .replace(/<br\s*\/?>/gi, ' ')
    .replace(/<[^>]+>/g, '')
    .replace(/&quot;/g, '"')
    .replace(/&#039;|&apos;/g, "'")
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&mdash;/g, '—')
    .replace(/&hellip;/g, '…')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

function hexHue(hex: string | null | undefined): number | null {
  if (!hex || !/^#[0-9a-f]{6}$/i.test(hex)) return null
  const r = parseInt(hex.slice(1, 3), 16) / 255
  const g = parseInt(hex.slice(3, 5), 16) / 255
  const b = parseInt(hex.slice(5, 7), 16) / 255
  const max = Math.max(r, g, b)
  const min = Math.min(r, g, b)
  if (max === min) return null
  const d = max - min
  let h = 0
  if (max === r) h = ((g - b) / d) % 6
  else if (max === g) h = (b - r) / d + 2
  else h = (r - g) / d + 4
  return Math.round(((h * 60) + 360) % 360)
}

const SCHEDULE: WeekDay[] = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']

const GENRE_ALIASES: Record<string, Genre> = {
  // AniList genre → our genre vocabulary
  Action: 'Action', Adventure: 'Adventure', Fantasy: 'Fantasy', Romance: 'Romance',
  Drama: 'Drama', Horror: 'Horror', Mystery: 'Mystery', Thriller: 'Thriller',
  'Sci-Fi': 'Sci-Fi', Sports: 'Sports', Comedy: 'Comedy', 'Slice of Life': 'Slice of Life',
  Supernatural: 'Supernatural', Psychological: 'Psychological', Historical: 'Historical',
  Ecchi: 'Romance', Erotica: 'Romance', Hentai: 'Romance',
}

function mapStatus(status: string): SeriesStatus {
  switch (status) {
    case 'RELEASING': return 'Ongoing'
    case 'FINISHED': return 'Completed'
    case 'HIATUS': return 'Hiatus'
    case 'NOT_YET_RELEASED': return 'Ongoing'
    default: return 'Completed'
  }
}

/** Synthesize a deterministic, plausible chapter list (AniList rarely lists webtoon chapters). */
function synthesizeChapters(slug: string, count: number, lastUpdatedMs: number, seedStr: string) {
  const rand = seededRandom(seedStr)
  const DAY = 86_400_000
  const chapters = []
  const titlesA = ['The', 'A', 'Beneath the', 'After the', 'Before the', 'Return of the', 'Echoes of the', 'Shadow of the', 'Price of the', 'Oath of the']
  const titlesB = ['Cold Dawn', 'Broken Mask', 'Hidden Chamber', 'Paper Crane', 'Sun Temple', 'Silent Witness', 'Silver Sigil', 'Fractured Vow', 'Winter Oath', 'Northern Sea', 'Glass Monarch', 'Unspoken Memory']
  for (let i = count; i >= 1; i--) {
    const stepsBack = count - i
    const jitter = Math.floor((rand() - 0.5) * 2 * DAY)
    const release = lastUpdatedMs - stepsBack * 7 * DAY + jitter
    const title = i === 1
      ? 'Prologue: The Journey Begins'
      : `${titlesA[Math.floor(rand() * titlesA.length)]} ${titlesB[Math.floor(rand() * titlesB.length)]}`
    chapters.push({
      id: `${slug}-ch-${i}`,
      number: i,
      title,
      releaseDate: new Date(release).toISOString(),
      pageCount: 38 + Math.floor(rand() * 40),
    })
  }
  return chapters.sort((a, b) => a.number - b.number)
}

export function mapMedia(m: Media): Series {
  const slug = `al-${m.id}`
  const title = m.title.english || m.title.romaji || m.title.native
  const rand = seededRandom('meta:' + slug)

  // staff → author (story) / artist (art)
  let author = ''
  let artist = ''
  for (const edge of m.staff.edges) {
    const name = edge.node.name.full
    if (!author && /story/i.test(edge.role) && !/art/i.test(edge.role)) author = name
    else if (!artist && /art/i.test(edge.role)) artist = name
    else if (/story & art/i.test(edge.role)) { author = author || name; artist = artist || name }
  }
  if (!author) author = m.staff.edges[0]?.node.name.full ?? 'Unknown'
  if (!artist) artist = author

  const updatedAtMs = (m.updatedAt || Math.floor(Date.now() / 1000)) * 1000
  const chapterCount = m.chapters ?? 24 + Math.floor(rand() * 80)
  const chapters = synthesizeChapters(slug, chapterCount, updatedAtMs, 'ch:' + slug)

  const firstReleased = m.startDate
    ? new Date(Date.UTC(m.startDate.year, (m.startDate.month ?? 1) - 1, m.startDate.day ?? 1)).toISOString()
    : chapters[0].releaseDate

  const hue = hexHue(m.coverImage?.color) ?? Math.floor(rand() * 360)
  const accentHue = (hue + 40 + Math.floor(rand() * 60)) % 360

  return {
    id: slug,
    slug,
    title,
    author,
    artist,
    studio: 'MANHWAS Originals',
    genres: (m.genres ?? []).map((g) => GENRE_ALIASES[g] ?? ('Fantasy' as Genre)).slice(0, 4),
    status: mapStatus(m.status),
    rating: m.averageScore ? Math.round((m.averageScore / 20) * 10) / 10 : 4.0,
    ratingCount: Math.round(m.popularity * 0.6),
    views: m.popularity * 12,
    weeklyViews: Math.round(m.popularity / 10) + (m.trending ?? 0) * 400,
    synopsis:
      stripHtml(m.description) ||
      'No synopsis available for this title yet on AniList.',
    schedule: SCHEDULE[Math.floor(rand() * 7)],
    firstReleased,
    lastUpdated: new Date(updatedAtMs).toISOString(),
    featured: (m.trending ?? 0) >= 40,
    staffPick: (m.averageScore ?? 0) >= 78,
    chapters,
    hue,
    accentHue,
    // real-content extras
    coverUrl: m.coverImage?.extraLarge ?? undefined,
    siteUrl: m.siteUrl,
    isReal: true,
    altTitles: [...new Set([m.title.romaji, m.title.native, m.title.english].filter(Boolean))] as string[],
  }
}

/* ------------------------------------------------------------------ *
 * Public API                                                         *
 * ------------------------------------------------------------------ */

export async function fetchCatalog(): Promise<Series[]> {
  // serve from cache when fresh
  try {
    const raw = localStorage.getItem(CATALOG_CACHE_KEY)
    if (raw) {
      const parsed = JSON.parse(raw) as { at: number; series: Series[] }
      if (Date.now() - parsed.at < CATALOG_TTL && parsed.series?.length) return parsed.series
    }
  } catch {
    /* corrupted cache — refetch */
  }

  const query = `query ($page: Int) {
    Page(page: $page, perPage: 50) {
      media(type: MANGA, countryOfOrigin: KR, sort: POPULARITY_DESC, isAdult: false) { ${MEDIA_FIELDS} }
    }
  }`

  // two pages → ~100 of the most popular Korean manhwa
  const [p1, p2] = await Promise.all([
    gql<{ Page: { media: Media[] } }>(query, { page: 1 }),
    gql<{ Page: { media: Media[] } }>(query, { page: 2 }),
  ])
  const series = [...p1.Page.media, ...p2.Page.media]
    .filter((m) => m.title.romaji || m.title.english)
    .map(mapMedia)

  try {
    localStorage.setItem(
      CATALOG_CACHE_KEY,
      JSON.stringify({ at: Date.now(), series }),
    )
  } catch {
    /* storage full — non-fatal */
  }
  return series
}

export async function fetchSeriesBySlug(slug: string): Promise<Series | null> {
  const id = Number(slug.replace(/^al-/, ''))
  if (!Number.isFinite(id)) return null
  const query = `query ($id: Int) {
    Media(id: $id, type: MANGA) { ${MEDIA_FIELDS} }
  }`
  const data = await gql<{ Media: Media }>(query, { id })
  return data.Media ? mapMedia(data.Media) : null
}

const searchCache = new Map<string, Series[]>()

export async function searchAniList(query: string): Promise<Series[]> {
  const q = query.trim()
  if (!q) return []
  const cached = searchCache.get(q)
  if (cached) return cached

  const gqlQuery = `query ($search: String) {
    Page(page: 1, perPage: 24) {
      media(type: MANGA, countryOfOrigin: KR, search: $search, sort: SEARCH_MATCH, isAdult: false) { ${MEDIA_FIELDS} }
    }
  }`
  const data = await gql<{ Page: { media: Media[] } }>(gqlQuery, { search: q })
  const results = data.Page.media.map(mapMedia)
  searchCache.set(q, results)
  return results
}

const TRENDING_CACHE_KEY = 'manhwas:anilist:trending:v1'
const TRENDING_TTL = 6 * 60 * 60 * 1000

/** Currently-trending Korean manhwa from AniList — used to widen the live catalog. */
export async function fetchAniListTrending(limit = 30): Promise<Series[]> {
  try {
    const raw = localStorage.getItem(TRENDING_CACHE_KEY)
    if (raw) {
      const parsed = JSON.parse(raw) as { at: number; series: Series[] }
      if (Date.now() - parsed.at < TRENDING_TTL && parsed.series?.length) return parsed.series
    }
  } catch {
    /* corrupted cache — refetch */
  }

  const query = `query ($perPage: Int) {
    Page(page: 1, perPage: $perPage) {
      media(type: MANGA, countryOfOrigin: KR, sort: TRENDING_DESC, isAdult: false) { ${MEDIA_FIELDS} }
    }
  }`
  const data = await gql<{ Page: { media: Media[] } }>(query, { perPage: limit })
  const series = data.Page.media.map(mapMedia)
  try {
    localStorage.setItem(TRENDING_CACHE_KEY, JSON.stringify({ at: Date.now(), series }))
  } catch {
    /* storage full — non-fatal */
  }
  return series
}
