import React from 'react'
import ReactDOM from 'react-dom/client'
import App from './App'
import { AuthProvider } from './lib/auth'
import { StoreProvider } from './lib/store'
import { CatalogProvider } from './lib/catalog-context'
import { migrateLegacyHash } from './lib/router'
import './lib/posthog'
import './index.css'

// Old bookmarks/shared links use hash routes (#/series/…) — redirect them
// once to the equivalent real path before the app mounts.
migrateLegacyHash()

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <AuthProvider>
      <StoreProvider>
        <CatalogProvider>
          <App />
        </CatalogProvider>
      </StoreProvider>
    </AuthProvider>
  </React.StrictMode>,
)
