import { fetchCdnJson, CDN_ORIGIN } from './utils'

/**
 * Off-main-thread JSON loader for the heavy catalog snapshots.
 *
 * catalog-mk-meta.json is ~3.7MB raw and catalog-full.json ~6.7MB — their
 * JSON.parse on the main thread blocked phones for seconds (Lighthouse
 * mobile TBT ~9.6s after the chapter-window trim). The fetch AND the parse
 * run in a blob worker; the result crosses back via structuredClone
 * (~tens of ms for these sizes). Any worker failure falls back to the
 * normal main-thread fetchCdnJson.
 */

let worker: Worker | null = null
let seq = 0
const pending = new Map<number, { resolve: (v: unknown) => void; reject: (e: Error) => void }>()

// CDN-first with a same-origin fallback — mirrors fetchCdnJson, but the
// parse happens in the worker (CDN_ORIGIN import would pull utils back in;
// the origin is passed per call instead).
const WORKER_SRC = `
self.onmessage = async (e) => {
  const { id, origin, path } = e.data
  for (const base of [origin + path, path]) {
    try {
      // 'no-cache': the zone's Browser Cache TTL override (4 h) would freeze
      // chapter lists; force conditional revalidation instead (304s are cheap)
      const res = await fetch(base, { cache: 'no-cache' })
      if (res.ok) {
        const data = await res.json()
        self.postMessage({ id, ok: true, data })
        return
      }
    } catch (err) {
      /* try the next source */
    }
  }
  self.postMessage({ id, ok: false })
}
`

function getWorker(): Worker | null {
  if (worker) return worker
  if (typeof Worker === 'undefined' || typeof Blob === 'undefined') return null
  try {
    worker = new Worker(URL.createObjectURL(new Blob([WORKER_SRC], { type: 'text/javascript' })))
    worker.onmessage = (e: MessageEvent<{ id: number; ok: boolean; data?: unknown }>) => {
      const p = pending.get(e.data.id)
      if (!p) return
      pending.delete(e.data.id)
      if (e.data.ok) p.resolve(e.data.data)
      else p.reject(new Error('worker fetch failed'))
    }
    worker.onerror = () => {
      for (const [, p] of pending) p.reject(new Error('worker error'))
      pending.clear()
    }
    return worker
  } catch {
    return null
  }
}

export async function fetchJsonOffThread<T>(path: string): Promise<T | null> {
  const w = getWorker()
  if (!w) return fetchCdnJson<T>(path)
  try {
    return (await new Promise<unknown>((resolve, reject) => {
      const id = ++seq
      pending.set(id, { resolve, reject })
      w.postMessage({ id, origin: CDN_ORIGIN, path })
    })) as T
  } catch {
    // worker path failed (CORS hiccup, worker crash) — main-thread fallback
    return fetchCdnJson<T>(path)
  }
}
