import { useEffect, useRef, useState } from 'react'
import type { Chapter, Genre, Series, SeriesStatus, WeekDay } from '../types'
import { seededRandom, fetchCdnJson } from './utils'

/**
 * MangaDex public API client — free, no key required.
 * Docs: https://api.mangadex.org/docs/
 *
 * api.mangadex.org only sends CORS headers to mangadex.org, so every call is
 * routed through the same-origin edge proxy at /api/md (api/md/[...path].ts
 * on Vercel, mirrored by the dev-server proxy in vite.config.ts).
 *
 * The catalog itself is sourced from MangaDex so that every listed series
 * has REAL readable English chapter pages, streamed from the @Home CDN:
 *  1. top most-followed Korean manhwa (2 pages × 50, safe + suggestive)
 *  2. per-title English chapter feeds (progressive, concurrency-limited)
 *     — titles with no readable English chapters are simply not listed
 *  3. reader pages fetched per chapter from the @Home image servers
 *
 * AniList remains as a metadata fallback when MangaDex is unreachable.
 */

const API = '/api/md'
const COVER_CDN = 'https://uploads.mangadex.org/covers'
const MAP_KEY = 'manhwas:md:map:v1' // normalized title → manga uuid
const FEED_KEY = 'manhwas:md:feed:v1' // manga uuid → { at, chapters }
const MD_CATALOG_KEY = 'manhwas:md:catalog:v1' // full progressive catalog
const TTL = 6 * 60 * 60 * 1000 // 6 hours — auto-refreshed by the catalog provider
const MAX_FEED_PAGES = 5 // up to 2500 chapters per title

/** Minimum readable chapters for a title to appear in the live catalog. */
const MIN_CHAPTERS = 10

function lsGet<T>(key: string): T | null {
  try {
    const raw = localStorage.getItem(key)
    return raw ? (JSON.parse(raw) as T) : null
  } catch {
    return null
  }
}

function lsSet(key: string, value: unknown): void {
  try {
    localStorage.setItem(key, JSON.stringify(value))
  } catch {
    /* storage full — non-fatal */
  }
}

async function mdGet<T>(path: string): Promise<T> {
  const res = await fetch(API + path, { headers: { Accept: 'application/json' } })
  if (!res.ok) throw new Error(`MangaDex ${res.status}`)
  return (await res.json()) as T
}

function norm(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, '').replace(/^(the|a) /, '')
}

/** True when the two titles are plausibly the same work. */
function titlesMatch(a: string, b: string): boolean {
  const na = norm(a)
  const nb = norm(b)
  if (!na || !nb) return false
  return na === nb || na.includes(nb) || nb.includes(na)
}

/* ------------------------------------------------------------------ *
 * MangaDex API shapes                                                *
 * ------------------------------------------------------------------ */

interface MDManga {
  id: string
  attributes: {
    title: Record<string, string>
    altTitles: Record<string, string>[]
    description: Record<string, string>
    status: string
    year: number | null
    tags: { attributes: { name: Record<string, string> } }[]
    lastChapter: string | null
    updatedAt: string
    contentRating: string
  }
  relationships: {
    type: string
    attributes?: { name?: string; fileName?: string }
  }[]
}

interface MDMangaList {
  data: MDManga[]
}

interface MDStats {
  statistics: Record<
    string,
    { follows: number; rating: { bayesian: number | null; average: number | null } }
  >
}

interface MDChapterAttrs {
  chapter: string | null
  title: string | null
  pages: number
  publishAt: string
  externalUrl: string | null
}

interface MDFeed {
  data: { id: string; attributes: MDChapterAttrs }[]
}

interface MDAtHome {
  baseUrl: string
  chapter: { hash: string; data: string[]; dataSaver: string[] }
}

/* ------------------------------------------------------------------ *
 * Chapter feeds                                                      *
 * ------------------------------------------------------------------ */

/** Fetch the English chapter feed of a MangaDex manga (cached). */
export async function fetchFeedChapters(mangaId: string): Promise<Chapter[] | null> {
  const feedCache = lsGet<Record<string, { at: number; chapters: Chapter[] }>>(FEED_KEY) ?? {}
  const cached = feedCache[mangaId]
  if (cached && Date.now() - cached.at < TTL && cached.chapters.length) return cached.chapters

  const raw: { id: string; num: number; attrs: MDChapterAttrs }[] = []
  for (let page = 0; page < MAX_FEED_PAGES; page++) {
    const offset = page * 500
    const d = await mdGet<MDFeed>(
      `/manga/${mangaId}/feed` +
        `?translatedLanguage[]=en&order[chapter]=asc&limit=500&offset=${offset}` +
        `&contentRating[]=safe&contentRating[]=suggestive&includeExternalUrl=0`,
    )
    for (const ch of d.data) {
      const a = ch.attributes
      if (a.externalUrl) continue // external reader link, no hosted pages
      const num = parseFloat(a.chapter ?? '')
      if (!Number.isFinite(num)) continue // unnamed extras/one-shots
      raw.push({ id: ch.id, num, attrs: a })
    }
    if (d.data.length < 500) break
  }
  if (!raw.length) return null

  raw.sort((a, b) => a.num - b.num || a.attrs.publishAt.localeCompare(b.attrs.publishAt))
  // number = the SOURCE chapter number from MangaDex, not the list position
  // — feeds contain gaps and half chapters (5.5), so index+1 drifts (the
  // "Lookism 624 shown as 623" class of bug). Duplicate source numbers
  // (re-uploads) keep the most recent upload.
  const deduped: typeof raw = []
  for (const ch of raw) {
    if (deduped.length && deduped[deduped.length - 1].num === ch.num) deduped[deduped.length - 1] = ch
    else deduped.push(ch)
  }
  const chapters: Chapter[] = deduped.map((ch) => ({
    id: ch.id, // stable MangaDex UUID — also used for reading progress
    number: ch.num,
    title: ch.attrs.title?.trim() || `Chapter ${ch.attrs.chapter}`,
    releaseDate: ch.attrs.publishAt,
    pageCount: ch.attrs.pages,
    mdChapterId: ch.id,
  }))

  feedCache[mangaId] = { at: Date.now(), chapters }
  lsSet(FEED_KEY, feedCache)
  return chapters
}

/** Fetch the real page image URLs for a chapter from the MangaDex @Home CDN. */
export async function fetchChapterImages(chapterId: string): Promise<string[]> {
  const d = await mdGet<MDAtHome>(`/at-home/server/${chapterId}`)
  const { baseUrl, chapter } = d
  if (!baseUrl || !chapter?.hash || !chapter.dataSaver?.length) return []
  // data-saver = compressed pages; full quality is much heavier per chapter.
  // Images route through the edge proxy: the @Home CDN rate-limits visitor
  // IPs aggressively (429), which blanked whole chapters before — proxied
  // URLs hit the Vercel cache instead of MangaDex directly.
  return chapter.dataSaver.map((f) =>
    proxyImageUrl(`${baseUrl}/data-saver/${chapter.hash}/${f}`) as string,
  )
}

/* ------------------------------------------------------------------ *
 * Image proxying                                                     *
 * ------------------------------------------------------------------ */

const PROXIED_HOSTS =
  /^([a-z0-9-]+\.mangadex\.network|uploads\.mangadex\.org|[a-z0-9-]+\.mangakatana\.com|imgsrv\d\.com|cdn\.asurascans\.com|scans\.lastation\.us|hot\.planeptune\.us|official\.lowee\.us)$/i

/**
 * Rewrite a CDN image URL to the same-origin edge proxy.
 *
 * uploads.mangadex.org (covers) and *.mangadex.network (chapter pages)
 * throttle reader IPs hard — a household that browses a few titles quickly
 * gets 429'd and sees blank covers / blank chapters. Proxied URLs are served
 * from the Vercel cache (immutable files, 7–30 day edge TTL), so at-home
 * sees roughly one request per file instead of one per visitor. This also
 * applies to MangaKatana images (*.mangakatana.com — covers and token URLs
 * served as downloads, which the proxy streams with image headers) and to
 * mgeko chapter pages (imgsrv1..9.com — the fallback source for
 * MangaKatana-sourced series). All other URLs pass through untouched.
 */
export function proxyImageUrl(url: string | undefined): string | undefined {
  if (!url) return undefined
  try {
    const u = new URL(url)
    if (u.protocol !== 'https:' || !PROXIED_HOSTS.test(u.hostname)) return url
    return `${API}/?img=${encodeURIComponent(url)}`
  } catch {
    return url
  }
}

/* ------------------------------------------------------------------ *
 * Mapping MangaDex manga → our Series model                          *
 * ------------------------------------------------------------------ */

const GENRE_ALIASES: Record<string, Genre> = {
  Action: 'Action', Adventure: 'Adventure', Comedy: 'Comedy', Drama: 'Drama',
  Fantasy: 'Fantasy', Horror: 'Horror', Mystery: 'Mystery', Romance: 'Romance',
  'Sci-Fi': 'Sci-Fi', 'Slice of Life': 'Slice of Life', Sports: 'Sports',
  Supernatural: 'Supernatural', Psychological: 'Psychological', Thriller: 'Thriller',
  Historical: 'Historical', Reincarnation: 'Fantasy', Regression: 'Fantasy',
  'Time Travel': 'Sci-Fi', Magic: 'Fantasy', Monsters: 'Horror',
  'Award Winning': 'Drama', School: 'Slice of Life', Isekai: 'Adventure',
  'Love Triangle': 'Romance', Office: 'Slice of Life', 'Full Color': 'Drama',
  'Long Strip': 'Drama', 'Web Comic': 'Drama', 'Adaptation': 'Drama',
}

function mapStatus(status: string): SeriesStatus {
  switch (status) {
    case 'ongoing': return 'Ongoing'
    case 'completed': return 'Completed'
    case 'hiatus': return 'Hiatus'
    case 'cancelled': return 'Completed'
    default: return 'Ongoing'
  }
}

function stripHtml(html: string | null): string {
  if (!html) return ''
  return html
    .replace(/<br\s*\/?>/gi, ' ')
    .replace(/<[^>]+>/g, '')
    .replace(/&quot;/g, '"')
    .replace(/&#039;|&apos;/g, "'")
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&mdash;/g, '—')
    .replace(/&hellip;/g, '…')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

const WEEKDAYS: WeekDay[] = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']

/** Most frequent release weekday across the chapter feed. */
function deriveSchedule(chapters: Chapter[], seed: string): WeekDay {
  const counts = new Map<WeekDay, number>()
  for (const c of chapters) {
    const day = WEEKDAYS[new Date(c.releaseDate).getUTCDay()]
    counts.set(day, (counts.get(day) ?? 0) + 1)
  }
  let best: WeekDay | null = null
  let bestCount = 0
  for (const [day, n] of counts) {
    if (n > bestCount) {
      best = day
      bestCount = n
    }
  }
  return best ?? WEEKDAYS[seededRandom(seed)() * 7 | 0]
}

function displayTitle(m: MDManga): { title: string; alts: string[] } {
  const titleValues = Object.values(m.attributes.title)
  const enAlt = m.attributes.altTitles.filter((t) => 'en' in t).map((t) => t.en)
  const title = m.attributes.title.en ?? enAlt[0] ?? titleValues[0] ?? 'Untitled'
  // Keep ALL alt titles, not just English: the catalog merge matches
  // md↔mk same-work entries by shared main/alt title, and MangaKatana lists
  // romanized-Korean alts that MangaDex carries in its ko-ro altTitles —
  // filtering to 'en' was losing those matches (chapter-count shortages).
  // Non-Latin scripts produce no merge keys (the normalizer strips them),
  // so keeping them is harmless.
  const alts = [
    ...new Set([...enAlt, ...titleValues, ...m.attributes.altTitles.flatMap((t) => Object.values(t))]),
  ].filter((t): t is string => !!t && t !== title)
  return { title, alts }
}

function mapMdManga(m: MDManga, chapters: Chapter[], stats?: { follows: number; rating: number | null }): Series {
  const slug = `md-${m.id}`
  const { title, alts } = displayTitle(m)
  const follows = stats?.follows ?? 1000
  const bayesian = stats?.rating ?? null

  const authors = m.relationships.filter((r) => r.type === 'author').map((r) => r.attributes?.name)
  const artists = m.relationships.filter((r) => r.type === 'artist').map((r) => r.attributes?.name)
  const cover = m.relationships.find((r) => r.type === 'cover_art')?.attributes?.fileName

  const seed = seededRandom('md:' + m.id)
  const hue = Math.floor(seed() * 360)
  const accentHue = (hue + 40 + Math.floor(seed() * 60)) % 360

  const firstReleased =
    m.attributes.year
      ? new Date(Date.UTC(m.attributes.year, 0, 1)).toISOString()
      : chapters[0].releaseDate

  return {
    id: slug,
    slug,
    title,
    author: authors[0] ?? 'Unknown',
    artist: artists[0] ?? authors[0] ?? 'Unknown',
    studio: 'MANHWAS Originals',
    genres: (m.attributes.tags
      .map((t) => t.attributes.name.en)
      .map((g) => GENRE_ALIASES[g])
      .filter((g): g is Genre => !!g)
      .slice(0, 4) as Genre[]).length
      ? (m.attributes.tags
          .map((t) => t.attributes.name.en)
          .map((g) => GENRE_ALIASES[g])
          .filter((g): g is Genre => !!g)
          .slice(0, 4) as Genre[])
      : ['Fantasy'],
    status: mapStatus(m.attributes.status),
    rating: bayesian ? Math.round((bayesian / 2) * 10) / 10 : 4.0,
    ratingCount: Math.round(follows * 0.3),
    views: follows * 12,
    weeklyViews: Math.round(follows / 12),
    synopsis:
      stripHtml(m.attributes.description.en ?? Object.values(m.attributes.description)[0] ?? '') ||
      'No synopsis available for this title yet.',
    schedule: deriveSchedule(chapters, slug),
    firstReleased,
    lastUpdated: chapters[chapters.length - 1]?.releaseDate ?? m.attributes.updatedAt,
    featured: follows >= 60_000,
    staffPick: (bayesian ?? 0) >= 8.5,
    chapters,
    hue,
    accentHue,
    // real-content extras
    coverUrl: cover ? `${COVER_CDN}/${m.id}/${cover}.512.jpg` : undefined,
    siteUrl: `https://mangadex.org/title/${m.id}`,
    isReal: true,
    altTitles: alts,
  }
}

/* ------------------------------------------------------------------ *
 * Progressive live catalog                                           *
 * ------------------------------------------------------------------ */

/** Run tasks with limited concurrency, preserving result order. */
async function pool<T>(items: T[], limit: number, fn: (item: T) => Promise<void>): Promise<void> {
  let index = 0
  const workers = Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (index < items.length) {
      const i = index++
      try {
        await fn(items[i])
      } catch {
        /* individual failures are skipped */
      }
    }
  })
  await Promise.all(workers)
}

export interface CatalogCallbacks {
  /** Called with each progressively-loaded batch of readable series. */
  onBatch?: (series: Series[]) => void
  /** Called once with the complete catalog (also on cache hit). */
  onComplete?: (series: Series[]) => void
}

export async function fetchMangaDexCatalog(cb: CatalogCallbacks = {}): Promise<Series[]> {
  // serve from cache when fresh
  try {
    const raw = lsGet<{ at: number; series: Series[] }>(MD_CATALOG_KEY)
    if (raw && Date.now() - raw.at < TTL && raw.series?.length) {
      cb.onComplete?.(raw.series)
      return raw.series
    }
  } catch {
    /* corrupted cache — refetch */
  }

  const query =
    `/manga?originalLanguage[]=ko&order[followedCount]=desc` +
    `&contentRating[]=safe&contentRating[]=suggestive&hasAvailableChapters=true` +
    `&includes[]=cover_art&includes[]=author&includes[]=artist&limit=50`

  // The full catalog arrives via the prebuilt snapshots (catalog.json +
  // catalog-full.json); this live scan only refreshes the top titles so a
  // visit costs a handful of proxy requests, not hundreds
  const pages = await Promise.all(
    [0, 50, 100, 150].map((offset) => mdGet<MDMangaList>(query + `&offset=${offset}`)),
  )
  const manga = pages.flatMap((p) => p.data)
  if (!manga.length) throw new Error('MangaDex catalog empty')

  // statistics in batched requests (follow counts + bayesian rating)
  const stats: Record<string, { follows: number; rating: number | null }> = {}
  for (let i = 0; i < manga.length; i += 50) {
    const ids = manga.slice(i, i + 50).map((m) => `manga[]=${m.id}`).join('&')
    try {
      const s = await mdGet<MDStats>(`/statistics/manga?${ids}`)
      for (const [id, v] of Object.entries(s.statistics)) {
        stats[id] = { follows: v.follows, rating: v.rating?.bayesian ?? v.rating?.average ?? null }
      }
    } catch {
      /* stats are cosmetic — continue without */
    }
  }

  // probe each title's English feed, most-followed first, revealing batches
  const collected: Series[] = []
  let batch: Series[] = []
  const flush = () => {
    if (!batch.length) return
    collected.push(...batch)
    cb.onBatch?.(batch)
    batch = []
  }

  await pool(manga, 4, async (m) => {
    const chapters = await fetchFeedChapters(m.id)
    if (!chapters || chapters.length < MIN_CHAPTERS) return
    batch.push(mapMdManga(m, chapters, stats[m.id]))
    if (batch.length >= 4) flush()
  })
  flush()

  if (!collected.length) throw new Error('No readable titles found')
  lsSet(MD_CATALOG_KEY, { at: Date.now(), series: collected })
  cb.onComplete?.(collected)
  return collected
}

/** Load a single MangaDex series by uuid (deep links / cache misses). */
export async function fetchMangaDexSeries(id: string): Promise<Series | null> {
  try {
    const d = await mdGet<{ data: MDManga }>(
      `/manga/${id}?includes[]=cover_art&includes[]=author&includes[]=artist`,
    )
    const m = d.data
    if (!m) return null
    const chapters = await fetchFeedChapters(id)
    if (!chapters?.length) return null
    let stats: { follows: number; rating: number | null } | undefined
    try {
      const s = await mdGet<MDStats>(`/statistics/manga?manga[]=${id}`)
      const v = s.statistics[id]
      if (v) stats = { follows: v.follows, rating: v.rating?.bayesian ?? v.rating?.average ?? null }
    } catch {
      /* cosmetic */
    }
    return mapMdManga(m, chapters, stats)
  } catch {
    return null
  }
}

/* ------------------------------------------------------------------ *
 * Live search                                                        *
 * ------------------------------------------------------------------ */

const searchCache = new Map<string, Series[]>()

export async function searchMangaDex(query: string): Promise<Series[]> {
  const q = query.trim()
  if (!q) return []
  const cached = searchCache.get(q)
  if (cached) return cached

  const d = await mdGet<MDMangaList>(
    `/manga?title=${encodeURIComponent(q)}&order[followedCount]=desc&limit=12` +
      `&contentRating[]=safe&contentRating[]=suggestive&hasAvailableChapters=true` +
      `&includes[]=cover_art&includes[]=author&includes[]=artist`,
  )

  // keep only titles that loosely match the query and have readable pages
  const results: Series[] = []
  await pool(d.data.slice(0, 8), 4, async (m) => {
    const { title, alts } = displayTitle(m)
    if (![title, ...alts].some((t) => titlesMatch(t, q))) return
    const chapters = await fetchFeedChapters(m.id)
    if (!chapters?.length) return
    results.push(mapMdManga(m, chapters))
  })

  results.sort((a, b) => b.views - a.views)
  searchCache.set(q, results)
  return results
}

/* ------------------------------------------------------------------ *
 * AniList-title → MangaDex bridging (used by AniList-fallback mode)  *
 * ------------------------------------------------------------------ */

/** Resolve an AniList series title to a MangaDex manga uuid (cached). */
async function resolveMangaId(titles: string[]): Promise<string | null> {
  const map = lsGet<Record<string, string>>(MAP_KEY) ?? {}
  for (const t of titles) {
    const hit = map[norm(t)]
    if (hit) return hit
  }

  for (const t of titles) {
    try {
      const d = await mdGet<MDMangaList>(
        `/manga?title=${encodeURIComponent(t)}&limit=8` +
          `&hasAvailableChapters=true&contentRating[]=safe&contentRating[]=suggestive` +
          `&order[followedCount]=desc`,
      )
      for (const m of d.data) {
        const names = [
          ...Object.values(m.attributes.title),
          // all alt-title scripts/romanizations — AniList romaji titles often
          // match MangaDex's ko-ro romanization, not the English alt
          ...m.attributes.altTitles.flatMap((a) => Object.values(a)),
        ]
        if (names.some((n) => titlesMatch(n, t))) {
          map[norm(t)] = m.id
          lsSet(MAP_KEY, map)
          return m.id
        }
      }
    } catch {
      /* try the next title variant */
    }
  }
  return null
}

/**
 * Fetch the readable MangaDex chapter list for an AniList-backed series.
 * Returns null when the title isn't readable on MangaDex.
 */
export async function fetchRealChapters(titles: string[]): Promise<Chapter[] | null> {
  if (!titles.length) return null
  const mangaId = await resolveMangaId(titles)
  if (!mangaId) return null
  return fetchFeedChapters(mangaId)
}

/**
 * Bridge an AniList series to its MangaDex counterpart.
 * Returns the MangaDex uuid + real chapter list, or null when the title
 * has no readable English chapters on MangaDex.
 */
export async function bridgeToMangaDex(
  al: { title: string; altTitles?: string[] },
): Promise<{ mangaId: string; chapters: Chapter[] } | null> {
  const mangaId = await resolveMangaId([al.title, ...(al.altTitles ?? [])])
  if (!mangaId) return null
  const chapters = await fetchFeedChapters(mangaId)
  if (!chapters || chapters.length < MIN_CHAPTERS) return null
  return { mangaId, chapters }
}

/** Display name of the data source backing a series. */
export function sourceName(series: { siteUrl?: string }): string {
  if (series.siteUrl?.includes('mangakatana')) return 'MangaKatana'
  return series.siteUrl?.includes('mangadex') ? 'MangaDex' : 'AniList'
}

/** True when the series already carries its real MangaDex chapter list. */
export function isMangaDexSeries(series: { slug: string }): boolean {
  return series.slug.startsWith('md-')
}

/**
 * Resolve the freshest real chapter list for a live series.
 *  - MangaDex-native series: revalidate the cached feed (auto-updated every 6h)
 *  - AniList series: bridge to MangaDex when the title is readable there
 *  - §30: MD winner of a collapse group carries mkTwinSlug — its stale feed
 *    window is unioned with the MK twin's ground truth (see below)
 * Returns null when the title isn't readable on MangaDex.
 */
export function useRealChapters(series: Series | undefined): {
  chapters: Chapter[] | null
  loading: boolean
} {
  const [chapters, setChapters] = useState<Chapter[] | null>(null)
  const [loading, setLoading] = useState(false)
  const lastIdRef = useRef('')
  const seriesId = series?.isReal ? series.id : ''
  // §30: the MK twin slug is stamped onto the MD winner by title collapse —
  // it can land AFTER a deep link resolves (catalog-mk-meta snapshot merge),
  // so the effect re-runs when it appears.
  const mkTwinSlug = series?.mkTwinSlug

  useEffect(() => {
    if (!seriesId) {
      lastIdRef.current = ''
      setChapters(null)
      setLoading(false)
      return
    }
    const s = series!
    let cancelled = false
    // §30: hard-reset only when the SERIES changed — a catalog merge that
    // grows the list (mkMeta landing after a deep link resolved) re-runs
    // this effect and must revalidate in place, not blank chapters the
    // reader is already showing.
    if (lastIdRef.current !== seriesId) {
      setChapters(null)
      lastIdRef.current = seriesId
    }
    setLoading(true)

    const load =
      isMangaDexSeries(s)
        ? // revalidate the feed cache — refetches when older than the TTL
          fetchFeedChapters(s.slug.replace(/^md-/, ''))
        : // MangaKatana series have no live feed. The snapshot variant loaded
          // on mobile carries compact chapters without page paths — fetch the
          // per-series ground truth (generated at build time) once; its full
          // failure fallback is the compact list (reader shows the
          // not-available notice instead of pages).
          s.slug.startsWith('mk-')
          ? s.chaptersPartial
            ? // CDN-first (R2, unmetered) with the Vercel copy as fallback
              fetchCdnJson<{ chapters?: Chapter[] }>(
                `/mk-chapters/${encodeURIComponent(s.slug)}.json`,
              )
                .then((d) => (d?.chapters?.length ? d.chapters : s.chapters))
                .catch(() => s.chapters)
            : Promise.resolve(s.chapters)
          : fetchRealChapters(s.altTitles ? [s.title, ...s.altTitles] : [s.title])    // §30 collapse-window union: title collapse keeps the twin with MORE
    // chapters and stamps the losing MK twin's slug on the winner
    // (mkTwinSlug) — a licensed MD title's stale feed window (Lookism ≤612)
    // beat its MK twin's recent window (→626), so the newest chapters 404'd
    // in the SPA while SSR kept 200ing. Hydrate the twin's per-series ground
    // truth and union by chapter number — MD wins conflicts (mdChapterId),
    // MK fills the gaps. No-op when no twin was collapsed away.
    const resolved = s.mkTwinSlug
      ? Promise.all([
          load,
          fetchCdnJson<{ chapters?: Chapter[] }>(
            `/mk-chapters/${encodeURIComponent(s.mkTwinSlug)}.json`,
          ).catch(() => null),
        ]).then(([mdList, mkFile]) => {
          const mkChapters = mkFile?.chapters ?? []
          if (!mkChapters.length) return mdList
          if (!mdList) return mkChapters
          const byNumber = new Map(mdList.map((c) => [c.number, c]))
          for (const c of mkChapters) if (!byNumber.has(c.number)) byNumber.set(c.number, c)
          return [...byNumber.values()].sort((a, b) => a.number - b.number)
        })
      : load

    resolved
      .then((list) => {
        if (!cancelled && list) setChapters(list)
      })
      .catch(() => {
        /* keep the series' bundled chapter list */
      })
      .finally(() => {
        if (!cancelled) setLoading(false)
      })
    return () => {
      cancelled = true
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [seriesId, mkTwinSlug])

  return { chapters, loading }
}
