import { Check, X } from 'lucide-react'
import { useStore } from '../lib/store'
import { cx } from '../lib/utils'

export default function Toaster() {
  const { toasts, dismissToast } = useStore()
  return (
    <div className="pointer-events-none fixed inset-x-0 bottom-5 z-[100] flex flex-col items-center gap-2 px-4">
      {toasts.map((t) => (
        <div
          key={t.id}
          className={cx(
            'animate-toast-in pointer-events-auto flex items-center gap-3 rounded-full py-2.5 pl-3 pr-2 shadow-lg ring-1',
            t.tone === 'accent'
              ? 'bg-ink text-paper ring-black/10'
              : 'bg-paper text-ink ring-line-strong',
          )}
        >
          <span
            className={cx(
              'grid h-6 w-6 place-items-center rounded-full',
              t.tone === 'accent' ? 'bg-accent text-white' : 'bg-ink/10 text-ink',
            )}
          >
            <Check width={14} height={14} />
          </span>
          <span className="text-sm font-medium">{t.message}</span>
          <button
            onClick={() => dismissToast(t.id)}
            className={cx(
              'grid h-6 w-6 place-items-center rounded-full transition-colors',
              t.tone === 'accent' ? 'hover:bg-white/15' : 'hover:bg-ink/10',
            )}
            aria-label="Dismiss"
          >
            <X width={13} height={13} />
          </button>
        </div>
      ))}
    </div>
  )
}
