import { useEffect, useRef } from 'react'

// Approved banner zones (user, 2026-09-24) — highrevenueformat.com iframes.
// These scripts share the `atOptions` global, so they MUST load one at a
// time: a queue serializes injection (one invoke.js per mounted slot, in
// order). Each slot is a self-contained fixed-size box.
const ZONES = {
  '728x90': { key: '5a2648f6ef20937bdee759be1a2de6ba', w: 728, h: 90 },
  '468x60': { key: '3c137e29ff4bb0d574cf8e52aa2dfb5a', w: 468, h: 60 },
  '320x50': { key: '47e92ebfdee68820153eb83e84568b17', w: 320, h: 50 },
  '300x250': { key: 'e34f2ca970f1d088e9132915812b08b1', w: 300, h: 250 },
  '160x600': { key: '53832fb2a5e4a122ab45ce0b122cffad', w: 160, h: 600 },
  '160x300': { key: '9e122c7ab8202ae2d253195d43f89587', w: 160, h: 300 },
} as const

export type BannerSize = keyof typeof ZONES

// Serialized loader: banner iframes from these networks rewrite the DOM
// around their <script> tag, so each script element is created fresh and
// appended inside its own container, one after another.
let chain: Promise<void> = Promise.resolve()
function enqueue(zone: typeof ZONES[BannerSize], container: HTMLElement) {
  chain = chain.then(
    () =>
      new Promise<void>((resolve) => {
        if (!container.isConnected) return resolve()
        const at = document.createElement('script')
        at.text = `atOptions = ${JSON.stringify({ key: zone.key, format: 'iframe', height: zone.h, width: zone.w, params: {} })}`
        container.appendChild(at)
        const invoke = document.createElement('script')
        invoke.src = `https://www.highrevenueformat.com/${zone.key}/invoke.js`
        invoke.async = true
        invoke.onload = () => resolve()
        invoke.onerror = () => resolve()
        container.appendChild(invoke)
        // never deadlock the chain if the network hangs
        setTimeout(resolve, 8000)
      }),
  )
}

/**
 * One banner zone. Renders an AD-labelled box of the zone's exact size and
 * injects the network script into it. Unmount removes the box (and any
 * injected iframe with it).
 */
export default function BannerAd({ size, className = '' }: { size: BannerSize; className?: string }) {
  const ref = useRef<HTMLDivElement>(null)
  const zone = ZONES[size]

  useEffect(() => {
    const el = ref.current
    if (!el) return
    enqueue(zone, el)
    return () => {
      el.innerHTML = ''
    }
    // zone is a constant lookup — size alone identifies it
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [size])

  return (
    <div className={`relative inline-block ${className}`}>
      <span className="absolute -top-2 left-2 z-10 rounded-sm border border-onyx-line bg-onyx-2 px-1 text-[9px] font-semibold uppercase tracking-wider text-[#83817a]">
        Ad
      </span>
      <div
        ref={ref}
        aria-hidden="true"
        style={{ width: zone.w, height: zone.h }}
        className="overflow-hidden rounded-card border border-onyx-line bg-onyx-2"
      />
    </div>
  )
}
