import { Suspense, lazy, useEffect } from 'react'
import { useRoute } from './lib/router'
import { setSeo, buildRouteMeta } from './lib/seo'
import Navbar from './components/Navbar'
import Footer from './components/Footer'
import Toaster from './components/Toaster'
import EdgeAds from './components/EdgeAds'
import Home from './pages/Home'
import NotFound from './pages/NotFound'

// Home remains in the entry chunk; other routes load only when visited so a
// first-time mobile homepage doesn't parse every page/reader implementation.
const Catalog = lazy(() => import('./pages/Catalog'))
const SeriesDetail = lazy(() => import('./pages/SeriesDetail'))
const Reader = lazy(() => import('./pages/Reader'))
const Library = lazy(() => import('./pages/Library'))
const Rankings = lazy(() => import('./pages/Rankings'))
const Genres = lazy(() => import('./pages/Genres'))
const GenreDetail = lazy(() => import('./pages/GenreDetail'))
const SearchPage = lazy(() => import('./pages/SearchPage'))
const Account = lazy(() => import('./pages/Account'))
const Updates = lazy(() => import('./pages/Updates'))
const NewReleases = lazy(() => import('./pages/NewReleases'))
const StatusPage = lazy(() => import('./pages/StatusPage'))
const KindHub = lazy(() => import('./pages/KindHub'))
const Calendar = lazy(() => import('./pages/Calendar'))
const AuthorPage = lazy(() => import('./pages/AuthorPage'))
const DirectoryPage = lazy(() => import('./pages/DirectoryPage'))
const YearPage = lazy(() => import('./pages/YearPage'))
const BrowsePage = lazy(() => import('./pages/BrowsePage'))
const About = lazy(() => import('./pages/About'))
const Dmca = lazy(() => import('./pages/Dmca'))
const Privacy = lazy(() => import('./pages/Privacy'))

export default function App() {
  const route = useRoute()

  // Per-route <title>/description/canonical/robots/OG + JSON-LD.
  // Series/genre pages refine this from inside their own components
  // (buildSeriesMeta / buildGenreMeta) once catalog data is in hand.
  useEffect(() => {
    const meta = buildRouteMeta(route.segments, route.query)
    if (meta) setSeo(meta)
  }, [route.path, route.query.toString()])

  // Remove the build-time prerendered crawler content once React takes over
  // (the real UI replaces it inside #root).
  useEffect(() => {
    document.getElementById('seo-content')?.remove()
  }, [])

  // Reader route: /read/:slug/chapter-:n. The legacy bare-number form
  // (/read/:slug/:n) is 301'd to chapter-N server-side by api/read; this
  // rewrites the address bar for the remaining paths it can appear on (dev
  // server, migrated #/hash bookmarks). replaceState fires no popstate, so
  // this can't loop.
  const chapterRaw = route.segments[2] ?? ''
  // decimals (chapter-5.5) and chapter 0 are real source chapter numbers
  const chapterMatch = /^chapter-(\d+(?:\.\d+)?)$/i.exec(chapterRaw)
  useEffect(() => {
    if (route.segments[0] === 'read' && route.segments[1] && chapterRaw && !chapterMatch) {
      const n = Number(chapterRaw)
      history.replaceState(null, '', `/read/${route.segments[1]}/chapter-${Number.isFinite(n) && n >= 0 ? n : 1}`)
    }
  }, [route.path])

  if (route.segments[0] === 'read' && route.segments[1]) {
    const chapterNumber = chapterMatch
      ? Number(chapterMatch[1])
      : Number(chapterRaw) || 1
    return (
      <>
        <Suspense fallback={<RouteLoading />}>
          <Reader
            slug={route.segments[1]}
            chapterNumber={chapterNumber}
          />
        </Suspense>
        <Toaster />
        <Footer />
        {/* Edge ads — reader zone: rails only, never over the reading column */}
        <EdgeAds zone="overlay" />
      </>
    )
  }

  let page: React.ReactNode
  switch (route.segments[0]) {
    case undefined:
      page = <Home />
      break
    case 'catalog':
      page = <Catalog />
      break
    case 'series':
    case 'comic':
      page = route.segments[1] ? <SeriesDetail slug={route.segments[1]} /> : <NotFound />
      break
    case 'manhwa':
    case 'manhua':
      // bare /manhwa · /manhua → kind hub; /manhwa/{slug} → series detail
      page = route.segments[1] ? (
        <SeriesDetail slug={route.segments[1]} />
      ) : (
        <KindHub kind={route.segments[0] as 'manhwa' | 'manhua'} />
      )
      break
    case 'library':
      page = <Library />
      break
    case 'rankings':
      page = <Rankings />
      break
    case 'genres':
      // /genres/{slug} — genre hub; /genres/{slug}/page/{n} — paginated
      // views (mirrors the prerendered pagination pages)
      page = route.segments[1]
        ? <GenreDetail
            name={decodeURIComponent(route.segments[1])}
            page={route.segments[2] === 'page' && Number(route.segments[3]) > 1
              ? Number(route.segments[3])
              : undefined}
          />
        : <Genres />
      break
    // legacy singular form → canonical /genres/:name
    case 'genre':
      page = route.segments[1] ? <GenreDetail name={decodeURIComponent(route.segments[1])} /> : <Genres />
      break
    case 'author':
      page = route.segments[1] ? <AuthorPage slug={route.segments[1]} /> : <NotFound />
      break
    case 'directory':
      page = <DirectoryPage letter={route.segments[1] ? decodeURIComponent(route.segments[1]) : undefined} />
      break
    case 'years':
      page = route.segments[1] ? <YearPage year={route.segments[1]} /> : <NotFound />
      break
    case 'browse':
      page = route.segments[1] && route.segments[2]
        ? <BrowsePage kind={route.segments[1]} genre={route.segments[2]} />
        : <NotFound />
      break
    case 'updates':
      page = route.segments[1] === 'page' && Number(route.segments[2]) > 1
        ? <Updates page={Number(route.segments[2])} />
        : <Updates />
      break
    case 'new-releases':
      page = <NewReleases />
      break
    case 'status':
      page = route.segments[1] === 'ongoing' || route.segments[1] === 'completed'
        ? <StatusPage status={route.segments[1]} />
        : <NotFound />
      break
    case 'calendar':
      page = <Calendar />
      break
    case 'search':
      page = <SearchPage />
      break
    case 'account':
      page = <Account />
      break
    // Static trust pages (prerendered to dist/about.html etc. — no function,
    // no rewrite; listed in the footer and the sitemap)
    case 'about':
      page = <About />
      break
    case 'dmca':
      page = <Dmca />
      break
    case 'privacy':
      page = <Privacy />
      break
    default:
      page = <NotFound />
  }

  return (
    <div className="min-h-screen bg-paper">
      <Navbar />
      {/* Edge ads — embedded top strip directly under the Navbar */}
      <EdgeAds zone="top" />
      <Suspense fallback={<RouteLoading />}>{page}</Suspense>
      <Footer />
      <Toaster />
      {/* Edge ads — fixed rails + scroll-triggered bottom bar */}
      <EdgeAds zone="overlay" />
    </div>
  )
}

function RouteLoading() {
  return (
    <main className="mx-auto min-h-[60vh] max-w-[1240px] px-4 py-12 sm:px-6 lg:px-8" aria-label="Loading page">
      <div className="h-8 w-56 animate-pulse rounded bg-paper-3/60" />
      <div className="mt-6 h-40 animate-pulse rounded-[14px] bg-paper-3/40" />
    </main>
  )
}
