import { navigate } from '../lib/router'

function link(to: string) {
  return (e: React.MouseEvent) => {
    if (e.metaKey || e.ctrlKey) return
    e.preventDefault()
    navigate(to)
  }
}

/**
 * Minimal footer, modeled on what readers see on the big manhwa/manga sites
 * (Asura: "Privacy Policy | Terms of Service | DMCA"; MangaKatana: a single
 * centered copyright line). A brand row, one horizontal nav row, one
 * centered copyright line — nothing else.
 */
const NAV = [
  { label: 'Catalog', to: '/catalog' },
  { label: 'Latest Updates', to: '/updates' },
  { label: 'Rankings', to: '/rankings' },
  { label: 'Genres', to: '/genres' },
  { label: 'About', to: '/about' },
  { label: 'DMCA', to: '/dmca' },
  { label: 'Privacy', to: '/privacy' },
  { label: 'Contact', to: 'mailto:manhwas@proton.me' },
]

export default function Footer() {
  return (
    <footer className="mt-24 border-t border-line bg-paper-2">
      <div className="mx-auto flex max-w-[1240px] flex-col items-center gap-5 px-4 py-10 text-center sm:px-6">
        <a href="/" onClick={link('/')} className="flex items-center gap-2.5" aria-label="MANHWAS home">
          <img
            src="/logo1.png"
            alt="MANHWAS logo"
            className="h-8 w-8 shrink-0 rounded-md object-contain"
            draggable={false}
          />
          <span className="text-lg font-extrabold tracking-[-0.02em]">MANHWAS</span>
        </a>

        <nav
          aria-label="Footer"
          className="flex flex-wrap items-center justify-center gap-x-5 gap-y-2 text-sm text-ink-soft"
        >
          {NAV.map((l) => (
            <a
              key={l.label}
              href={l.to}
              onClick={/^(mailto|https?):/.test(l.to) ? undefined : link(l.to)}
              className="transition-colors hover:text-accent"
            >
              {l.label}
            </a>
          ))}
        </nav>

        <p className="text-xs text-ink-faint">© {new Date().getFullYear()} MANHWAS. All rights reserved.</p>
      </div>
    </footer>
  )
}
