import type { ReactNode } from 'react'
import { Star } from 'lucide-react'
import type { Genre, SeriesStatus } from '../types'
import { cx, genreHref } from '../lib/utils'
import { navigate } from '../lib/router'

/* ---------------- Status badge ---------------- */
export function StatusBadge({ status, className }: { status: SeriesStatus; className?: string }) {
  const map: Record<SeriesStatus, string> = {
    Ongoing: 'bg-emerald/12 text-emerald ring-emerald/25',
    Completed: 'bg-slate/12 text-slate ring-slate/25',
    Hiatus: 'bg-amber/15 text-amber ring-amber/30',
  }
  const dot: Record<SeriesStatus, string> = {
    Ongoing: 'bg-emerald',
    Completed: 'bg-slate',
    Hiatus: 'bg-amber',
  }
  return (
    <span
      className={cx(
        'inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-semibold uppercase tracking-wide ring-1 ring-inset',
        map[status],
        className,
      )}
    >
      <span className={cx('h-1.5 w-1.5 rounded-full', dot[status])} />
      {status}
    </span>
  )
}

/* ---------------- Genre pill ---------------- */
export function GenrePill({
  genre,
  active,
  as = 'link',
  onClick,
}: {
  genre: Genre
  active?: boolean
  as?: 'link' | 'button' | 'static'
  onClick?: () => void
}) {
  const cls = cx(
    'inline-flex items-center rounded-full border px-3 py-1 text-xs font-medium transition-colors',
    active
      ? 'border-accent bg-accent text-white'
      : 'border-line-strong bg-paper text-ink-soft hover:border-ink hover:text-ink',
  )
  if (as === 'button') {
    return (
      <button type="button" onClick={onClick} className={cls}>
        {genre}
      </button>
    )
  }
  if (as === 'static') {
    return <span className={cls}>{genre}</span>
  }
  return (
    <a
      href={genreHref(genre)}
      onClick={(e) => {
        if (e.metaKey || e.ctrlKey) return
        e.preventDefault()
        navigate(genreHref(genre))
      }}
      className={cls}
    >
      {genre}
    </a>
  )
}

/* ---------------- Star rating (display + interactive) ---------------- */
export function StarRating({
  value,
  size = 16,
  className,
  onRate,
}: {
  value: number
  size?: number
  className?: string
  onRate?: (v: number) => void
}) {
  const interactive = !!onRate
  return (
    <div className={cx('inline-flex items-center gap-0.5', className)}>
      {[1, 2, 3, 4, 5].map((i) => {
        const filled = value >= i - 0.25
        const half = !filled && value >= i - 0.75
        const star = (
          <Star
            width={size}
            height={size}
            className={cx(
              filled ? 'fill-accent text-accent' : half ? 'fill-accent/40 text-accent' : 'fill-transparent text-line-strong',
            )}
          />
        )
        if (interactive) {
          return (
            <button
              key={i}
              type="button"
              onClick={() => onRate!(i)}
              className="transition-transform hover:scale-110"
              aria-label={`Rate ${i} of 5`}
            >
              {star}
            </button>
          )
        }
        return <span key={i}>{star}</span>
      })}
    </div>
  )
}

/* ---------------- Section header ---------------- */
export function SectionHeader({
  eyebrow,
  title,
  action,
  onAction,
  actionHref,
}: {
  eyebrow?: string
  title: ReactNode
  action?: string
  onAction?: () => void
  actionHref?: string
}) {
  return (
    <div className="mb-5 flex items-end justify-between gap-4">
      <div>
        {eyebrow && <div className="eyebrow mb-1.5 text-accent">{eyebrow}</div>}
        <h2 className="text-2xl font-extrabold tracking-tight sm:text-[1.75rem]">{title}</h2>
      </div>
      {action && (
        <a
          href={actionHref ?? '#'}
          onClick={(e) => {
            if (e.metaKey || e.ctrlKey) return
            e.preventDefault()
            onAction?.()
          }}
          className="group inline-flex shrink-0 items-center gap-1 whitespace-nowrap text-sm font-semibold text-ink-soft transition-colors hover:text-accent"
        >
          {action}
          <span className="transition-transform group-hover:translate-x-0.5">→</span>
        </a>
      )}
    </div>
  )
}

/* ---------------- Buttons ---------------- */
type BtnProps = {
  children: ReactNode
  onClick?: () => void
  href?: string
  variant?: 'solid' | 'accent' | 'outline' | 'ghost'
  size?: 'sm' | 'md' | 'lg'
  className?: string
  icon?: ReactNode
  full?: boolean
  type?: 'button' | 'submit'
}

export function Button({
  children,
  onClick,
  href,
  variant = 'solid',
  size = 'md',
  className,
  icon,
  full,
  type = 'button',
}: BtnProps) {
  const sizes = {
    sm: 'h-9 px-3.5 text-sm gap-1.5',
    md: 'h-11 px-5 text-sm gap-2',
    lg: 'h-12 px-6 text-base gap-2',
  }
  const variants = {
    solid: 'bg-ink text-paper hover:bg-accent hover:text-white',
    // orange CTA — identical in light and dark themes (bg-ink flips LIGHT in
    // dark mode; combining the solid variant with a bg-accent className made
    // bg-ink win and rendered white-on-white buttons in dark mode)
    accent: 'bg-accent text-white hover:bg-accent-dark hover:text-white',
    outline: 'border border-ink/25 text-ink hover:border-ink hover:bg-ink hover:text-paper',
    ghost: 'text-ink hover:bg-ink/5',
  }
  const cls = cx(
    'inline-flex items-center justify-center rounded-full font-semibold transition-all duration-200 active:scale-[0.98]',
    sizes[size],
    variants[variant],
    full && 'w-full',
    className,
  )
  if (href) {
    return (
      <a
        href={href}
        onClick={(e) => {
          if (href.startsWith('/') && !e.metaKey && !e.ctrlKey && !e.shiftKey && e.button === 0) {
            e.preventDefault()
            navigate(href)
          }
        }}
        className={cls}
      >
        {icon}
        {children}
      </a>
    )
  }
  return (
    <button type={type} onClick={onClick} className={cls}>
      {icon}
      {children}
    </button>
  )
}

/* ---------------- Stat tile ---------------- */
export function Stat({
  label,
  value,
  hint,
}: {
  label: string
  value: ReactNode
  hint?: string
}) {
  return (
    <div className="rounded-[14px] border border-line bg-paper px-5 py-4">
      <div className="text-[2rem] font-extrabold leading-none tracking-tight tabular-nums">
        {value}
      </div>
      <div className="mt-2 text-sm font-medium text-ink-soft">{label}</div>
      {hint && <div className="mt-0.5 text-xs text-ink-faint">{hint}</div>}
    </div>
  )
}

/* ---------------- Divider label ---------------- */
export function EyebrowRule({ children }: { children: ReactNode }) {
  return (
    <div className="flex items-center gap-3">
      <span className="eyebrow text-accent">{children}</span>
      <span className="h-px flex-1 bg-line" />
    </div>
  )
}
