/**
 * Content deny-list — client mirror of scripts/filter-content.mjs (keep the
 * two lists in sync). Filters series merged at RUNTIME from the live
 * MangaDex/AniList paths, which bypass the build-time snapshots. The
 * snapshots themselves are already filtered at scrape + prerender time.
 *
 * ponytail upgrade path: per-series manual allow-list if a legitimate title
 * is ever vetoed by the keyword rule.
 */

const BLOCKED_GENRES = new Set([
  'adult', 'adultonly', 'adultslike', 'smut', 'hentai', 'ecchi', 'mature',
  'maturecontent', 'erotica', 'erotic', 'sexual', 'sex', 'sexualcontent',
  '18', '18plus', 'r18', 'nude', 'nudity', 'porn', 'pornographic',
  'yaoi', 'yuri', 'boyslove', 'girlslove', 'bl', 'gl', 'bara', 'lily',
  'josei', 'seinen',
])

const BLOCKED_TITLE = /\b(hentai|netorare|\bntr\b|pornographic|xxx)\b/i

/** Structural subset of Series so the filter never needs a type import. */
interface Blockable {
  genres?: string[]
  title?: string
  altTitles?: string[]
}

export function isBlockedSeries(s: Blockable | null | undefined): boolean {
  if (!s) return false
  if (Array.isArray(s.genres) && s.genres.some((g) => BLOCKED_GENRES.has(String(g ?? '').toLowerCase().replace(/[^a-z0-9]/g, '')))) return true
  if (BLOCKED_TITLE.test(String(s.title ?? ''))) return true
  if (Array.isArray(s.altTitles) && s.altTitles.some((t) => BLOCKED_TITLE.test(String(t ?? '')))) return true
  return false
}
