import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react'
import posthog, { isPostHogEnabled } from './posthog'

/**
 * Auth context — real accounts backed by /api/auth (Vercel edge + Blob).
 *
 * The session lives in an HttpOnly cookie, so the browser never sees the
 * token; this context just reflects who is signed in and issues the
 * register / login / logout calls. Reading data (library, progress, ratings)
 * syncs per-user via /api/user-data — see store.tsx.
 */

export interface AuthUser {
  id: string
  username: string
  email: string
}

interface AuthValue {
  user: AuthUser | null
  /** true until the initial session check resolves (avoids login-screen flash) */
  initializing: boolean
  register: (username: string, email: string, password: string) => Promise<AuthUser | string>
  login: (identifier: string, password: string) => Promise<AuthUser | string>
  logout: () => Promise<void>
}

const AuthContext = createContext<AuthValue | null>(null)

async function call(path: string, body?: unknown): Promise<{ status: number; data: any }> {
  try {
    const res = await fetch(path, {
      method: body === undefined ? 'GET' : 'POST',
      headers: body === undefined ? undefined : { 'Content-Type': 'application/json' },
      body: body === undefined ? undefined : JSON.stringify(body),
    })
    return { status: res.status, data: await res.json().catch(() => ({})) }
  } catch {
    return { status: 0, data: { error: 'Network error — please try again' } }
  }
}

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<AuthUser | null>(null)
  const [initializing, setInitializing] = useState(true)
  const identifiedUserId = useRef<string | null>(null)

  const identifyUser = useCallback((nextUser: AuthUser) => {
    if (!isPostHogEnabled || !nextUser.id) return

    if (identifiedUserId.current && identifiedUserId.current !== nextUser.id) {
      posthog.reset()
    }
    if (identifiedUserId.current === nextUser.id) return

    posthog.identify(nextUser.id, {
      email: nextUser.email,
      username: nextUser.username,
    })
    identifiedUserId.current = nextUser.id
  }, [])

  useEffect(() => {
    let alive = true
    call('/api/auth').then(({ data }) => {
      if (alive) {
        const sessionUser = data?.user as AuthUser | null
        if (sessionUser) identifyUser(sessionUser)
        setUser(sessionUser)
        setInitializing(false)
      }
    })
    return () => {
      alive = false
    }
  }, [identifyUser])

  const register = useCallback(async (username: string, email: string, password: string) => {
    const { status, data } = await call('/api/auth', {
      action: 'register',
      username,
      email,
      password,
    })
    if (status >= 400) return (data?.error as string) ?? 'Could not create the account'
    const registeredUser = data.user as AuthUser
    identifyUser(registeredUser)
    setUser(registeredUser)
    return registeredUser
  }, [identifyUser])

  const login = useCallback(async (identifier: string, password: string) => {
    const { status, data } = await call('/api/auth', { action: 'login', identifier, password })
    if (status >= 400) return (data?.error as string) ?? 'Could not sign in'
    const loggedInUser = data.user as AuthUser
    identifyUser(loggedInUser)
    setUser(loggedInUser)
    return loggedInUser
  }, [identifyUser])

  const logout = useCallback(async () => {
    await call('/api/auth', { action: 'logout' })
    if (isPostHogEnabled) posthog.reset()
    identifiedUserId.current = null
    setUser(null)
  }, [])

  const value = useMemo<AuthValue>(
    () => ({ user, initializing, register, login, logout }),
    [user, initializing, register, login, logout],
  )

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
}

export function useAuth(): AuthValue {
  const ctx = useContext(AuthContext)
  if (!ctx) throw new Error('useAuth must be used within AuthProvider')
  return ctx
}
