import { useEffect, useState, useCallback } from 'react'

export interface Route {
  path: string // e.g. "/series/the-glass-monarch"
  segments: string[] // ["series", "the-glass-monarch"]
  query: URLSearchParams
}

function parse(): Route {
  const path = window.location.pathname || '/'
  const segments = path.split('/').filter(Boolean)
  return { path, segments, query: new URLSearchParams(window.location.search) }
}

export function useRoute(): Route {
  const [route, setRoute] = useState<Route>(parse)
  useEffect(() => {
    const onChange = () => setRoute(parse())
    window.addEventListener('popstate', onChange)
    return () => window.removeEventListener('popstate', onChange)
  }, [])
  return route
}

export function navigate(to: string, opts?: { replace?: boolean; scroll?: boolean }) {
  const url = to.startsWith('/') ? to : '/' + to
  if (opts?.replace) {
    history.replaceState(null, '', url)
  } else {
    history.pushState(null, '', url)
  }
  // pushState/replaceState don't fire popstate — notify listeners manually.
  window.dispatchEvent(new PopStateEvent('popstate'))
  if (opts?.scroll !== false) {
    window.scrollTo({ top: 0, behavior: 'auto' })
  }
}

/** Absolute URL for the current or a given path — used by Share. */
export function absoluteUrl(to: string): string {
  const url = to.startsWith('/') ? to : '/' + to
  return `${window.location.origin}${url}`
}

/**
 * Legacy hash URLs (#/series/...) → real paths. Runs once on startup so old
 * bookmarks/shared links keep working after the move off hash routing.
 */
export function migrateLegacyHash() {
  const hash = window.location.hash
  if (hash.startsWith('#/')) {
    const target = hash.slice(1)
    history.replaceState(null, '', target)
    return true
  }
  return false
}

/** Convenience: click handler that navigates while allowing modifier-clicks. */
export function useLink() {
  return useCallback((to: string) => (e: React.MouseEvent) => {
    if (e.metaKey || e.ctrlKey || e.shiftKey || e.button !== 0) return
    e.preventDefault()
    navigate(to)
  }, [])
}
