import { Compass } from 'lucide-react'
import { Button } from '../components/ui'
import { navigate } from '../lib/router'
import { useCatalog } from '../lib/catalog-context'
import { trending } from '../lib/selectors'
import { SeriesCard } from '../components/SeriesCard'

export default function NotFound() {
  const { series, loading } = useCatalog()
  const suggestions = loading ? [] : trending(series, 5)
  return (
    <main className="mx-auto max-w-[1240px] animate-fade-up px-4 py-20 text-center sm:px-6 lg:px-8">
      <div className="mx-auto grid h-16 w-16 place-items-center rounded-full bg-[#181817] text-[#F7F6F2]">
        <Compass width={26} height={26} />
      </div>
      <div className="mt-6 text-6xl font-extrabold tracking-tight text-ink/10">404</div>
      <h1 className="-mt-6 text-3xl font-extrabold tracking-tight">This page wandered off.</h1>
      <p className="mx-auto mt-3 max-w-md text-ink-soft">
        The requested manhwa title may have been moved or unpublished.
      </p>
      <div className="mt-7 flex flex-wrap justify-center gap-3">
        <Button onClick={() => navigate('/')}>Back to Home</Button>
        <Button variant="outline" onClick={() => navigate('/catalog')}>
          Browse Catalog
        </Button>
      </div>

      {!loading && suggestions.length > 0 && (
        <section className="mt-16 text-left">
          <div className="eyebrow mb-5 text-center text-accent">Popular right now</div>
          <div className="grid grid-cols-2 gap-x-5 gap-y-8 sm:grid-cols-3 lg:grid-cols-5">
            {suggestions.map((s) => (
              <SeriesCard key={s.id} series={s} />
            ))}
          </div>
        </section>
      )}
    </main>
  )
}
