function makeChapters(seed: Seed): Chapter[] {
  const rand = seededRandom('ch:' + seed.title)
  const count = seed.chapters
  const latest = NOW - seed.recencyDays * DAY
  const chapters: Chapter[] = []
  // Average cadence: weekly, with slight jitter.
  for (let i = count; i >= 1; i--) {
    const stepsBack = count - i
    const jitter = Math.floor((rand() - 0.5) * 2 * DAY)
    const release = latest - stepsBack * 7 * DAY + jitter
    let title: string
    if (i === 1) {
      title = 'Prologue: The Journey Begins'
    } else {
      const a = CHAPTER_TITLE_A[Math.floor(rand() * CHAPTER_TITLE_A.length)]
      const b = CHAPTER_TITLE_B[Math.floor(rand() * CHAPTER_TITLE_B.length)]
      title = `${a} ${b}`
    }
    chapters.push({
      id: `${slugify(seed.title)}-ch-${i}`,
      number: i,
      title,
      releaseDate: new Date(release).toISOString(),
      pageCount: 38 + Math.floor(rand() * 40),
    })
  }
  // ascending by number
  return chapters.sort((a, b) => a.number - b.number)
}

function build(seed: Seed): Series {
  const slug = slugify(seed.title)
  const chapters = makeChapters(seed)
  const firstReleased = chapters[0]?.releaseDate ?? new Date(NOW - seed.ageDays * DAY).toISOString()
  const lastUpdated =
    chapters[chapters.length - 1]?.releaseDate ?? new Date(NOW - seed.recencyDays * DAY).toISOString()
  return {
    id: slug,
    slug,
    title: seed.title,
    author: seed.author,
    artist: seed.artist,
    studio: seed.studio,
    genres: seed.genres,
    status: seed.status,
    rating: seed.rating,
    ratingCount: seed.ratingCount,
    views: seed.views,
    weeklyViews: seed.weeklyViews,
    synopsis: seed.synopsis,
    schedule: seed.schedule,
    firstReleased,
    lastUpdated,
    featured: seed.featured,
    staffPick: seed.staffPick,
    chapters,
    hue: seed.hue,
    accentHue: seed.accentHue,
  }
}

export const CATALOG: Series[] = SEEDS.map(build)

export const SERIES_BY_SLUG: Record<string, Series> = Object.fromEntries(
  CATALOG.map((s) => [s.slug, s]),
)

export function getSeries(slug: string): Series | undefined {
  return SERIES_BY_SLUG[slug]
}

export function totalChapters(): number {
  return CATALOG.reduce((sum, s) => sum + s.chapters.length, 0)
}
