import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react'
import type {
  ChapterRating,
  Preferences,
  ReaderAtmosphere,
  ReaderWidth,
  ReadingProgress,
  SiteTheme,
} from '../types'
import { useAuth } from './auth'
import posthog, { isPostHogEnabled } from './posthog'

const LS = {
  library: 'manhwas:library',
  progress: 'manhwas:progress',
  ratings: 'manhwas:ratings',
  prefs: 'manhwas:prefs',
}

function read<T>(key: string, fallback: T): T {
  try {
    const raw = localStorage.getItem(key)
    return raw ? (JSON.parse(raw) as T) : fallback
  } catch {
    return fallback
  }
}

function write(key: string, value: unknown) {
  try {
    localStorage.setItem(key, JSON.stringify(value))
  } catch {
    /* storage full / unavailable — non-fatal */
  }
}

export interface Toast {
  id: number
  message: string
  tone: 'default' | 'accent'
}

interface StoreValue {
  // library
  library: string[]
  inLibrary: (seriesId: string) => boolean
  toggleLibrary: (seriesId: string, title?: string) => void
  // reading progress
  progress: Record<string, ReadingProgress>
  setProgress: (p: ReadingProgress) => void
  // ratings
  ratings: Record<string, number>
  rateChapter: (chapterId: string, value: number, trackChapterRating?: boolean) => void
  // preferences
  prefs: Preferences
  theme: SiteTheme
  setTheme: (t: SiteTheme) => void
  toggleTheme: () => void
  setAtmosphere: (a: ReaderAtmosphere) => void
  setWidth: (w: ReaderWidth) => void
  setNotifyOnDrop: (v: boolean) => void
  // toasts
  toasts: Toast[]
  toast: (message: string, tone?: Toast['tone']) => void
  dismissToast: (id: number) => void
}

const StoreContext = createContext<StoreValue | null>(null)

const DEFAULT_PREFS: Preferences = {
  theme: 'light',
  atmosphere: 'light',
  width: 'standard',
  notifyOnDrop: true,
}

export function StoreProvider({ children }: { children: ReactNode }) {
  const { user } = useAuth()
  const [library, setLibrary] = useState<string[]>(() => read(LS.library, []))
  const [progress, setProgressState] = useState<Record<string, ReadingProgress>>(() =>
    read(LS.progress, {}),
  )
  const [ratings, setRatings] = useState<Record<string, number>>(() => read(LS.ratings, {}))
  const [prefs, setPrefs] = useState<Preferences>(() => ({
    ...DEFAULT_PREFS,
    ...read(LS.prefs, DEFAULT_PREFS),
  }))
  const [toasts, setToasts] = useState<Toast[]>([])
  const toastId = useRef(0)

  // ---- cloud sync (signed-in users) ------------------------------------
  // On sign-in: pull the account's data and merge it into whatever this
  // device already has (union of libraries, newest progress per series,
  // local ratings win on conflict). Afterwards every change is pushed
  // (debounced) to /api/user-data, so each account's bookmarks/progress are
  // private to it and follow it across devices.
  const syncedUserId = useRef<string | null>(null)
  const skipPush = useRef(true)
  const pushTimer = useRef<number | undefined>(undefined)
  // bumped when a sign-in sync settles, so the push effect runs once even if
  // the merge changed nothing (e.g. brand-new account with local data to upload)
  const [syncEpoch, setSyncEpoch] = useState(0)

  useEffect(() => {
    if (!user) {
      syncedUserId.current = null
      skipPush.current = true
      return
    }
    if (syncedUserId.current === user.id) return
    syncedUserId.current = user.id
    let alive = true
    ;(async () => {
      try {
        const res = await fetch('/api/user-data')
        if (res.ok && alive) {
          const remote = (await res.json()) as {
            library?: string[]
            progress?: Record<string, ReadingProgress>
            ratings?: Record<string, number>
          }
          if (remote.library?.length || remote.progress || remote.ratings) {
            setLibrary((cur) => [...new Set([...(remote.library ?? []), ...cur])])
            setProgressState((cur) => {
              const merged: Record<string, ReadingProgress> = { ...(remote.progress ?? {}) }
              for (const [k, v] of Object.entries(cur)) {
                const r = merged[k]
                if (!r || v.updatedAt >= r.updatedAt) merged[k] = v
              }
              return merged
            })
            setRatings((cur) => ({ ...(remote.ratings ?? {}), ...cur }))
          }
        }
      } catch {
        /* offline — local data stays */
      } finally {
        if (alive) {
          skipPush.current = false
          setSyncEpoch((e) => e + 1)
        }
      }
    })()
    return () => {
      alive = false
    }
  }, [user])

  useEffect(() => {
    if (!user || skipPush.current) return
    window.clearTimeout(pushTimer.current)
    pushTimer.current = window.setTimeout(() => {
      fetch('/api/user-data', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ library, progress, ratings }),
      }).catch(() => {
        /* offline — localStorage still has it; next change retries */
      })
    }, 1500)
    return () => window.clearTimeout(pushTimer.current)
  }, [library, progress, ratings, user, syncEpoch])

  useEffect(() => write(LS.library, library), [library])
  useEffect(() => write(LS.progress, progress), [progress])
  useEffect(() => write(LS.ratings, ratings), [ratings])
  useEffect(() => write(LS.prefs, prefs), [prefs])

  // Apply the site theme to <html> so CSS variables + the body background follow
  useEffect(() => {
    document.documentElement.classList.toggle('dark', prefs.theme === 'dark')
  }, [prefs.theme])

  const dismissToast = useCallback((id: number) => {
    setToasts((t) => t.filter((x) => x.id !== id))
  }, [])

  const toast = useCallback(
    (message: string, tone: Toast['tone'] = 'default') => {
      const id = ++toastId.current
      setToasts((t) => [...t, { id, message, tone }])
      window.setTimeout(() => dismissToast(id), 2600)
    },
    [dismissToast],
  )

  const inLibrary = useCallback((seriesId: string) => library.includes(seriesId), [library])

  const toggleLibrary = useCallback(
    (seriesId: string, title?: string) => {
      const has = library.includes(seriesId)
      if (isPostHogEnabled) {
        posthog.capture(has ? 'library_item_removed' : 'library_item_added', { series_id: seriesId })
      }
      setLibrary((cur) => (has ? cur.filter((x) => x !== seriesId) : [...cur, seriesId]))
      toast(
        has ? `Removed${title ? ` “${title}”` : ''} from Library` : `Added${title ? ` “${title}”` : ''} to Library`,
        has ? 'default' : 'accent',
      )
    },
    [library, toast],
  )

  const setProgress = useCallback((p: ReadingProgress) => {
    setProgressState((cur) => ({ ...cur, [p.seriesId]: p }))
  }, [])

  const rateChapter = useCallback(
    (chapterId: string, value: number, trackChapterRating = true) => {
      if (trackChapterRating && isPostHogEnabled) {
        posthog.capture('chapter_rated', { chapter_id: chapterId, rating: value })
      }
      setRatings((cur) => ({ ...cur, [chapterId]: value }))
      toast('Rating recorded.', 'accent')
    },
    [toast],
  )

  const setTheme = useCallback((theme: SiteTheme) => {
    setPrefs((p) => ({ ...p, theme }))
  }, [])

  const toggleTheme = useCallback(() => {
    setPrefs((p) => ({ ...p, theme: p.theme === 'dark' ? 'light' : 'dark' }))
  }, [])

  const setAtmosphere = useCallback(
    (atmosphere: ReaderAtmosphere) => {
      setPrefs((p) => ({ ...p, atmosphere }))
      toast(
        `Reader atmosphere set to ${atmosphere === 'dark' ? 'Onyx Dark' : 'Editorial Light'}`,
      )
    },
    [toast],
  )

  const setWidth = useCallback((width: ReaderWidth) => {
    setPrefs((p) => ({ ...p, width }))
  }, [])

  const setNotifyOnDrop = useCallback((notifyOnDrop: boolean) => {
    setPrefs((p) => ({ ...p, notifyOnDrop }))
  }, [])

  const value = useMemo<StoreValue>(
    () => ({
      library,
      inLibrary,
      toggleLibrary,
      progress,
      setProgress,
      ratings,
      rateChapter,
      prefs,
      theme: prefs.theme,
      setTheme,
      toggleTheme,
      setAtmosphere,
      setWidth,
      setNotifyOnDrop,
      toasts,
      toast,
      dismissToast,
    }),
    [
      library,
      inLibrary,
      toggleLibrary,
      progress,
      setProgress,
      ratings,
      rateChapter,
      prefs,
      setTheme,
      toggleTheme,
      setAtmosphere,
      setWidth,
      setNotifyOnDrop,
      toasts,
      toast,
      dismissToast,
    ],
  )

  return <StoreContext.Provider value={value}>{children}</StoreContext.Provider>
}

export function useStore(): StoreValue {
  const ctx = useContext(StoreContext)
  if (!ctx) throw new Error('useStore must be used within StoreProvider')
  return ctx
}
