import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react'
import type { Series } from '../types'
import { CATALOG as LOCAL_CATALOG } from '../data/catalog'
import { decodeEntities, slugify, fetchCdnJson } from './utils'
import { isBlockedSeries } from './contentFilter'
import { fetchJsonOffThread } from './json-worker'
import { posthogLogger } from './posthog-logger'
import { fetchCatalog as fetchAniListCatalog, fetchAniListTrending, fetchSeriesBySlug, searchAniList } from './anilist'
import {
  fetchMangaDexCatalog,
  fetchMangaDexSeries,
  searchMangaDex,
  bridgeToMangaDex,
  isMangaDexSeries,
} from './mangadex'

type Source = 'mangadex' | 'anilist' | 'local'

const REFRESH_INTERVAL = 3 * 60 * 60 * 1000 // silent refresh every 3h while open
const STALE_FOCUS = 30 * 60 * 1000 // refetch on focus if last load > 30min ago

interface CatalogValue {
  /** Full loaded series list — every entry has real readable chapters. */
  series: Series[]
  loading: boolean
  source: Source
  /**
   * true while the heavy snapshots (full MangaDex + MangaKatana meta) are
   * still downloading. Deep links to a title slug can only resolve from
   * snapshot data, so callers keep unresolved slugs in the loading state
   * until this flips false instead of flashing "not found".
   */
  hydrating: boolean
  /**
   * true once the fast catalog data has merged: the top-tier snapshot
   * (~1.5MB) or any fallback (live load / AniList / local). The deferred
   * full MangaDex snapshot (~6.5MB, idle-loaded long tail) is NOT awaited —
   * sections that draw from the popular head of the catalog (Trending,
   * Latest Updates) can render on this instead of waiting for `hydrating`.
   * Sticky: once true it never flips back during background refreshes.
   */
  coreReady: boolean
  /** Lookup by slug across the loaded list. */
  bySlug: (slug: string) => Series | undefined
  /** Load a single series by slug — fetches from the live APIs on miss. */
  loadSeries: (slug: string) => Promise<Series | null>
  /** Live search across the current source; local filtering when offline. */
  search: (q: string) => Promise<Series[]>
  /** Trigger a silent background refresh of the live catalog. */
  refresh: () => void
}

const CatalogContext = createContext<CatalogValue | null>(null)

function normTitle(s: unknown): string {
  return String(s ?? '').toLowerCase().replace(/[^a-z0-9]+/g, '')
}

/**
 * Key variants of a title: as-is, without parenthetical/bracket suffixes
 * ("(Remake)", "(2022)", "(Webtoon Version)"), and without a leading article.
 * "The Emperor's Sword" and "Emperor's Sword" are the same work; keys are
 * additive so distinct titles stay distinct.
 */
function titleVariants(t: string): string[] {
  const out = [t]
  const noParen = t.replace(/\s*[([{][^)\]}]*[)\]}]\s*/g, ' ').trim()
  if (noParen && noParen !== t) out.push(noParen)
  for (const base of [...out]) {
    const noArticle = base.replace(/^(the|a|an)\s+/i, '').trim()
    if (noArticle && noArticle !== base) out.push(noArticle)
  }
  return out
}

/**
 * Match keys for a series: normalized main title + alt titles. The same work
 * often carries different display titles per source (md "The Patron of
 * Villains" vs mk "Raising Villains the Right Way"), so main-title matching
 * alone misses pairs — the alt titles are where they meet. Titles are
 * entity-decoded first (scraped "&eacute;" would poison the key) and each
 * article/parenthetical variant contributes keys. Keys shorter than
 * 4 chars are skipped: short generic alt strings collide across unrelated
 * works.
 *
 * Memoized per series object: collapseTitles runs on every merge batch and
 * recomputes keys for the whole list twice per call — on a phone that's
 * tens of thousands of redundant regex computations per session.
 */
const titleKeysCache = new WeakMap<Series, string[]>()

function titleKeys(s: Series): string[] {
  const cached = titleKeysCache.get(s)
  if (cached) return cached
  const keys = new Set<string>()
  for (const raw of [s.title, ...(s.altTitles ?? [])]) {
    for (const variant of titleVariants(decodeEntities(String(raw ?? '')))) {
      const k = normTitle(variant)
      if (k.length >= 4) keys.add(k)
    }
  }
  const out = [...keys]
  titleKeysCache.set(s, out)
  return out
}

/**
 * Collapse same-work series to the richest entry. Entries are grouped by ANY
 * matching main/alt title (union-find over titleKeys) — the same work can
 * exist on MangaDex and MangaKatana under different display titles (e.g.
 * licensed-away titles keep only a few readable chapters on MangaDex while
 * MangaKatana carries the full run under another name), and showing both
 * would list the work twice. The group entry with more chapters wins; ties
 * favor MangaDex (live-revalidated).
 */
function collapseTitles(input: Series[]): Series[] {
  // content deny-list chokepoint: EVERY runtime merge funnels through here
  // (snapshot batches, live MangaDex loads, AniList hybrids) — so even a
  // blocked series that slipped past the scrape-time filter can never enter
  // the running catalog. Mirrors the build-time filter in
  // scripts/filter-content.mjs.
  const list = input.filter((s) => !isBlockedSeries(s))
  // union-find over title keys
  const parent = new Map<string, string>()
  const find = (k: string): string => {
    let r = k
    while (parent.get(r) !== r) r = parent.get(r)!
    for (let c = k; parent.get(c) !== c; ) {
      const next = parent.get(c)!
      parent.set(c, r)
      c = next
    }
    return r
  }
  const keyless: Series[] = []
  for (const s of list) {
    const keys = titleKeys(s)
    if (!keys.length) {
      keyless.push(s)
      continue
    }
    for (const k of keys) if (!parent.has(k)) parent.set(k, k)
    const root = find(keys[0])
    for (const k of keys.slice(1)) {
      const rk = find(k)
      if (rk !== root) parent.set(rk, root)
    }
  }
  const best = new Map<string, Series>()
  for (const s of list) {
    const keys = titleKeys(s)
    if (!keys.length) continue
    const root = find(keys[0])
    const cur = best.get(root)
    if (!cur) {
      best.set(root, s)
      continue
    }
    const wins =
      (s.chapters?.length ?? 0) > (cur.chapters?.length ?? 0) ||
      ((s.chapters?.length ?? 0) === (cur.chapters?.length ?? 0) && isMangaDexSeries(s) && !isMangaDexSeries(cur))
    if (wins) best.set(root, s)
  }
  // §30: when an MD entry wins a group, remember the losing MK twin's slug
  // (mkTwinSlug). The MD feed of licensed titles only hosts a RECENT window
  // (Lookism: 25 chapters ending 612) while MK carries the full run (→626) —
  // useRealChapters unions that twin's ground truth by chapter number so the
  // newest chapters never fall off the reader. Losers are still removed from
  // the list (no duplicate cards); only their slug survives, on the winner.
  for (const s of list) {
    if (!s.slug.startsWith('mk-')) continue
    const keys = titleKeys(s)
    if (!keys.length) continue
    const root = find(keys[0])
    const winner = best.get(root)
    if (winner && isMangaDexSeries(winner)) {
      winner.mkTwinSlug = winner.mkTwinSlug ?? s.slug
    }
  }
  return [...best.values(), ...keyless]
}

/** Merge series lists, deduping by slug and preferring existing entries. */
function mergeSeries(prev: Series[], next: Series[]): Series[] {
  const seen = new Set(prev.map((s) => s.slug))
  return collapseTitles([...prev, ...next.filter((s) => !seen.has(s.slug))])
}

export function CatalogProvider({ children }: { children: ReactNode }) {
  const [series, setSeries] = useState<Series[]>([])
  const [loading, setLoading] = useState(true)
  const [hydrating, setHydrating] = useState(true)
  const [coreReady, setCoreReady] = useState(false)
  const [source, setSource] = useState<Source>('local')
  const seriesRef = useRef<Series[]>([])
  const lastLoadRef = useRef(0)
  const loadingRef = useRef(false)
  const hasLoggedInitialCatalogRef = useRef(false)

  seriesRef.current = series

  // Sticky "fast data has landed" flag: any real series list with the
  // initial loading phase over is enough for the homepage sections. Covers
  // every path — snapshot merges, the live-load fallback, AniList/local
  // fallbacks, and silent refreshes (which never set loading=true).
  useEffect(() => {
    if (series.length && !loading) setCoreReady(true)
  }, [series.length, loading])

  useEffect(() => {
    if (!coreReady || hasLoggedInitialCatalogRef.current) return
    hasLoggedInitialCatalogRef.current = true
    posthogLogger.info('catalog_initial_load_completed', {
      catalog_source: source,
      series_count: series.length,
    })
  }, [coreReady, source, series.length])

  /** Widen the catalog with AniList-trending titles that are readable on MangaDex. */
  const mergeAniListTrending = useCallback(async () => {
    try {
      const trending = await fetchAniListTrending(30)
      const existing = new Set(seriesRef.current.map((s) => normTitle(s.title)))
      const candidates = trending.filter((t) => !existing.has(normTitle(t.title)))
      let added: Series[] = []
      for (const al of candidates) {
        const bridged = await bridgeToMangaDex(al).catch(() => null)
        if (!bridged) continue
        // hybrid: AniList metadata + real MangaDex chapters
        const hybrid: Series = {
          ...al,
          id: `md-${bridged.mangaId}`,
          slug: `md-${bridged.mangaId}`,
          chapters: bridged.chapters,
          studio: 'MANHWAS Originals',
        }
        added.push(hybrid)
        if (added.length >= 4) {
          const batch = added
          added = []
          setSeries((prev) => mergeSeries(prev, batch))
        }
      }
      if (added.length) setSeries((prev) => mergeSeries(prev, added))
    } catch {
      /* enrichment is best-effort */
    }
  }, [])

  /** Load the live MangaDex catalog progressively; AniList/local as fallback. */
  const runLoad = useCallback(
    (silent: boolean) => {
      if (loadingRef.current) return
      loadingRef.current = true
      if (!silent) setLoading(true)

      fetchMangaDexCatalog({
        onBatch: (batch) => {
          setSeries((prev) => mergeSeries(prev, batch))
          setSource('mangadex')
          setLoading(false)
        },
        onComplete: (full) => {
          // authoritative live list, keeping any extra titles already shown
          // (snapshot-only series + AniList·MangaDex hybrids), then collapse
          // same-title duplicates so a partially-readable MangaDex entry
          // never shadows the full MangaKatana one or vice versa
          setSeries((prev) => {
            const slugs = new Set(full.map((s) => s.slug))
            const extras = prev.filter((s) => !slugs.has(s.slug))
            return collapseTitles([...full, ...extras])
          })
          setSource('mangadex')
          setLoading(false)
          setHydrating(false)
          lastLoadRef.current = Date.now()
          loadingRef.current = false
          void mergeAniListTrending()
        },
      }).catch(async () => {
        loadingRef.current = false
        lastLoadRef.current = Date.now()
        if (silent && seriesRef.current.length) return // keep whatever we already have
        // fallback catalogs replace the MangaDex list, but never evict the
        // MangaKatana snapshot titles merged in earlier
        const keepMk = (prev: Series[]) => prev.filter((s) => s.slug.startsWith('mk-'))
        try {
          const al = await fetchAniListCatalog()
          if (al.length) {
            setSeries((prev) => collapseTitles([...al, ...keepMk(prev)]))
            setSource('anilist')
          } else {
            setSeries((prev) => collapseTitles([...LOCAL_CATALOG, ...keepMk(prev)]))
          }
        } catch {
          setSeries((prev) => collapseTitles([...LOCAL_CATALOG, ...keepMk(prev)]))
        } finally {
          setLoading(false)
          setHydrating(false)
        }
      })
    },
    [mergeAniListTrending],
  )

  /** Refresh from the static snapshots — cheap CDN revalidations, not a live
   * MangaDex scan. Incoming md/mk entries replace old snapshot objects;
   * AniList/local extras are preserved, then the same-work collapse runs. */
  const refreshSnapshots = useCallback(async () => {
    // off-thread parse — the snapshots are multi-MB JSON and a main-thread
    // parse froze phones for seconds mid-session
    const get = (path: string) => fetchJsonOffThread<{ series?: Series[] }>(path)
    const [top, full, mkMeta] = await Promise.all([
      get('/catalog.json'),
      get('/catalog-full.json'),
      get('/catalog-mk-meta.json'),
    ])
    let mk = mkMeta
    if (!mk?.series?.length) {
      // 'no-cache' — see fetchCdnJson: the zone's 4h browser TTL override
      // must not freeze the catalogue between refreshes
      mk = await fetch('/catalog-mk.json', { cache: 'no-cache' })
        .then((r) => (r.ok ? r.json() : null))
        .catch(() => null)
    }
    const incoming = [top, full, mk]
      .flatMap((x) => (Array.isArray(x?.series) ? (x.series as Series[]) : []))
    if (!incoming.length) return
    setSeries((prev) => {
      const extras = prev.filter((s) => !s.slug.startsWith('md-') && !s.slug.startsWith('mk-'))
      return collapseTitles([...incoming, ...extras])
    })
    setSource('mangadex')
    setLoading(false)
    lastLoadRef.current = Date.now()
    posthogLogger.info('catalog_snapshot_refresh_completed', {
      catalog_source: 'mangadex',
      snapshot_series_count: incoming.length,
    })
  }, [])

  // Initial load: instant bootstrap from the prebuilt snapshot (top tier),
  // then the full catalog. The heavy snapshots start off the critical path
  // (the MangaKatana meta is ~2MB gzipped vs ~5MB for the old full file, the
  // MangaDex full file is deferred to idle) so phones paint and can read
  // before tens of megabytes of JSON have downloaded.
  useEffect(() => {
    let cancelled = false
    let snapshotFound = false

    /** Run once the first paint has settled — keeps big fetches from
     * contending with JS/fonts/first-render on slow connections. */
    const whenIdle = (fn: () => void, timeout = 2000) => {
      const ric = (window as { requestIdleCallback?: (cb: () => void, opts?: { timeout: number }) => number })
        .requestIdleCallback
      if (ric) ric(fn, { timeout })
      else setTimeout(fn, 0)
    }

    const settle = () => {
      if (!cancelled) setHydrating(false)
    }

    // 1. snapshot (committed by the catalog automation) → instant first paint
    const topPromise = fetchJsonOffThread<{ series?: Series[] }>('/catalog.json')
      .then((snap) => {
        if (cancelled || !snap?.series?.length) return
        snapshotFound = true
        setSeries((prev) => mergeSeries(prev, snap.series as Series[]))
        setSource('mangadex')
        setLoading(false)
      })
      .catch(() => {
        /* snapshot optional */
      })

    // 2. MangaKatana snapshot — the compact meta variant (every mk series
    // with a recent chapter window; the reader fetches the full lists
    // per series from /mk-chapters/{slug}.json). Falls back to the full
    // snapshot when the build hasn't generated it (dev server).
    const mkPromise = fetchJsonOffThread<{ series?: Series[] }>('/catalog-mk-meta.json')
      .then(async (snap) => {
        if (snap?.series?.length) return snap
        // fallback: full snapshot (dev, or a deploy without the split build)
        return fetch('/catalog-mk.json', { cache: 'no-cache' })
          .then((r) => (r.ok ? (r.json() as Promise<{ series?: Series[] } | null>) : null))
          .catch(() => null)
      })
      .then((snap) => {
        if (cancelled || !snap?.series?.length) return
        snapshotFound = true
        // its chapters carry chapterPath in the full variant, so the reader
        // fetches their pages through /api/mk
        setSeries((prev) => mergeSeries(prev, snap.series as Series[]))
      })

    // 2b. full MangaDex snapshot — the complete md catalog (long tail beyond
    // the top-200 the live load brings). Deferred until the mk snapshot has
    // settled AND the main thread goes idle with a generous timeout: it's
    // ~6.7MB raw and nothing on the first screen needs it, so its parse
    // must never compete with first paint, the mk merge or the hero image
    // (fetching it early cost ~2s of Lighthouse mobile LCP).
    const fullPromise = mkPromise
      .catch(() => undefined)
      .then(
        () =>
          new Promise<void>((resolve) => {
            whenIdle(() => {
              fetchJsonOffThread<{ series?: Series[] }>('/catalog-full.json')
                .then((snap) => {
                  if (!cancelled && snap?.series?.length) {
                    snapshotFound = true
                    setSeries((prev) => mergeSeries(prev, snap.series as Series[]))
                  }
                })
                .catch(() => {
                  /* full snapshot optional */
                })
                .finally(resolve)
            }, 10_000)
          }),
      )

    // The six-hourly GitHub workflow already does the expensive live MangaDex
    // scan once for everybody. Normal visitors use those snapshots — do NOT
    // repeat dozens of /api/md function calls per page view. The live loader
    // remains below as an emergency fallback only when every snapshot failed.
    Promise.allSettled([topPromise, mkPromise, fullPromise]).then(() => {
      if (cancelled) return
      if (!snapshotFound) runLoad(false)
      else {
        lastLoadRef.current = Date.now()
        // any snapshot success is real data — clear the first-paint gate even
        // when only the later snapshots landed (the top tier alone used to
        // own setLoading(false), stranding the homepage skeleton forever)
        setLoading(false)
        settle()
      }
    })

    return () => {
      cancelled = true
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // Automation: revalidate the static snapshots every few hours and on focus.
  // The six-hourly GitHub workflow owns live catalog generation; browsers only
  // fetch its CDN artifacts, eliminating the per-visitor function/API storm.
  useEffect(() => {
    const interval = setInterval(() => void refreshSnapshots(), REFRESH_INTERVAL)
    const onFocus = () => {
      if (Date.now() - lastLoadRef.current > STALE_FOCUS) void refreshSnapshots()
    }
    window.addEventListener('focus', onFocus)
    return () => {
      clearInterval(interval)
      window.removeEventListener('focus', onFocus)
    }
  }, [refreshSnapshots])

  // Index by internal slug AND readable title slug so URLs like
  // /manhwa/who-made-me-a-princess resolve as well as legacy /manhwa/md-…
  const index = useMemo(() => {
    const map = new Map<string, Series>()
    for (const s of series) {
      map.set(s.slug, s)
      const t = slugify(s.title ?? '')
      if (t) map.set(t, s)
    }
    return map
  }, [series])

  const bySlug = useCallback(
    (slug: string) =>
      index.get(slug) ??
      LOCAL_CATALOG.find((s) => s.slug === slug || slugify(s.title ?? '') === slug),
    [index],
  )

  const loadSeries = useCallback(
    async (slug: string): Promise<Series | null> => {
      const hit = bySlug(slug)
      if (hit) return hit
      if (slug.startsWith('md-')) {
        const fetched = await fetchMangaDexSeries(slug.replace(/^md-/, ''))
        if (fetched) {
          setSeries((prev) => mergeSeries(prev, [fetched]))
          // same-work swap: the collapsed catalog entry with more chapters
          // beats the raw MangaDex fetch (licensed-away titles keep only a
          // few readable chapters there — e.g. Patron of Villains: 16 vs 50)
          const keys = new Set(titleKeys(fetched))
          const better = seriesRef.current.find(
            (c) =>
              c.slug !== fetched.slug &&
              (c.chapters?.length ?? 0) > (fetched.chapters?.length ?? 0) &&
              titleKeys(c).some((k) => keys.has(k)),
          )
          return better ?? fetched
        }
        return fetched
      }
      if (slug.startsWith('al-')) {
        try {
          return await fetchSeriesBySlug(slug)
        } catch {
          return null
        }
      }
      return null
    },
    [bySlug],
  )

  const search = useCallback(
    async (q: string): Promise<Series[]> => {
      const needle = q.trim().toLowerCase()
      if (!needle) return []

      // The six-hourly snapshots already contain the complete 2,000+ title
      // catalog. Search them first — no function invocation or upstream API
      // call for normal queries. Include title aliases, creator names,
      // synopsis and genres, then rank exact/prefix title matches first.
      const local = seriesRef.current
        .filter((s) =>
          [s.title, ...(s.altTitles ?? []), s.author, s.artist, s.synopsis, ...s.genres]
            .join(' ')
            .toLowerCase()
            .includes(needle),
        )
        .sort((a, b) => {
          const at = a.title.toLowerCase()
          const bt = b.title.toLowerCase()
          const ar = at === needle ? 0 : at.startsWith(needle) ? 1 : 2
          const br = bt === needle ? 0 : bt.startsWith(needle) ? 1 : 2
          return ar - br || b.weeklyViews - a.weeklyViews
        })
        .slice(0, 30)
      if (local.length) return local

      // Emergency long-tail fallback only when the snapshots have no match.
      if (source === 'mangadex') {
        try {
          const live = await searchMangaDex(q)
          const bestByKey = new Map<string, Series>()
          for (const s of seriesRef.current) {
            for (const k of titleKeys(s)) {
              const cur = bestByKey.get(k)
              if (!cur || (s.chapters?.length ?? 0) > (cur.chapters?.length ?? 0)) bestByKey.set(k, s)
            }
          }
          return live.map((s) => {
            const better = titleKeys(s)
              .map((k) => bestByKey.get(k))
              .find((c) => c && c.slug !== s.slug && (c.chapters?.length ?? 0) > (s.chapters?.length ?? 0))
            return better ?? s
          })
        } catch {
          return []
        }
      }
      if (source === 'anilist') {
        try {
          return await searchAniList(q)
        } catch {
          return []
        }
      }
      return LOCAL_CATALOG.filter((s) =>
        [s.title, s.author, s.artist, s.synopsis, ...s.genres]
          .join(' ')
          .toLowerCase()
          .includes(needle),
      )
    },
    [source],
  )

  const refresh = useCallback(() => void refreshSnapshots(), [refreshSnapshots])

  const value = useMemo<CatalogValue>(
    () => ({ series, loading, hydrating, coreReady, source, bySlug, loadSeries, search, refresh }),
    [series, loading, hydrating, coreReady, source, bySlug, loadSeries, search, refresh],
  )

  return <CatalogContext.Provider value={value}>{children}</CatalogContext.Provider>
}

export function useCatalog(): CatalogValue {
  const ctx = useContext(CatalogContext)
  if (!ctx) throw new Error('useCatalog must be used within CatalogProvider')
  return ctx
}

/**
 * Resolve a single series by slug or readable title slug, fetching from the
 * live APIs on miss. Title slugs (not md-/mk-/al- prefixed) can only be
 * resolved against the loaded catalog, so while it's still loading we keep
 * the caller in the loading state instead of reporting "not found".
 */
export function useSeries(slug: string | undefined): { series: Series | undefined; loading: boolean } {
  const { bySlug, loadSeries, loading: catalogLoading, hydrating } = useCatalog()
  const cached = slug ? bySlug(slug) : undefined
  // internal slugs are live-fetchable; anything else is a title slug
  const isInternalSlug = !!slug && /^(md-|mk-|al-)/.test(slug)
  const [fetched, setFetched] = useState<Series | null>(null)
  const [loading, setLoading] = useState(false)

  useEffect(() => {
    if (cached || !slug) return
    let cancelled = false
    setLoading(true)
    loadSeries(slug)
      .then((s) => {
        if (!cancelled) setFetched(s)
      })
      .finally(() => {
        if (!cancelled) setLoading(false)
      })
    return () => {
      cancelled = true
    }
  }, [slug, cached, loadSeries])

  // Title slugs (and mk- internal slugs) can only resolve from snapshot
  // data — while the snapshots are still downloading (slow mobile connection)
  // keep the caller in the loading state instead of flashing "not found".
  // md-/al- internal slugs resolve live and don't need to wait.
  const waitsForSnapshot = !isInternalSlug || slug?.startsWith('mk-')
  const resolvingTitleSlug =
    !cached && waitsForSnapshot && (catalogLoading || hydrating)
  return { series: cached ?? fetched ?? undefined, loading: (loading && !cached) || resolvingTitleSlug }
}
