import { useEffect, useMemo, useRef, useState } from 'react'
import { Search, Menu, X, User, Sun, Moon } from 'lucide-react'
import { navigate, useRoute } from '../lib/router'
import { cx, seriesHref } from '../lib/utils'
import { useStore } from '../lib/store'
import { useCatalog } from '../lib/catalog-context'
import { searchLocal } from '../lib/selectors'
import posthog, { isPostHogEnabled } from '../lib/posthog'

const NAV = [
  { label: 'Discover', to: '/' },
  { label: 'Catalog', to: '/catalog' },
  { label: 'Genres', to: '/genres' },
  { label: 'Updates', to: '/updates' },
  { label: 'Rankings', to: '/rankings' },
  { label: 'Library', to: '/library' },
]

export default function Navbar() {
  const route = useRoute()
  const { library, prefs, toggleTheme } = useStore()
  const { series: catalog } = useCatalog()
  const [scrolled, setScrolled] = useState(false)
  const [menuOpen, setMenuOpen] = useState(false)
  const [q, setQ] = useState('')
  const [showSuggest, setShowSuggest] = useState(false)
  const [activeIdx, setActiveIdx] = useState(-1)
  const searchRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 8)
    onScroll()
    window.addEventListener('scroll', onScroll, { passive: true })
    return () => window.removeEventListener('scroll', onScroll)
  }, [])

  // Close mobile menu on route change
  useEffect(() => setMenuOpen(false), [route.path])

  // Keyboard shortcut: "/" focuses search
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const el = document.activeElement
      const typing = el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement
      if (e.key === '/' && !typing) {
        e.preventDefault()
        searchRef.current?.focus()
      }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [])

  const isActive = (to: string) =>
    to === '/' ? route.path === '/' : route.path.startsWith(to)

  // Typeahead suggestions — title/author matches from the loaded catalog
  // (the snapshots are complete, so this is instant, no network round trip).
  const suggestions = useMemo(() => {
    const trimmed = q.trim()
    if (trimmed.length < 1) return []
    return searchLocal(catalog, trimmed).slice(0, 6)
  }, [q, catalog])

  const pickSuggestion = (href: string) => {
    if (isPostHogEnabled) {
      posthog.capture('search_submitted', {
        query_length: q.trim().length,
        result_selected: true,
      })
    }
    setQ('')
    setShowSuggest(false)
    setActiveIdx(-1)
    searchRef.current?.blur()
    navigate(href)
  }

  const onSearchKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (!showSuggest || suggestions.length === 0) return
    if (e.key === 'ArrowDown') {
      e.preventDefault()
      setActiveIdx((i) => (i + 1) % suggestions.length)
    } else if (e.key === 'ArrowUp') {
      e.preventDefault()
      setActiveIdx((i) => (i <= 0 ? suggestions.length - 1 : i - 1))
    } else if (e.key === 'Enter' && activeIdx >= 0) {
      e.preventDefault()
      pickSuggestion(seriesHref(suggestions[activeIdx]))
    } else if (e.key === 'Escape') {
      setShowSuggest(false)
      setActiveIdx(-1)
    }
  }

  const submitSearch = (e: React.FormEvent) => {
    e.preventDefault()
    const query = q.trim()
    if (query && isPostHogEnabled) {
      posthog.capture('search_submitted', {
        query_length: query.length,
        result_selected: false,
      })
    }
    navigate(`/search?q=${encodeURIComponent(q)}`)
  }

  return (
    <header
      className={cx(
        'sticky top-0 z-50 transition-all duration-300',
        scrolled
          ? 'border-b border-line bg-paper/85 backdrop-blur-md'
          : 'border-b border-transparent bg-paper',
      )}
    >
      <div className="mx-auto flex h-16 max-w-[1240px] items-center gap-4 px-4 sm:px-6 lg:px-8">
        {/* Logo */}
        <a
          href="/"
          onClick={(e) => {
            if (e.metaKey || e.ctrlKey) return
            e.preventDefault()
            navigate('/')
          }}
          className="flex shrink-0 items-center gap-2.5"
        >
          <img
            src="/logo1.webp"
            alt="MANHWAS logo"
            width={36}
            height={36}
            decoding="async"
            className="h-9 w-9 shrink-0 rounded-md object-contain"
            draggable={false}
          />
          <span className="text-lg font-extrabold tracking-[-0.02em]">
            MANHWAS
          </span>
        </a>

        {/* Desktop nav */}
        <nav className="ml-4 hidden items-center gap-1 lg:flex">
          {NAV.map((item) => (
            <a
              key={item.to}
              href={item.to}
              onClick={(e) => {
                if (e.metaKey || e.ctrlKey) return
                e.preventDefault()
                navigate(item.to)
              }}
              className={cx(
                'relative rounded-full px-3.5 py-2 text-sm font-semibold transition-colors',
                isActive(item.to) ? 'text-ink' : 'text-ink-soft hover:text-ink',
              )}
            >
              {item.label}
              {item.label === 'Library' && library.length > 0 && (
                <span className="ml-1.5 rounded-full bg-accent px-1.5 py-0.5 text-[10px] font-bold text-white">
                  {library.length}
                </span>
              )}
              {isActive(item.to) && (
                <span className="absolute inset-x-3.5 -bottom-[1px] h-0.5 rounded-full bg-accent" />
              )}
            </a>
          ))}
        </nav>

        <div className="flex-1" />

        {/* Search (desktop) — with live typeahead suggestions */}
        <form
          onSubmit={submitSearch}
          className="relative hidden md:block"
          onBlur={() => {
            // brief delay so item clicks land before the blur closes the list
            setTimeout(() => setShowSuggest(false), 120)
          }}
        >
          <div className="group flex h-10 w-56 items-center gap-2 rounded-full border border-line-strong bg-paper px-3.5 transition-colors focus-within:border-ink lg:w-64">
            <Search width={16} height={16} className="text-ink-faint" />
            <input
              ref={searchRef}
              value={q}
              onChange={(e) => {
                setQ(e.target.value)
                setShowSuggest(true)
                setActiveIdx(-1)
              }}
              onKeyDown={onSearchKeyDown}
              onFocus={() => q.trim() && setShowSuggest(true)}
              placeholder="Search series, author, genre…"
              className="w-full bg-transparent text-sm outline-none placeholder:text-ink-faint"
              aria-label="Search series"
              autoComplete="off"
            />
            <kbd className="hidden rounded border border-line-strong px-1.5 text-[10px] font-semibold text-ink-faint lg:inline">
              /
            </kbd>
          </div>

          {showSuggest && suggestions.length > 0 && (
            <ul
              className="absolute right-0 top-12 z-50 w-80 max-w-[90vw] overflow-hidden rounded-[14px] border border-line-strong bg-paper py-1.5 shadow-xl"
              role="listbox"
              aria-label="Search suggestions"
            >
              {suggestions.map((s, i) => (
                <li key={s.id} role="option" aria-selected={i === activeIdx}>
                  <button
                    type="button"
                    // mousedown beats the input's blur so the pick lands
                    onMouseDown={(e) => {
                      e.preventDefault()
                      pickSuggestion(seriesHref(s))
                    }}
                    onMouseEnter={() => setActiveIdx(i)}
                    className={cx(
                      'flex w-full items-center gap-3 px-3.5 py-2 text-left transition-colors',
                      i === activeIdx ? 'bg-ink/[0.05]' : 'bg-transparent',
                    )}
                  >
                    <span className="min-w-0 flex-1">
                      <span className="block truncate text-sm font-semibold text-ink">
                        {s.title}
                      </span>
                      <span className="mt-0.5 block truncate text-xs text-ink-faint">
                        {s.author} · {(s.genres ?? []).slice(0, 2).join(', ')}
                      </span>
                    </span>
                    <span className="shrink-0 text-[10px] font-bold uppercase tracking-wide text-ink-faint">
                      {s.kind === 'manhua' ? 'Manhua' : 'Manhwa'}
                    </span>
                  </button>
                </li>
              ))}
              <li>
                <button
                  type="submit"
                  onMouseDown={(e) => e.preventDefault()}
                  className="w-full px-3.5 py-2 text-left text-xs font-semibold text-accent transition-colors hover:underline"
                >
                  See all results for “{q.trim()}” →
                </button>
              </li>
            </ul>
          )}
        </form>

        {/* Theme toggle */}
        <button
          onClick={toggleTheme}
          className="grid h-10 w-10 place-items-center rounded-full border border-line-strong text-ink-soft transition-colors hover:border-ink hover:text-ink"
          aria-label={prefs.theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'}
          title={prefs.theme === 'dark' ? 'Editorial Light' : 'Onyx Dark'}
        >
          {prefs.theme === 'dark' ? <Sun width={17} height={17} /> : <Moon width={17} height={17} />}
        </button>

        {/* Account */}
        <a
          href="/account"
          onClick={(e) => {
            if (e.metaKey || e.ctrlKey) return
            e.preventDefault()
            navigate('/account')
          }}
          className="hidden h-10 w-10 place-items-center rounded-full border border-line-strong text-ink-soft transition-colors hover:border-ink hover:text-ink md:grid"
          aria-label="Account"
        >
          <User width={18} height={18} />
        </a>

        {/* Mobile buttons */}
        <button
          onClick={() => navigate('/search')}
          className="grid h-10 w-10 place-items-center rounded-full border border-line-strong text-ink-soft md:hidden"
          aria-label="Search"
        >
          <Search width={18} height={18} />
        </button>
        <button
          onClick={() => setMenuOpen((v) => !v)}
          className="grid h-10 w-10 place-items-center rounded-full border border-line-strong text-ink lg:hidden"
          aria-label="Open menu"
        >
          {menuOpen ? <X width={18} height={18} /> : <Menu width={18} height={18} />}
        </button>
      </div>

      {/* Mobile menu */}
      {menuOpen && (
        <div className="animate-fade-in border-t border-line bg-paper lg:hidden">
          <nav className="mx-auto flex max-w-[1240px] flex-col px-4 py-3 sm:px-6">
            {NAV.map((item) => (
              <a
                key={item.to}
                href={item.to}
                onClick={(e) => {
                  if (e.metaKey || e.ctrlKey) return
                  e.preventDefault()
                  navigate(item.to)
                }}
                className={cx(
                  'flex items-center justify-between rounded-lg px-3 py-3 text-base font-semibold',
                  isActive(item.to) ? 'bg-ink/5 text-ink' : 'text-ink-soft',
                )}
              >
                {item.label}
                {item.label === 'Library' && library.length > 0 && (
                  <span className="rounded-full bg-accent px-2 py-0.5 text-xs font-bold text-white">
                    {library.length}
                  </span>
                )}
              </a>
            ))}
            <div className="my-2 h-px bg-line" />
            <a
              href="/account"
              onClick={(e) => {
                if (e.metaKey || e.ctrlKey) return
                e.preventDefault()
                navigate('/account')
              }}
              className="flex items-center gap-2 rounded-lg px-3 py-3 text-base font-semibold text-ink-soft"
            >
              <User width={18} height={18} /> Account
            </a>
          </nav>
        </div>
      )}
    </header>
  )
}
