import { useCallback, useEffect, useMemo, useState } from 'react'
import { Star, Eye, ArrowRight, Sparkles, Clock, TrendingUp } from 'lucide-react'
import {
  trending,
  trendingNow,
  featuredToday,
  staffPicks,
  topRanked,
  topOfCharts,
  byGenre,
  latestUpdateGroups,
  platformStats,
} from '../lib/selectors'
import { GENRES } from '../data/genres'
import { useCatalog } from '../lib/catalog-context'
import Cover from '../components/Cover'
import Rail from '../components/Rail'
import { SeriesCard, FeatureCard, RankRow } from '../components/SeriesCard'
import { SectionHeader, Button } from '../components/ui'
import { navigate } from '../lib/router'
import { useStore } from '../lib/store'
import { formatViews, relativeDate, formatDate, cx, seriesHref, chapterHref, genreHref, shortDescription, chapterCountOf, firstChapterOf } from '../lib/utils'

const link =
  (to: string) =>
  (e: React.MouseEvent): void => {
    if (e.metaKey || e.ctrlKey) return
    e.preventDefault()
    navigate(to)
  }

export default function Home() {
  const { series, loading, coreReady, source } = useCatalog()
  const { progress } = useStore()

  // "Featured Today" — the day's top 10, auto-rotating in the hero. Picked
  // fresh from the trending pool each calendar day (see featuredToday), so
  // the set updates automatically with the 6-hourly catalog refresh.
  const heroes = useMemo(() => {
    const list = featuredToday(series, 10)
    return list.length >= 3 ? list : trending(series, 12).slice(0, 10)
  }, [series])
  const [heroIdx, setHeroIdx] = useState(0)
  const [heroPaused, setHeroPaused] = useState(false)
  const [canRotateHero, setCanRotateHero] = useState(false)

  useEffect(() => {
    const timer = window.setTimeout(() => setCanRotateHero(true), 1800)
    return () => window.clearTimeout(timer)
  }, [])

  useEffect(() => {
    if (!canRotateHero || heroPaused || heroes.length < 2) return
    const t = window.setInterval(() => setHeroIdx((i) => (i + 1) % heroes.length), 7000)
    return () => window.clearInterval(t)
  }, [canRotateHero, heroPaused, heroes.length])

  // Freeze the hero the moment the user acts on it — auto-rotation swaps the
  // featured series out from under a click mid-interaction (card read "Eleceed",
  // click landed on the rotated-in "Lookism").
  const pinHero = useCallback(() => setHeroPaused(true), [])

  if (loading) return <HomeSkeleton />

  const stats = platformStats(series)
  // Real figures for the stats band — completed titles and distinct genres in
  // the catalog (matches what /status/completed and /genres list).
  const completedCount = series.filter((s) => s.status === 'Completed').length
  const genreCount = new Set(series.flatMap((s) => s.genres)).size
  const hero = heroes[Math.min(heroIdx, heroes.length - 1)] ?? series[0]
  // "Trending Now" rail — all genuinely top-viewed this week, but the mix
  // re-rolls automatically every 2 days (see trendingNow) so the section
  // visibly refreshes on a 1–2 day cadence.
  // Sections render as soon as the FAST catalog data has merged (top-tier
  // snapshot ~1.5MB) instead of waiting for the deferred ~6.5MB full
  // MangaDex snapshot to idle-load — trending/updates draw from the popular
  // head of the catalog, which the fast snapshots already carry. Waiting on
  // full hydration left the middle of the homepage as skeletons for many
  // extra seconds on every device (worse on slow mobile connections).
  const ready = !loading && coreReady
  const heroRail = ready ? trendingNow(series, 12).filter((s) => s.id !== hero.id) : []
  const updates = ready ? latestUpdateGroups(series, 12) : []
  const picks = staffPicks(series).slice(0, 4)

  // Continue Reading: entries from reading progress, most recent first
  const continueReading = Object.values(progress)
    .sort((a, b) => b.updatedAt - a.updatedAt)
    .slice(0, 4)
    .map((p) => {
      const s = series.find((x) => x.id === p.seriesId)
      const chapter = s?.chapters.find((c) => c.id === p.chapterId)
      return s && chapter ? { series: s, chapter } : null
    })
    .filter(Boolean) as { series: (typeof series)[number]; chapter: (typeof series)[number]['chapters'][number] }[]

  return (
    <main className="animate-fade-up">
      {source === 'local' && (
        <div className="border-b border-amber/30 bg-amber/10 px-4 py-2.5 text-center text-xs font-medium text-amber">
          Live catalog unavailable — showing the offline demo catalog.
        </div>
      )}

      {/* ---------------- HERO (Featured Today — auto-rotating top 10) ---------------- */}
      <section
        className="relative overflow-hidden border-b border-line bg-[#181817] text-white"
        onMouseEnter={() => setHeroPaused(true)}
        // Permanent pin on first hover: resuming on leave let rotation fire
        // between reading the card and clicking it (synthetic tests and slow
        // readers land on the rotated-in series).
        onPointerDown={pinHero}
        onKeyDown={pinHero}
      >
        <div
          key={hero.id}
          className="absolute inset-0 animate-fade-in opacity-60"
          style={{
            background: `linear-gradient(105deg, hsl(${hero.hue} 30% 10%) 0%, hsl(${hero.hue} 26% 14%) 55%, hsl(${hero.accentHue} 34% 22%) 100%)`,
          }}
        />
        <div
          className="absolute inset-0"
          style={{
            background:
              'radial-gradient(90% 100% at 85% 0%, rgba(217,87,67,0.28) 0%, transparent 55%)',
          }}
        />
        <div key={`${hero.id}-content`} className="relative mx-auto max-w-[1240px] px-4 py-16 sm:px-6 sm:py-20 lg:py-24 lg:px-8">
          <div className="grid gap-10 lg:grid-cols-[1.15fr_0.85fr] lg:items-center">
          <div className="min-w-0">
            <div className="mb-5 inline-flex items-center gap-2 rounded-full bg-white/10 px-3.5 py-1.5 text-xs font-semibold uppercase tracking-[0.18em] text-white/80 backdrop-blur">
              <Sparkles width={13} height={13} className="text-accent" />
              Featured Today
              <span className="ml-1 rounded-full bg-accent px-1.5 py-0.5 text-[10px] font-bold tracking-normal text-white">
                #{heroIdx + 1} of {heroes.length}
              </span>
            </div>
            <h1 className="max-w-xl break-words text-4xl font-extrabold leading-[1.05] tracking-[-0.03em] sm:text-5xl lg:text-6xl">
              {hero.title}
            </h1>
            <p className="mt-5 line-clamp-4 max-w-lg break-words text-base leading-relaxed text-white/70 sm:text-lg">
              {shortDescription(hero, 180)}
            </p>
            <div className="mt-6 flex flex-wrap items-center gap-x-5 gap-y-2 text-sm text-white/60">
              <span className="inline-flex items-center gap-1.5 font-semibold text-white">
                <Star width={15} height={15} className="fill-accent text-accent" />
                {hero.rating.toFixed(1)}
                <span className="font-normal text-white/50">
                  ({formatViews(hero.ratingCount)} ratings)
                </span>
              </span>
              <span className="inline-flex items-center gap-1.5">
                <Eye width={15} height={15} /> {formatViews(hero.views)} readers
              </span>
              <span className="inline-flex items-center gap-1.5">
                <Clock width={15} height={15} /> {chapterCountOf(hero)} chapters
              </span>
              <span className="hidden sm:inline">{hero.genres.join(' · ')}</span>
            </div>
            <div className="mt-8 flex flex-wrap gap-3">
              <Button
                variant="accent"
                size="lg"
                href={chapterHref(hero, firstChapterOf(hero))}
                onClick={pinHero}
              >
                Read First Chapter
                <ArrowRight width={18} height={18} />
              </Button>
              <Button
                variant="outline"
                size="lg"
                href={`${seriesHref(hero)}`}
                className="border-white/30 text-white hover:border-white hover:bg-white hover:text-ink"
              >
                Series Details
              </Button>
            </div>
          </div>

          {/* cover art — visible on every screen size (was hidden below lg,
              which left the mobile hero with no picture) */}
          <div className="relative">
            <a
              href={`${seriesHref(hero)}`}
              onClick={link(`${seriesHref(hero)}`)}
              className="group block aspect-[3/4] w-[210px] justify-self-start overflow-hidden rounded-[18px] shadow-2xl ring-1 ring-white/15 transition-transform duration-500 group-hover:scale-[1.015] sm:w-[260px] lg:w-[340px] lg:justify-self-end"
            >
              <Cover series={hero} rounded="rounded-none" priority />
            </a>
            <div className="absolute -bottom-5 -left-2 rounded-[14px] border border-white/15 bg-onyx-2/90 px-4 py-3 backdrop-blur lg:-left-6">
              <div className="eyebrow text-accent">This Week</div>
              <div className="mt-1 text-sm font-bold text-white">
                {formatViews(hero.weeklyViews)} active readers
              </div>
            </div>
          </div>
          </div>
        </div>

        {/* rotation indicators — auto-advances every 7s, pauses on hover */}
        {heroes.length > 1 && (
          <div className="absolute bottom-4 left-1/2 z-10 flex -translate-x-1/2 items-center gap-2">
            {heroes.map((h, i) => (
              <button
                key={h.id}
                type="button"
                onClick={() => {
                  setHeroIdx(i)
                  setHeroPaused(true)
                }}
                aria-label={`Show ${h.title}`}
                aria-current={i === heroIdx ? 'true' : undefined}
                className={cx(
                  'h-11 min-w-11 rounded-full p-0 transition-all before:mx-auto before:block before:h-1.5 before:rounded-full before:content-[\'\']',
                  i === heroIdx
                    ? 'before:w-7 before:bg-white'
                    : 'before:w-2.5 before:bg-white/45 hover:before:bg-white/80',
                )}
              />
            ))}
          </div>
        )}
      </section>

      {/* ---------------- Continue Reading ---------------- */}
      {continueReading.length > 0 && (
        <section className="mx-auto max-w-[1240px] px-4 pt-12 sm:px-6 lg:px-8">
          <SectionHeader
            eyebrow="Pick up where you left off"
            title="Continue Reading"
            action="Reading history"
            onAction={() => navigate('/library?tab=history')}
          />
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
            {continueReading.map(({ series: s, chapter }) => {
              // progress bar: exact position against the full list; for the
              // trimmed mk window (chaptersPartial) the last-read chapter
              // often isn't in the array, so estimate from the source-true
              // chapter number instead
              const idx = s.chapters.findIndex((c) => c.id === chapter.id)
              const pct =
                idx >= 0 && !s.chaptersPartial
                  ? Math.round(((idx + 1) / s.chapters.length) * 100)
                  : Math.min(100, Math.round((chapter.number / Math.max(chapterCountOf(s), 1)) * 100))
              return (
                <a
                  key={s.id}
                  href={chapterHref(s, chapter.number)}
                  onClick={link(chapterHref(s, chapter.number))}
                  className="group rounded-[14px] border border-line bg-paper p-3 transition-all hover:-translate-y-0.5 hover:shadow-md"
                >
                  <div className="flex gap-3">
                    <div className="h-[86px] w-16 shrink-0 overflow-hidden rounded-lg ring-1 ring-black/5">
                      <Cover series={s} showTitle={false} rounded="rounded-lg" />
                    </div>
                    <div className="min-w-0 flex-1">
                      <h4 className="line-clamp-1 font-bold tracking-tight group-hover:text-accent">
                        {s.title}
                      </h4>
                      <p className="mt-0.5 line-clamp-1 text-xs text-ink-faint">
                        Ch. {chapter.number} · {chapter.title}
                      </p>
                      <p className="mt-2 text-[11px] font-medium uppercase tracking-wide text-accent">
                        Resume reading →
                      </p>
                    </div>
                  </div>
                  <div className="mt-3 h-1.5 overflow-hidden rounded-full bg-paper-3">
                    <div
                      className="h-full rounded-full bg-accent"
                      style={{ width: `${pct}%` }}
                    />
                  </div>
                </a>
              )
            })}
          </div>
        </section>
      )}

      {/* ---------------- Trending rail ---------------- */}
      <section className="mx-auto max-w-[1240px] px-4 pt-14 sm:px-6 lg:px-8">
        <SectionHeader
          eyebrow="What everyone is reading right now"
          title="Trending Now"
          action="View all"
          onAction={() => navigate('/catalog?sort=trending')}
        />
        <Rail>
          {heroRail.map((s, i) => (
            <div key={s.id} className="w-[168px] shrink-0 snap-start sm:w-[190px]">
              {/* first 4 rail covers sit above the fold on most viewports —
                  eager + high priority so the hydrated LCP doesn't regress */}
              <SeriesCard series={s} priority={i < 4} />
            </div>
          ))}
          {!ready &&
            Array.from({ length: 6 }).map((_, i) => (
              <div key={`sk-${i}`} className="w-[168px] shrink-0 snap-start sm:w-[190px]">
                <div className="aspect-[3/4] animate-pulse rounded-[14px] bg-paper-3/60" />
                <div className="mt-3 h-4 w-3/4 animate-pulse rounded bg-paper-3/60" />
                <div className="mt-1.5 h-3 w-1/2 animate-pulse rounded bg-paper-3/60" />
              </div>
            ))}
        </Rail>
      </section>

      {/* ---------------- Latest Updates (source-style update feed) ---------------- */}
      <section className="mx-auto max-w-[1240px] px-4 pt-14 sm:px-6 lg:px-8">
        <SectionHeader
          eyebrow="Fresh chapters, updated hourly"
          title="Latest Updates"
          action="Full updates"
          actionHref="/updates"
        />
        <div className="space-y-7">
          {!ready && (
            <div className="grid gap-3 lg:grid-cols-2">
              {Array.from({ length: 6 }).map((_, i) => (
                <div
                  key={`usk-${i}`}
                  className="flex gap-4 rounded-[14px] border border-line bg-paper p-3.5"
                >
                  <div className="h-[104px] w-[76px] shrink-0 animate-pulse rounded-lg bg-paper-3/60" />
                  <div className="min-w-0 flex-1 space-y-2 pt-1">
                    <div className="h-4 w-3/4 animate-pulse rounded bg-paper-3/60" />
                    <div className="h-3 w-1/2 animate-pulse rounded bg-paper-3/60" />
                    <div className="h-3 w-2/3 animate-pulse rounded bg-paper-3/60" />
                  </div>
                </div>
              ))}
            </div>
          )}
          {updates.map((group) => (
            <div key={group.key}>
              <div className="mb-3 flex items-center gap-3">
                <h3
                  className={cx(
                    'text-sm font-extrabold uppercase tracking-wide',
                    group.label === 'Today' ? 'text-accent' : 'text-ink',
                  )}
                >
                  {group.label}
                </h3>
                <span className="text-xs font-medium text-ink-faint">
                  {group.rows.length} series
                </span>
                <div className="h-px flex-1 bg-line" />
              </div>
              <div className="grid gap-3 lg:grid-cols-2">
                {group.rows.map(({ series: s, chapters }) => (
                  <div
                    key={s.id}
                    className="group flex gap-4 rounded-[14px] border border-line bg-paper p-3.5 transition-all hover:border-accent/40 hover:shadow-md"
                  >
                    {/* cover + status, like the source update lists */}
                    <a
                      href={`${seriesHref(s)}`}
                      onClick={link(`${seriesHref(s)}`)}
                      className="relative h-[104px] w-[76px] shrink-0 overflow-hidden rounded-lg ring-1 ring-black/5"
                    >
                      <Cover series={s} showTitle={false} rounded="rounded-lg" />
                      <span
                        className={cx(
                          'absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/70 to-transparent px-1.5 pb-1 pt-4 text-[10px] font-bold uppercase tracking-wide text-white',
                        )}
                      >
                        {s.status}
                      </span>
                    </a>
                    <div className="min-w-0 flex-1">
                      <a
                        href={`${seriesHref(s)}`}
                        onClick={link(`${seriesHref(s)}`)}
                        className="line-clamp-1 text-sm font-bold tracking-tight hover:text-accent"
                      >
                        {s.title}
                        <span className="ml-1.5 font-semibold text-accent">
                          — Ch. {chapters[0].number}
                        </span>
                      </a>
                      <div className="mt-1.5 flex flex-wrap items-center gap-x-3 gap-y-1">
                        <span className="inline-flex items-center gap-1 text-[11px] font-medium text-ink-faint">
                          <Clock width={11} height={11} />
                          {relativeDate(chapters[0].releaseDate)}
                        </span>
                        {s.genres.slice(0, 4).map((g) => (
                          <a
                            key={g}
                            href={genreHref(g)}
                            onClick={link(genreHref(g))}
                            className="rounded-full border border-line px-2 py-0.5 text-[10px] font-medium text-ink-soft transition-colors hover:border-accent hover:text-accent"
                          >
                            {g}
                          </a>
                        ))}
                      </div>
                      {/* latest chapters with dates, newest first */}
                      <div className="mt-2 space-y-0.5">
                        {chapters.map((chapter) => (
                          <div key={chapter.id} className="flex items-baseline justify-between gap-3">
                            <a
                              href={chapterHref(s, chapter.number)}
                              onClick={link(chapterHref(s, chapter.number))}
                              className="line-clamp-1 text-xs font-semibold text-ink-soft transition-colors hover:text-accent"
                            >
                              Chapter {chapter.number}
                            </a>
                            <span className="shrink-0 text-[10px] tabular-nums text-ink-faint">
                              {formatDate(chapter.releaseDate)}
                            </span>
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
          {ready && (
            <p className="pt-1 text-center">
              <a
                href="/updates"
                onClick={link('/updates')}
                className="inline-flex min-h-11 items-center justify-center rounded-full border border-line-strong px-5 text-sm font-semibold text-ink-soft transition-colors hover:border-ink hover:text-ink"
              >
                Browse all updates and every series <ArrowRight width={16} height={16} className="ml-2" />
              </a>
            </p>
          )}
        </div>
      </section>

      {/* ---------------- Genre spotlight ---------------- */}
      <section className="mx-auto max-w-[1240px] px-4 pt-14 sm:px-6 lg:px-8">
        <SectionHeader
          eyebrow="Browse by Genre"
          title="Genre Spotlight"
          action="Genre directory"
          onAction={() => navigate('/genres')}
        />
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-5">
          {GENRES.slice(0, 10).map((g) => {
            // the genre's most-viewed series (real popularity since the
            // AniList enrichment) drives the card's palette — Action shows
            // its actual top title, not whichever entry the catalog
            // happened to list first
            const sample = byGenre(series, g.name)[0]
            return (
              <a
                key={g.name}
                href={genreHref(g.name)}
                onClick={link(genreHref(g.name))}
                className="group relative overflow-hidden rounded-[14px] border border-line p-4 transition-all hover:-translate-y-0.5 hover:shadow-md"
                style={{
                  background: sample
                    ? `linear-gradient(140deg, hsl(${sample.hue} 30% 94%) 0%, hsl(${sample.accentHue} 26% 88%) 100%)`
                    : undefined,
                }}
              >
                <div className="text-sm font-extrabold tracking-tight">{g.name}</div>
                <p className="mt-1 line-clamp-2 text-xs leading-snug text-ink-soft">
                  {g.tagline}
                </p>
                <span className="mt-3 inline-block text-[11px] font-bold uppercase tracking-wide text-accent opacity-0 transition-opacity group-hover:opacity-100">
                  Explore →
                </span>
              </a>
            )
          })}
        </div>
      </section>

      {/* ---------------- Staff picks / editorial ---------------- */}
      <section className="mx-auto max-w-[1240px] px-4 pt-14 sm:px-6 lg:px-8">
        <SectionHeader
          eyebrow="Curated highlights selected by the editorial desk"
          title="Worth Reading"
          action="Browse catalog"
          onAction={() => navigate('/catalog')}
        />
        <div className="grid gap-4 lg:grid-cols-2">
          {picks.map((s) => (
            <FeatureCard key={s.id} series={s} />
          ))}
        </div>
      </section>

      {/* ---------------- Rankings preview ---------------- */}
      <section className="mx-auto max-w-[1240px] px-4 pt-14 sm:px-6 lg:px-8">
        <SectionHeader
          eyebrow="Platform Rankings"
          title="Top of the Charts"
          action="Full leaderboard"
          onAction={() => navigate('/rankings')}
        />
        <div className="rounded-[18px] border border-line bg-paper-2/50 p-2 sm:p-4">
          <div className="grid gap-x-8 lg:grid-cols-2">
            {topOfCharts(series, 10).map((s, i) => (
              <RankRow key={s.id} series={s} rank={i + 1} metric={`★ ${s.rating.toFixed(1)}`} />
            ))}
          </div>
        </div>
      </section>

      {/* ---------------- Catalog stats band ---------------- */}
      <section className="mx-auto max-w-[1240px] px-4 pt-14 sm:px-6 lg:px-8">
        <div className="overflow-hidden rounded-[18px] bg-[#151513] px-6 py-10 text-white">
          <p className="text-sm text-white/50">
            Everything in the catalog, refreshed every few hours.
          </p>
          <div className="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
            {[
              {
                icon: TrendingUp,
                label: 'Ongoing series',
                value: String(stats.ongoing),
                href: '/status/ongoing',
              },
              {
                icon: Star,
                label: 'Completed series',
                value: String(completedCount),
                href: '/status/completed',
              },
              {
                icon: Clock,
                label: 'Total chapters',
                value: formatViews(stats.totalChapters),
                href: '/updates',
              },
              {
                icon: Sparkles,
                label: 'Genres',
                value: String(genreCount),
                href: '/genres',
              },
            ].map(({ icon: Icon, label, value, href }) => (
              <a
                key={label}
                href={href}
                onClick={link(href)}
                className="transition-opacity hover:opacity-80"
              >
                <Icon width={18} height={18} className="text-accent" />
                <div className="mt-3 text-3xl font-extrabold tracking-tight tabular-nums">
                  {value}
                </div>
                <div className="mt-1 text-sm text-white/60">{label}</div>
              </a>
            ))}
          </div>
        </div>
      </section>
    </main>
  )
}

/* Loading skeleton shown while the catalog loads */
function HomeSkeleton() {
  return (
    <main className="animate-fade-in">
      <div className="h-[340px] w-full animate-pulse bg-paper-3/60" />
      <div className="mx-auto max-w-[1240px] px-4 py-12 sm:px-6 lg:px-8">
        <div className="mb-5 h-7 w-56 animate-pulse rounded bg-paper-3/60" />
        <div className="flex gap-5 overflow-hidden">
          {Array.from({ length: 6 }).map((_, i) => (
            <div key={i} className="w-[180px] shrink-0">
              <div className="aspect-[3/4] animate-pulse rounded-[14px] bg-paper-3/60" />
              <div className="mt-3 h-4 w-3/4 animate-pulse rounded bg-paper-3/60" />
            </div>
          ))}
        </div>
        <div className="mt-12 mb-5 h-7 w-48 animate-pulse rounded bg-paper-3/60" />
        <div className="grid gap-3 lg:grid-cols-2">
          {Array.from({ length: 4 }).map((_, i) => (
            <div key={i} className="h-[88px] animate-pulse rounded-[14px] bg-paper-3/60" />
          ))}
        </div>
      </div>
    </main>
  )
}
