import { useState } from 'react'
import { coverArt, monogram } from '../lib/cover'
import { proxyImageUrl } from '../lib/mangadex'
import type { Series } from '../types'
import { cx } from '../lib/utils'

interface CoverProps {
  series: Series
  className?: string
  showTitle?: boolean
  rounded?: string
  /** Hero/first-viewport covers: fetch eagerly at high priority (they are
   *  the page's LCP element); grid covers stay lazy. */
  priority?: boolean
}

/**
 * Cover renderer. Series with real cover art (AniList) display the image;
 * procedural gradient covers remain for fictional/fallback titles and as
 * an error fallback.
 */
export default function Cover({ series, className, showTitle = true, rounded = 'rounded-[14px]', priority = false }: CoverProps) {
  const [imgFailed, setImgFailed] = useState(false)
  const useImage = !!series.coverUrl && !imgFailed
  const art = coverArt(series)

  return (
    <div
      className={cx('relative h-full w-full overflow-hidden', rounded, className)}
      style={{ background: art.bg }}
      aria-hidden={!showTitle}
    >
      {useImage ? (
        <>
          <img
            // our CDN mirror first (the source 403s Cloudflare-Worker
            // proxies for MangaKatana covers); proxy as fallback
            src={series.coverCdn || proxyImageUrl(series.coverUrl)}
            alt={series.title}
            width={600}
            height={800}
            sizes="(max-width: 640px) 50vw, (max-width: 1024px) 25vw, 300px"
            decoding="async"
            loading={priority ? 'eager' : 'lazy'}
            {...(priority ? ({ fetchpriority: 'high' } as never) : {})}
            referrerPolicy="no-referrer"
            onError={() => setImgFailed(true)}
            className="absolute inset-0 h-full w-full object-cover"
          />
          {/* soft gradient for overlay text legibility */}
          <div
            className="absolute inset-0"
            style={{ background: 'linear-gradient(to top, rgba(10,10,9,0.62) 0%, rgba(10,10,9,0.08) 42%, transparent 65%)' }}
          />
        </>
      ) : (
        <>
          <div className="absolute inset-0" style={{ background: art.glow }} />
          <Motif motif={art.motif} band={art.band} />
          <div
            className="absolute inset-0 opacity-[0.5]"
            style={{
              background:
                'radial-gradient(120% 120% at 50% 0%, transparent 55%, rgba(0,0,0,0.45) 100%)',
            }}
          />
        </>
      )}

      {/* accent hairline band near bottom */}
      <div
        className="absolute left-0 right-0 bottom-0 h-[3px]"
        style={{ background: art.band }}
      />

      {showTitle ? (
        <div className="absolute inset-0 flex flex-col justify-between p-3.5">
          <div className="flex items-center justify-between">
            <span
              className="eyebrow text-[10px] text-white/75"
              style={{ letterSpacing: '0.24em' }}
            >
              {series.genres[0]}
            </span>
          </div>

          <div className="pointer-events-none select-none">
            <div
              className="font-extrabold uppercase leading-[0.98] tracking-tight text-white"
              style={{
                fontSize: 'clamp(1.05rem, 2.4vw, 1.9rem)',
                textShadow: '0 2px 24px rgba(0,0,0,0.35)',
              }}
            >
              {series.title}
            </div>
            <div className="mt-1.5 text-[11px] font-medium text-white/70">
              {series.author}
            </div>
          </div>
        </div>
      ) : !useImage ? (
        <div className="absolute inset-0 flex items-center justify-center">
          <span
            className="font-extrabold text-white/90"
            style={{ fontSize: 'clamp(1.5rem, 8vw, 3rem)', textShadow: '0 2px 20px rgba(0,0,0,0.4)' }}
          >
            {monogram(series.title)}
          </span>
        </div>
      ) : null}
    </div>
  )
}

function Motif({ motif, band }: { motif: string; band: string }) {
  const common = { stroke: 'rgba(255,255,255,0.14)', fill: 'none', strokeWidth: 1.5 }
  return (
    <svg
      className="absolute inset-0 h-full w-full"
      viewBox="0 0 100 140"
      preserveAspectRatio="xMidYMid slice"
    >
      {motif === 'arc' && (
        <g {...common}>
          <circle cx="78" cy="26" r="30" />
          <circle cx="78" cy="26" r="46" />
          <circle cx="78" cy="26" r="62" />
        </g>
      )}
      {motif === 'rings' && (
        <g {...common}>
          <circle cx="50" cy="60" r="18" />
          <circle cx="50" cy="60" r="30" />
          <circle cx="50" cy="60" r="42" strokeDasharray="3 5" />
        </g>
      )}
      {motif === 'peaks' && (
        <g {...common}>
          <path d="M0 120 L26 70 L44 96 L64 54 L86 100 L100 74 L100 140 L0 140 Z" fill="rgba(255,255,255,0.05)" stroke="none" />
          <path d="M0 120 L26 70 L44 96 L64 54 L86 100 L100 74" />
        </g>
      )}
      {motif === 'grid' && (
        <g {...common} strokeWidth={1}>
          {Array.from({ length: 7 }).map((_, i) => (
            <line key={'v' + i} x1={i * 16} y1={0} x2={i * 16} y2={140} />
          ))}
          {Array.from({ length: 9 }).map((_, i) => (
            <line key={'h' + i} x1={0} y1={i * 16} x2={100} y2={i * 16} />
          ))}
        </g>
      )}
      {motif === 'sun' && (
        <g {...common}>
          <circle cx="50" cy="44" r="16" fill={band} stroke="none" opacity={0.5} />
          {Array.from({ length: 12 }).map((_, i) => {
            const a = (i / 12) * Math.PI * 2
            return (
              <line
                key={i}
                x1={50 + Math.cos(a) * 22}
                y1={44 + Math.sin(a) * 22}
                x2={50 + Math.cos(a) * 34}
                y2={44 + Math.sin(a) * 34}
              />
            )
          })}
        </g>
      )}
      {motif === 'rift' && (
        <g {...common}>
          <path d="M60 -5 L40 50 L58 70 L34 145" strokeWidth={2} />
          <path d="M76 -5 L58 46 L72 66 L52 145" strokeWidth={1} opacity={0.6} />
        </g>
      )}
    </svg>
  )
}
