/** Small formatting + misc helpers used across the app. */

import type { Series } from '../types'

/**
 * Readable URL slug for a series, generated from its title
 * ("Who Made Me a Princess" → "who-made-me-a-princess"). Falls back to the
 * internal slug when the title yields nothing usable (e.g. non-latin-only).
 *
 * Safe as a URL key: the catalog collapses same-title entries to one, and
 * two different collapsed titles always produce different slugify() values
 * (slugify is a lossless-injective transform of the collapse key), so this
 * is unique within the merged catalog without any disambiguation suffix.
 */
export function titleSlug(s: Pick<Series, 'slug' | 'title'>): string {
  return slugify(s.title ?? '') || s.slug
}

/**
 * Keyword URL for a series: /manhwa/{title-slug} or /manhua/{title-slug}.
 * Prefer series.kind when present; fall back to manhwa (md-/al- series are
 * Korean manhwa by definition; mk- series get their real kind from the
 * catalog scraper).
 */
export function seriesHref(s: Pick<Series, 'slug' | 'title' | 'kind'>): string {
  const kind = s.kind ?? 'manhwa'
  return `/${kind}/${titleSlug(s)}`
}

/**
 * Reader URL for one chapter: /read/{title-slug}/chapter-{n}. The "chapter-N"
 * form is canonical everywhere the site links to a chapter (the old bare
 * /read/{slug}/{n} URLs 301 to it — see api/read/index.ts). Mirrored in
 * scripts/prerender.mjs and api/read/index.ts — keep the three in sync.
 */
export function chapterHref(s: Pick<Series, 'slug' | 'title'>, chapterNumber: number): string {
  return `/read/${titleSlug(s)}/chapter-${chapterNumber}`
}

/**
 * True chapter total. The mk meta snapshot ships only a recent window of
 * chapters per series (chapterCount carries the real total — see
 * types.ts); everywhere else the full array is present.
 */
export function chapterCountOf(s: Pick<Series, 'chapterCount' | 'chapters'>): number {
  return s.chapterCount ?? s.chapters.length
}

/** First chapter's number — falls back to the array when it isn't trimmed. */
export function firstChapterOf(
  s: Pick<Series, 'firstChapter' | 'chapters' | 'chapterCount'>,
): number {
  // A trimmed recent-window array (chapterCount > window length) must not
  // pose as the start of the run — the true first chapter is 1.
  if (!s.firstChapter && (s.chapterCount ?? 0) > s.chapters.length) return 1
  return s.firstChapter ?? s.chapters[0]?.number ?? 1
}

/** Permanent lowercase genre URL: /genres/fantasy. */
export function genreHref(name: string): string {
  return `/genres/${slugify(name)}`
}

/** Named HTML entities that show up raw in scraped descriptions. */
const NAMED_ENTITIES: Record<string, string> = {
  amp: '&',
  lt: '<',
  gt: '>',
  quot: '"',
  apos: "'",
  nbsp: ' ',
  hellip: '…',
  mdash: '—',
  ndash: '–',
  lsquo: '‘',
  rsquo: '’',
  ldquo: '“',
  rdquo: '”',
  // accented Latin-1 entities — they leak into scraped titles
  // ("I Raised My Fianc&eacute; with Money") and would otherwise poison
  // title-matching keys
  aacute: 'á',
  agrave: 'à',
  eacute: 'é',
  egrave: 'è',
  iacute: 'í',
  oacute: 'ó',
  uacute: 'ú',
  uuml: 'ü',
  ouml: 'ö',
  ntilde: 'ñ',
  ccedil: 'ç',
  aelig: 'æ',
  oelig: 'œ',
  aring: 'å',
}

/** Decode HTML entities (&amp;, &#039;, &rsquo;, …) that scrape in raw. */
export function decodeEntities(s: string): string {
  return s
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
    .replace(/&([a-z]+);/gi, (m, name: string) => NAMED_ENTITIES[name.toLowerCase()] ?? m)
}

/**
 * Full, sanitized source synopsis for series detail pages. Keep the real
 * catalog text (rather than generating filler) while limiting outlier copy.
 */
export function fullDescription(
  s: Pick<Series, 'title' | 'synopsis' | 'genres' | 'status' | 'chapters' | 'kind'>,
  maxChars = 1200,
): string {
  const text = decodeEntities(s.synopsis ?? '')
    .replace(/<br\s*\/?>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/https?:\/\/\S+/g, ' ')
    .replace(/\[[^\]]*\]|\((?:source|raw|scanlated? by|author|artist|note)[^)]*\)/gi, ' ')
    .replace(/[*_#>|~]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()

  if (!text || /^no (synopsis|description)/i.test(text)) return shortDescription(s, maxChars)
  if (text.length <= maxChars) return text
  const cut = text.slice(0, maxChars - 1)
  const boundary = cut.lastIndexOf(' ')
  return `${cut.slice(0, boundary >= maxChars * 0.6 ? boundary : cut.length)}…`
}

/**
 * Short, clean, 1–2 sentence description for a series. Decodes stray HTML
 * entities, strips tags/URLs/source notes and other scrape noise, then cuts
 * at a sentence boundary so every card, page, and meta tag shows a tidy
 * blurb instead of a wall of text or gibberish.
 */
export function shortDescription(
  s: Pick<Series, 'title' | 'synopsis' | 'genres' | 'status' | 'chapters' | 'kind'>,
  maxChars = 200,
): string {
  const text = decodeEntities(s.synopsis ?? '')
    .replace(/<br\s*\/?>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/https?:\/\/\S+/g, ' ')
    .replace(/\[[^\]]*\]|\((?:source|raw|scanlated? by|author|artist|note)[^)]*\)/gi, ' ')
    .replace(/[*_#>|~]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()

  if (!text || /^no (synopsis|description)/i.test(text)) {
    const genre = s.genres?.[0]
    const kind = s.kind ?? 'manhwa'
    return `Read ${s.title} free on MANHWAS — ${s.status.toLowerCase()} ${kind}${
      genre ? ` with ${genre.toLowerCase()}` : ''
    } and ${s.chapters?.length ?? 0} chapters.`
  }

  // keep the first sentence, then a second only if it fits
  const sentences = text.match(/[^.!?]+[.!?]+(?:["'”’)\]]+)?\s*/g) ?? [text + ' ']
  let out = ''
  for (const sent of sentences.slice(0, 2)) {
    if (out && out.length + sent.trim().length > maxChars) break
    out += sent
  }
  out = out.trim() || text
  if (out.length > maxChars) out = out.slice(0, maxChars).replace(/\s+\S*$/, '') + '…'
  return out
}

export function formatViews(n: number): string {
  if (n >= 1_000_000) return (n / 1_000_000).toFixed(n >= 10_000_000 ? 0 : 1) + 'M'
  if (n >= 1_000) return (n / 1_000).toFixed(n >= 10_000 ? 0 : 1) + 'K'
  return String(n)
}

export function formatNumber(n: number): string {
  return n.toLocaleString('en-US')
}

/** "Today" / "Yesterday" / "3 days ago" / "Mar 4, 2025" */
export function relativeDate(iso: string): string {
  const then = new Date(iso).getTime()
  const now = Date.now()
  const diff = now - then
  const day = 86_400_000
  if (diff < 0) return formatDate(iso)
  if (diff < 60_000) return 'Just now'
  if (diff < 3_600_000) return `${Math.floor(diff / 60_000)}m ago`
  if (diff < day) return `${Math.floor(diff / 3_600_000)}h ago`
  if (diff < 2 * day) return 'Yesterday'
  if (diff < 7 * day) return `${Math.floor(diff / day)} days ago`
  return formatDate(iso)
}

export function formatDate(iso: string): string {
  return new Date(iso).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  })
}

export function clamp(n: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, n))
}

export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(' ')
}

/** Deterministic pseudo-random from a string seed (mulberry32). */
export function seededRandom(seed: string): () => number {
  let h = 1779033703 ^ seed.length
  for (let i = 0; i < seed.length; i++) {
    h = Math.imul(h ^ seed.charCodeAt(i), 3432918353)
    h = (h << 13) | (h >>> 19)
  }
  let a = h >>> 0
  return function () {
    a |= 0
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

export function slugify(s: string): string {
  return s
    .toLowerCase()
    .replace(/['’]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '')
}

/**
 * Heavy static data — catalog snapshots and per-series chapter files — is
 * published to Cloudflare R2 (cdn.manhwas.site): free, unmetered egress,
 * and it keeps the bulk of the site's bandwidth off the Vercel Hobby
 * allowance. The same files are still served from this origin by Vercel, so
 * every read falls back automatically if the CDN is unreachable.
 */
export const CDN_ORIGIN = 'https://cdn.manhwas.site'

export async function fetchCdnJson<T>(path: string): Promise<T | null> {
  // cache: 'no-cache' — the Cloudflare zone's Browser Cache TTL overrides our
  // max-age to 4 hours, which would freeze chapter lists in a visitor's
  // browser long after a refresh landed. 'no-cache' forces a conditional
  // revalidation (304s are cheap — these files carry etags) so the app reads
  // fresh data without losing caching entirely.
  for (const url of [`${CDN_ORIGIN}${path}`, path]) {
    try {
      const res = await fetch(url, { cache: 'no-cache' })
      if (res.ok) return (await res.json()) as T
    } catch {
      /* try the next source */
    }
  }
  return null
}

/**
 * Strip the chapter-number prefix from a source chapter title
 * ("Chapter 624", "Vol.2 Chapter 26 — …") so UI never shows a SECOND
 * chapter number next to the real one. Returns the remaining descriptive
 * text ("Side Story 21 [END]", "Ep. 624" is dropped too as pure numbering),
 * or '' when the title was nothing but the chapter label.
 */
export function chapterTitleSuffix(title: string | undefined): string {
  return String(title ?? '')
    .replace(/^\s*(?:vol\.?\s*\d+\s+)?chapter\s*#?\s*[\d.]+\s*[:.\-–—]?\s*/i, '')
    .replace(/^\s*(?:ep(?:isode)?\.?\s*[\d.]+)\s*$/i, '')
    .trim()
}
