import { Star, Eye, BookOpen } from 'lucide-react'
import type { Series } from '../types'
import Cover from './Cover'
import { StatusBadge } from './ui'
import { cx, formatViews, seriesHref, shortDescription, chapterCountOf, slugify } from '../lib/utils'
import { navigate } from '../lib/router'

function go(href: string) {
  return (e: React.MouseEvent) => {
    if (e.metaKey || e.ctrlKey) return
    e.preventDefault()
    navigate(href)
  }
}

/* ---------------- Standard grid / rail card ---------------- */
export function SeriesCard({
  series,
  className,
  width,
  priority,
}: {
  series: Series
  className?: string
  width?: number
  /** Above-fold cards: eager + fetchpriority=high (they are the page's LCP
   *  element once hydrated). Default stays lazy for below-fold grids. */
  priority?: boolean
}) {
  const authorHref = series.author && series.author !== 'Unknown' && slugify(series.author)
    ? `/author/${slugify(series.author)}`
    : null
  return (
    <div className={cx('group block', className)} style={width ? { width } : undefined}>
      <a href={seriesHref(series)} onClick={go(seriesHref(series))} className="block">
        <div className="relative aspect-[3/4] overflow-hidden rounded-[14px] shadow-sm ring-1 ring-black/5 transition-all duration-300 group-hover:-translate-y-1 group-hover:shadow-xl">
          <Cover series={series} priority={priority} />
          {series.staffPick && (
            <span className="absolute left-2.5 top-2.5 rounded-full bg-white/90 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide text-ink backdrop-blur">
              Staff Pick
            </span>
          )}
        </div>
        <div className="mt-3">
          <div className="flex items-center gap-2 text-xs text-ink-faint">
            <span className="inline-flex items-center gap-1 font-semibold text-ink">
              <Star width={13} height={13} className="fill-accent text-accent" />
              {series.rating.toFixed(1)}
            </span>
            <span className="text-line-strong">·</span>
            <span className="inline-flex items-center gap-1">
              <Eye width={13} height={13} />
              {formatViews(series.views)}
            </span>
          </div>
          <h3 className="mt-1 line-clamp-1 font-bold leading-snug tracking-tight transition-colors group-hover:text-accent">
            {series.title}
          </h3>
        </div>
      </a>
      {authorHref ? (
        <a href={authorHref} onClick={go(authorHref)} className="line-clamp-1 text-sm text-ink-soft hover:text-accent">
          {series.author}
        </a>
      ) : (
        <p className="line-clamp-1 text-sm text-ink-soft">{series.author || 'Unknown'}</p>
      )}
    </div>
  )
}

/* ---------------- Wide editorial / feature card ---------------- */
export function FeatureCard({ series }: { series: Series }) {
  return (
    <a
      href={`${seriesHref(series)}`}
      onClick={go(seriesHref(series))}
      className="group grid overflow-hidden rounded-[18px] border border-line bg-paper sm:grid-cols-[200px_1fr]"
    >
      <div className="relative aspect-[3/4] sm:aspect-auto">
        <Cover series={series} rounded="rounded-none" />
      </div>
      <div className="flex flex-col justify-between p-5">
        <div>
          <div className="mb-2 flex items-center gap-2">
            <StatusBadge status={series.status} />
            <span className="text-xs font-medium text-ink-faint">{series.genres.join(' · ')}</span>
          </div>
          <h3 className="text-xl font-extrabold tracking-tight transition-colors group-hover:text-accent">
            {series.title}
          </h3>
          <p className="mt-2 line-clamp-3 text-sm leading-relaxed text-ink-soft">
            {shortDescription(series, 160)}
          </p>
        </div>
        <div className="mt-4 flex items-center gap-3 text-xs text-ink-faint">
          <span className="inline-flex items-center gap-1 font-semibold text-ink">
            <Star width={13} height={13} className="fill-accent text-accent" />
            {series.rating.toFixed(1)}
          </span>
          <span className="inline-flex items-center gap-1">
            <BookOpen width={13} height={13} />
            {chapterCountOf(series)} ch
          </span>
          <span className="inline-flex items-center gap-1">
            <Eye width={13} height={13} />
            {formatViews(series.views)}
          </span>
        </div>
      </div>
    </a>
  )
}

/* ---------------- Ranking row (leaderboards) ---------------- */
export function RankRow({
  series,
  rank,
  metric,
}: {
  series: Series
  rank: number
  metric: string
}) {
  return (
    <a
      href={`${seriesHref(series)}`}
      onClick={go(seriesHref(series))}
      className="group flex items-center gap-4 rounded-[14px] border border-transparent px-3 py-2.5 transition-colors hover:border-line hover:bg-paper"
    >
      <span
        className={cx(
          'w-7 shrink-0 text-center text-lg font-extrabold tabular-nums',
          rank <= 3 ? 'text-accent' : 'text-ink-faint',
        )}
      >
        {rank}
      </span>
      <div className="relative h-16 w-12 shrink-0 overflow-hidden rounded-md ring-1 ring-black/5">
        <Cover series={series} showTitle={false} rounded="rounded-md" />
      </div>
      <div className="min-w-0 flex-1">
        <h4 className="line-clamp-1 font-bold tracking-tight transition-colors group-hover:text-accent">
          {series.title}
        </h4>
        <p className="line-clamp-1 text-xs text-ink-faint">{series.genres.slice(0, 2).join(' · ')}</p>
      </div>
      <div className="shrink-0 text-right">
        <div className="text-sm font-bold tabular-nums">{metric}</div>
      </div>
    </a>
  )
}

/* ---------------- Compact horizontal list card (search / library rows) ---------------- */
export function ListCard({ series, right }: { series: Series; right?: React.ReactNode }) {
  return (
    <a
      href={`${seriesHref(series)}`}
      onClick={go(seriesHref(series))}
      className="group flex items-center gap-4 rounded-[14px] border border-line bg-paper p-3 transition-all hover:-translate-y-0.5 hover:shadow-md"
    >
      <div className="relative h-20 w-15 shrink-0 overflow-hidden rounded-lg ring-1 ring-black/5" style={{ width: 60 }}>
        <Cover series={series} showTitle={false} rounded="rounded-lg" />
      </div>
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-2">
          <StatusBadge status={series.status} />
        </div>
        <h4 className="mt-1 line-clamp-1 font-bold tracking-tight transition-colors group-hover:text-accent">
          {series.title}
        </h4>
        <p className="line-clamp-1 text-sm text-ink-soft">
          {series.author} · {series.genres.slice(0, 2).join(', ')}
        </p>
      </div>
      {right && <div className="shrink-0">{right}</div>}
    </a>
  )
}
