import type { Chapter, Genre, Series } from '../types'
import { seededRandom, chapterCountOf } from './utils'

export interface FeedItem {
  series: Series
  chapter: Chapter
}

/** Most weekly views first — the "Trending Now" rail. */
export function trending(list: Series[], limit?: number): Series[] {
  const sorted = [...list].sort((a, b) => b.weeklyViews - a.weeklyViews)
  return limit ? sorted.slice(0, limit) : sorted
}

/** Highest rating first (rating, then rating count as tiebreak). */
export function topRanked(list: Series[], limit?: number): Series[] {
  const sorted = [...list].sort(
    (a, b) => b.rating - a.rating || b.ratingCount - a.ratingCount,
  )
  return limit ? sorted.slice(0, limit) : sorted
}

/** Most lifetime views first — "Most Popular". */
export function mostPopular(list: Series[], limit?: number): Series[] {
  const sorted = [...list].sort((a, b) => b.views - a.views)
  return limit ? sorted.slice(0, limit) : sorted
}

/** Newest debut first — "New Series". */
export function newestSeries(list: Series[], limit?: number): Series[] {
  const sorted = [...list].sort(
    (a, b) => new Date(b.firstReleased).getTime() - new Date(a.firstReleased).getTime(),
  )
  return limit ? sorted.slice(0, limit) : sorted
}

/** Recently updated series first — "Latest Updates". */
export function recentlyUpdated(list: Series[], limit?: number): Series[] {
  const sorted = [...list].sort(
    (a, b) => new Date(b.lastUpdated).getTime() - new Date(a.lastUpdated).getTime(),
  )
  return limit ? sorted.slice(0, limit) : sorted
}

/** Flattened recent-chapter feed across series — "Latest Updates". */
export function latestChapters(list: Series[], limit = 12): FeedItem[] {
  const items: FeedItem[] = []
  for (const series of list) {
    const recent = series.chapters.slice(-3)
    for (const chapter of recent) items.push({ series, chapter })
  }
  items.sort(
    (a, b) =>
      new Date(b.chapter.releaseDate).getTime() - new Date(a.chapter.releaseDate).getTime(),
  )
  return items.slice(0, limit)
}

export interface UpdateRow {
  series: Series
  /** newest first — the chapter chips shown on the Latest Updates rows */
  chapters: Chapter[]
}

export interface UpdateGroup {
  /** calendar-day key, e.g. "2026-8-30" */
  key: string
  /** "Today" / "Yesterday" / "Aug 28, 2026" */
  label: string
  rows: UpdateRow[]
}

function dayKey(d: Date): string {
  return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`
}

/**
 * Homepage "Latest Updates" — every series grouped by the day its newest
 * chapter dropped (Today / Yesterday / date), like the update feeds on other
 * manhwa sites. Each row carries the series' latest chapters as chips.
 */
export function latestUpdateGroups(list: Series[], limit = 36): UpdateGroup[] {
  const rows = list
    .map((series) => ({ series, latest: series.chapters[series.chapters.length - 1] }))
    .filter((r): r is { series: Series; latest: Chapter } => Boolean(r.latest))
    .sort(
      (a, b) =>
        new Date(b.latest.releaseDate).getTime() - new Date(a.latest.releaseDate).getTime(),
    )
    .slice(0, limit)
    .map(({ series }) => ({ series, chapters: series.chapters.slice(-3).reverse() }))

  const groups: UpdateGroup[] = []
  const byDay = new Map<string, UpdateGroup>()
  const now = new Date()
  const today = dayKey(now)
  const yesterday = dayKey(new Date(now.getTime() - 86_400_000))
  for (const row of rows) {
    const d = new Date(row.chapters[0].releaseDate)
    const key = dayKey(d)
    let group = byDay.get(key)
    if (!group) {
      group = {
        key,
        label:
          key === today
            ? 'Today'
            : key === yesterday
              ? 'Yesterday'
              : d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }),
        rows: [],
      }
      byDay.set(key, group)
      groups.push(group)
    }
    group.rows.push(row)
  }
  return groups
}

export function featured(list: Series[]): Series[] {
  const flagged = list.filter((s) => s.featured)
  return flagged.length ? flagged : trending(list, 5)
}

/** Seed from the local calendar date, e.g. "2026-8-30" — changes at midnight. */
function todaySeed(): string {
  const d = new Date()
  return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`
}

/** Seed that advances every `days` days — e.g. "rot-20691" — for sections
 *  that should visibly refresh on a multi-day cadence. */
function rotationSeed(days: number): string {
  return `rot-${Math.floor(Date.now() / (days * 86_400_000))}`
}

/**
 * Pick `limit` items from a ranked `pool` with a seeded partial Fisher–Yates,
 * restoring pool order afterwards so the pick is stable across re-renders.
 * Every entry still comes from the top of the ranking — only the mix rotates.
 */
function rotatingPick(pool: Series[], limit: number, seed: string): Series[] {
  if (pool.length <= limit) return pool
  const rng = seededRandom(seed)
  const idx = pool.map((_, i) => i)
  for (let i = 0; i < limit; i++) {
    const j = i + Math.floor(rng() * (idx.length - i))
    ;[idx[i], idx[j]] = [idx[j], idx[i]]
  }
  return idx
    .slice(0, limit)
    .sort((a, b) => a - b)
    .map((i) => pool[i])
}

/**
 * "Trending Now" homepage rail — action/fantasy-led like the aggregator
 * front pages (Asura/Flame/HiveToons all lead with the action cluster).
 * Entries come from the genuinely most-viewed pool (real AniList/MangaDex
 * numbers since the popularity enrichment), with the prime genres sorted
 * ahead of the rest so the rail leads with action/fantasy while still
 * showing a few other genres in the tail. Order still re-rolls every 2
 * days via the seeded shuffle within each group.
 */
export function trendingNow(list: Series[], limit = 12): Series[] {
  const pool = trending(list, 40)
  const prime = pool.filter((s) => isPrimeGenreSeries(s))
  const other = pool.filter((s) => !isPrimeGenreSeries(s))
  // keep 2-3 non-prime slots visible when the pool has them ("show other
  // genres too, just not on top")
  const otherSlots = Math.min(other.length, Math.max(2, Math.round(limit * 0.25)))
  const primeSlots = Math.max(0, limit - otherSlots)
  return [
    ...rotatingPick(prime, primeSlots, rotationSeed(2)),
    ...rotatingPick(other, otherSlots, rotationSeed(2) + ':other'),
  ]
}

/**
 * "Featured Today" — the hero carousel. Mirrors the big aggregators: the
 * first slots anchor on all-time-famous hits (matched at runtime from the
 * curated list below; anything missing from the catalog simply skips),
 * then action/fantasy from the real-popularity trending pool fills most
 * of the rest, and 2-3 slots rotate through the other genres so every
 * kind of reader finds something. The non-anchor picks re-roll daily.
 */
export function featuredToday(list: Series[], limit = 10): Series[] {
  const pool = trending(list, 80)
  // catalog slugs are internal (mk-…/md-…), so anchors match by normalized
  // title (+ alt titles, same normalization family as the merge)
  const byTitle = new Map<string, Series>()
  for (const s of pool) {
    for (const t of [s.title, ...(s.altTitles ?? [])]) {
      const k = normTitleKey(t)
      if (k && !byTitle.has(k)) byTitle.set(k, s)
    }
  }
  const anchors: Series[] = []
  const seen = new Set<string>()
  for (const key of FAMOUS_TITLES) {
    const hit = byTitle.get(key)
    if (hit && !seen.has(hit.slug)) {
      anchors.push(hit)
      seen.add(hit.slug)
    }
  }
  const used = new Set(anchors.map((s) => s.slug))
  const rest = pool.filter((s) => !used.has(s.slug))
  const prime = rest.filter((s) => isPrimeGenreSeries(s))
  const other = rest.filter((s) => !isPrimeGenreSeries(s))

  const anchorSlots = Math.min(anchors.length, Math.max(3, Math.round(limit * 0.4)))
  const otherSlots = Math.min(other.length, 3)
  const primeSlots = Math.max(0, limit - anchorSlots - otherSlots)

  return [
    ...anchors.slice(0, anchorSlots),
    ...rotatingPick(prime, primeSlots, todaySeed()),
    ...rotatingPick(other, otherSlots, todaySeed() + ':other'),
  ]
}

/** lowercase alphanumerics, apostrophes dropped — the merge normalization */
function normTitleKey(t: string | undefined): string {
  return String(t ?? '')
    .toLowerCase()
    .replace(/['’]/g, '')
    .replace(/[^a-z0-9]+/g, '')
}

/** Genres that dominate aggregator front pages — the action/fantasy
 *  cluster. Weighting applies ONLY to the homepage hero/trending rails;
 *  rankings, genre pages and the updates feed stay pure popularity. */
const PRIME_GENRES = new Set(['Action', 'Fantasy', 'Adventure', 'Thriller', 'Supernatural', 'Horror'])
const isPrimeGenreSeries = (s: Series) => (s.genres ?? []).some((g) => PRIME_GENRES.has(g))

/** All-time-famous titles, as normalized title keys (lowercase
 *  alphanumerics, no articles/parentheticals needed). Matched against the
 *  trending pool's titles + alt titles at runtime — entries missing from
 *  the catalog simply don't match and are skipped, so the list is safe to
 *  maintain loosely. These anchor the hero like every big aggregator's
 *  homepage does. */
const FAMOUS_TITLES = [
  'solo-leveling',
  'omniscient-readers-viewpoint',
  'tower-of-god',
  'lookism',
  'eleceed',
  'the-beginning-after-the-end',
  'return-of-the-mount-hua-sect',
  'nano-machine',
  'reaper-of-the-drifting-moon',
  'legend-of-the-northern-blade',
  'sss-class-suicide-hunter',
  'the-greatest-estate-developer',
  'solo-max-level-newbie',
  'teenage-mercenary',
  'the-god-of-high-school',
]

/**
 * "Top of the Charts" homepage preview — the highest-RATED series (real
 * AniList/MangaDex ratings since the popularity enrichment) with the same
 * prime-genre lead as the trending rails: action/fantasy first, a few
 * other genres in the tail, re-rolling every 2 days. The full /rankings
 * page stays PURE rating order.
 */
export function topOfCharts(list: Series[], limit = 10): Series[] {
  const pool = topRanked(list, 40)
  const prime = pool.filter((s) => isPrimeGenreSeries(s))
  const other = pool.filter((s) => !isPrimeGenreSeries(s))
  const otherSlots = Math.min(other.length, Math.max(2, Math.round(limit * 0.25)))
  const primeSlots = Math.max(0, limit - otherSlots)
  return [
    ...rotatingPick(prime, primeSlots, rotationSeed(2) + ':charts'),
    ...rotatingPick(other, otherSlots, rotationSeed(2) + ':charts:other'),
  ]
}

export function staffPicks(list: Series[]): Series[] {
  const picks = list.filter((s) => s.staffPick)
  return picks.length ? picks : topRanked(list, 5)
}

export function byGenre(list: Series[], genre: Genre, limit?: number): Series[] {
  const filtered = list.filter((s) => s.genres.includes(genre)).sort((a, b) => b.weeklyViews - a.weeklyViews)
  return limit ? filtered.slice(0, limit) : filtered
}

export function genreCount(list: Series[], genre: Genre): number {
  return list.filter((s) => s.genres.includes(genre)).length
}

/** Same-genre neighbours, excluding the given series — "Readers Also Enjoyed". */
export function readersAlsoEnjoyed(list: Series[], series: Series, limit = 6): Series[] {
  const scored = list
    .filter((s) => s.id !== series.id)
    .map((s) => ({
      s,
      overlap: s.genres.filter((g) => series.genres.includes(g)).length,
    }))
    .filter((x) => x.overlap > 0)
    .sort((a, b) => b.overlap - a.overlap || b.s.rating - a.s.rating)
  return scored.slice(0, limit).map((x) => x.s)
}

/**
 * Search matches title/credit fields only — synopsis/genre word-matching made
 * real-word queries ("Lookism") return every series whose blurb mentions the
 * word. Single source of truth shared by the catalog page and the navbar.
 */
export function matchesSearch(s: Series, q: string): boolean {
  return (
    s.title.toLowerCase().includes(q) ||
    s.altTitles?.some((t) => t.toLowerCase().includes(q)) ||
    s.author.toLowerCase().includes(q) ||
    s.artist.toLowerCase().includes(q) ||
    s.studio.toLowerCase().includes(q)
  )
}

export function searchLocal(list: Series[], query: string): Series[] {
  const q = query.trim().toLowerCase()
  if (!q) return []
  return list.filter((s) => {
    return matchesSearch(s, q)
  }).sort((a, b) => {
    const at = a.title.toLowerCase()
    const bt = b.title.toLowerCase()
    const aStarts = at.startsWith(q) ? 0 : 1
    const bStarts = bt.startsWith(q) ? 0 : 1
    return aStarts - bStarts || b.weeklyViews - a.weeklyViews
  })
}

/**
 * Real, verifiable catalog figures for the homepage stats band: series count,
 * chapter count, and ongoing titles. Deliberately returns nothing estimated —
 * the old monthlyViews (weeklyViews × 4) and activeReaders (× 0.18) fields
 * were fabricated extrapolations and have been removed.
 */
export function platformStats(list: Series[]) {
  const totalSeries = list.length
  const totalChapters = list.reduce((n, s) => n + chapterCountOf(s), 0)
  const ongoing = list.filter((s) => s.status === 'Ongoing').length
  return { totalSeries, totalChapters, ongoing }
}
