import type { Series } from '../types';
import { chapterCountOf, seriesHref, shortDescription } from './utils';

export const SITE_ORIGIN = 'https://manhwas.site';

export interface SeoMeta {
  /** Full <title> text, e.g. "Best Fantasy Manhwa – Recommendations & Catalog | MANHWAS". */
  title: string;
  /** Meta description, ideally 120–160 chars. */
  description: string;
  /** Canonical path (no domain), e.g. "/genres/fantasy". */
  path: string;
  /** true → robots "noindex,follow". */
  noindex?: boolean;
  /** Optional meta keywords (comma-separated). Google ignores the tag, but a
   * short honest list costs nothing and covers niche/typo queries. */
  keywords?: string;
  /** Absolute or root-relative OG image URL. */
  ogImage?: string;
  /** Open Graph type, defaults to 'website'. */
  ogType?: string;
  /** JSON-LD structured data object(s). */
  jsonLd?: Record<string, unknown> | Record<string, unknown>[];
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/**
 * Collapse all whitespace to single spaces, trim, and — when the text
 * exceeds `max` characters — cut at the last word boundary that fits,
 * appending a single '…' character. Never returns a string longer than
 * `max` (the ellipsis counts as one character).
 */
export function truncate(text: string, max: number): string {
  const clean = text.replace(/\s+/g, ' ').trim();
  if (clean.length <= max) {
    return clean;
  }
  // Reserve one character for the ellipsis.
  const cut = clean.slice(0, max - 1);
  const lastSpace = cut.lastIndexOf(' ');
  // Only fall back to a hard cut when the word boundary would be too early.
  const base = lastSpace >= Math.floor(max * 0.5) ? cut.slice(0, lastSpace) : cut;
  return base.replace(/[\s,.;:!-]+$/, '') + '…';
}

function slugify(value: string): string {
  return (
    value
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
  );
}

function absoluteUrl(path: string): string {
  if (/^https?:\/\//i.test(path)) {
    return path;
  }
  return SITE_ORIGIN + (path.startsWith('/') ? path : `/${path}`);
}

function breadcrumb(items: { name: string; path: string }[]): Record<string, unknown> {
  return {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: items.map((item, index) => ({
      '@type': 'ListItem',
      position: index + 1,
      name: item.name,
      item: absoluteUrl(item.path),
    })),
  };
}

/* ------------------------------------------------------------------ */
/* DOM application                                                     */
/* ------------------------------------------------------------------ */

const SEO_ATTR = 'data-seo';

function upsertMeta(selector: string, attr: 'name' | 'property', key: string, content: string): void {
  let el = document.head.querySelector<HTMLMetaElement>(selector);
  if (!el) {
    el = document.createElement('meta');
    el.setAttribute(attr, key);
    el.setAttribute(SEO_ATTR, '');
    document.head.appendChild(el);
  }
  el.setAttribute('content', content);
}

function upsertCanonical(href: string): void {
  let el = document.head.querySelector<HTMLLinkElement>('link[rel="canonical"]');
  if (!el) {
    el = document.createElement('link');
    el.setAttribute('rel', 'canonical');
    el.setAttribute(SEO_ATTR, '');
    document.head.appendChild(el);
  }
  el.setAttribute('href', href);
}

/**
 * Idempotently apply an SeoMeta to the current document: <title>,
 * meta description, canonical link, robots, and Open Graph tags.
 * Missing elements are created; existing ones are updated in place.
 * Any JSON-LD script injected by a previous call is replaced.
 */
export function setSeo(meta: SeoMeta): void {
  document.title = meta.title;

  upsertMeta('meta[name="description"]', 'name', 'description', meta.description);
  upsertMeta('meta[name="robots"]', 'name', 'robots', meta.noindex ? 'noindex,follow' : 'index,follow');

  upsertCanonical(absoluteUrl(meta.path));

  upsertMeta('meta[property="og:title"]', 'property', 'og:title', meta.title);
  upsertMeta('meta[property="og:description"]', 'property', 'og:description', meta.description);
  upsertMeta('meta[property="og:url"]', 'property', 'og:url', absoluteUrl(meta.path));
  upsertMeta('meta[property="og:type"]', 'property', 'og:type', meta.ogType ?? 'website');

  // og:image is only present when explicitly provided — drop a stale one
  // from a previous call before (maybe) adding the new one.
  document.head
    .querySelectorAll(`meta[property="og:image"][${SEO_ATTR}]`)
    .forEach((el) => el.remove());
  if (meta.ogImage) {
    upsertMeta(`meta[property="og:image"][${SEO_ATTR}]`, 'property', 'og:image', absoluteUrl(meta.ogImage as string));
  }

  // Optional keywords tag — created when provided, removed when a page
  // without keywords takes over so nothing stale lingers.
  const existingKeywords = document.head.querySelector<HTMLMetaElement>(
    `meta[name="keywords"][${SEO_ATTR}]`,
  );
  if (meta.keywords) {
    upsertMeta(`meta[name="keywords"][${SEO_ATTR}]`, 'name', 'keywords', meta.keywords);
  } else {
    existingKeywords?.remove();
  }

  // Replace any previously injected JSON-LD.
  document.head
    .querySelectorAll(`script[type="application/ld+json"][${SEO_ATTR}]`)
    .forEach((el) => el.remove());
  if (meta.jsonLd) {
    const script = document.createElement('script');
    script.setAttribute('type', 'application/ld+json');
    script.setAttribute(SEO_ATTR, '');
    script.textContent = JSON.stringify(meta.jsonLd);
    document.head.appendChild(script);
  }
}

/**
 * Remove only the JSON-LD elements injected by setSeo. Useful on page
 * transitions where base meta will be overwritten anyway.
 */
export function clearSeoExtra(): void {
  document.head
    .querySelectorAll(`script[type="application/ld+json"][${SEO_ATTR}]`)
    .forEach((el) => el.remove());
}

