function buildSeriesTitle(value: string, kindLabel: string, chapters: number): string {
  const title = value.replace(/\s+/g, ' ').trim();
  const brand = ' | MANHWAS';
  const richSuffix = ` ${kindLabel} – Read Free Online (${chapters} Ch)`;
  const shortSuffix = ` ${kindLabel} – Read Free Online`;
  const budget = 65 - brand.length;
  const titlePart =
    (title + richSuffix).length <= budget
      ? title + richSuffix
      : (title + shortSuffix).length <= budget
        ? title + shortSuffix
        : `${truncate(title, Math.max(18, budget - shortSuffix.length))}${shortSuffix}`;
  return `${titlePart}${brand}`;
}

function buildAuthorTitle(author: string): string {
  const cleanAuthor = author.replace(/\s+/g, ' ').trim();
  const brand = ' | MANHWAS';
  const budget = 65 - brand.length;
  const subject = `${cleanAuthor} Manhwa & Manhua`;
  const readSuffix = ' – Read Free Online';
  if ((subject + readSuffix).length <= budget) return `${subject}${readSuffix}${brand}`;
  if (subject.length <= budget) return `${subject}${brand}`;
  const subjectSuffix = ' Manhwa & Manhua';
  const authorBudget = Math.max(1, budget - subjectSuffix.length);
  return `${truncate(cleanAuthor, authorBudget)}${subjectSuffix}${brand}`;
}

export function buildSeriesMeta(series: Series): SeoMeta {
  // GSC growth lever: "<title> chapter N" queries land on series pages at
  // positions 1-5 with near-zero CTR — the latest chapter number in the
  // description matches that intent directly (mirrors scripts/prerender.mjs;
  // the mobile compact catalog still carries every chapter's number).
  const latestChapter = series.chapters.length ? series.chapters[series.chapters.length - 1]?.number : undefined;
  const chapters = chapterCountOf(series);
  const latestNote = latestChapter
    ? ` — chapter ${latestChapter} just dropped, ${chapters} chapters and counting`
    : '';
  const prefix = `Read ${series.title} free online${series.author ? ` by ${series.author}` : ''}${latestNote}. `;
  const max = 155;
  const remaining = max - prefix.length;
  const blurb = shortDescription(series, 155);
  const description = remaining >= 60 ? truncate(prefix + blurb, max) : truncate(blurb, max);

  const path = seriesHref(series);
  const url = absoluteUrl(path);

  const book: Record<string, unknown> = {
    '@context': 'https://schema.org',
    '@type': 'Book',
    name: series.title,
    // Cover in the schema (not just og:image) — Google image search / rich
    // results. Own CDN copy first; mirrors scripts/prerender.mjs.
    ...((series.coverCdn || series.coverUrl) ? { image: [series.coverCdn || series.coverUrl] } : {}),
    author: { '@type': 'Person', name: series.author },
    genre: series.genres,
    inLanguage: 'en',
    url,
    abstract: shortDescription(series, 300),
  };

  // "read <title> free" is the intent these SERPs carry — keep the title on
  // that, mirroring the prerendered template in scripts/prerender.mjs.
  // Match scripts/prerender.mjs: series titles stay under the audit's 70-char threshold.
  const kindLabel = path.startsWith('/manhua') ? 'Manhua' : 'Manhwa';
  const title = buildSeriesTitle(series.title, kindLabel, chapters);

  return {
    title,
    description,
    path,
    ogImage: series.coverCdn || series.coverUrl,
    jsonLd: [
      book,
      breadcrumb([
        { name: 'Home', path: '/' },
        { name: 'Catalog', path: '/catalog' },
        { name: series.title, path },
      ]),
    ],
  };
}

/**
 * Chapter-page meta for the SPA reader.
 *
 * The server-rendered chapter document (functions/read + api/read) carries a
 * concise, ≤70-character title with the chapter number preserved. The SPA
 * applies the same format on client-side chapter navigation. The title rule
 * mirrors chapterTitle() in api/read/index.ts and functions/read/[[path]].js.
 */
export function buildChapterMeta(args: {
  title: string
  /** title-slug used in URLs (utils.titleSlug), NOT the internal md-/mk- id */
  slug: string
  kind: 'manhwa' | 'manhua'
  chapter: number
  total: number
  date?: string
  genres?: string[]
  coverUrl?: string
  author?: string
}): SeoMeta {
  const path = `/read/${args.slug}/chapter-${args.chapter}`
  const titleSuffix = ` Chapter ${args.chapter} | MANHWAS`
  const titleLimit = 70
  const cleanTitle = args.title.replace(/\s+/g, ' ').trim()
  const fullTitle = `${cleanTitle}${titleSuffix}`
  let title = fullTitle
  if ([...fullTitle].length > titleLimit) {
    const titleBudget = titleLimit - [...titleSuffix].length
    const cut = [...cleanTitle].slice(0, Math.max(1, titleBudget - 1)).join('')
    const boundary = cut.lastIndexOf(' ')
    const base = boundary >= titleBudget * 0.5 ? cut.slice(0, boundary) : cut
    title = `${base.replace(/[\s,.;:!-]+$/, '')}…${titleSuffix}`
  }
  // Keep the chapter title and description rules aligned with both SSR renderers
  // (functions/read/[[path]].js + api/read/index.ts).
  const head = `Read ${args.title} Chapter ${args.chapter} online free on MANHWAS — chapter ${args.chapter} of ${args.total} chapters.`
  const date = args.date ? ` Updated ${args.date}.` : ''
  const genres = args.genres?.length ? ` ${args.title} genres: ${args.genres.join(', ')}.` : ''
  const description =
    (head + date + genres).length <= 155
      ? head + date + genres
      : (head + date).length <= 155
        ? head + date
        : head.length <= 155
          ? head
          : `${args.title} Chapter ${args.chapter} – read free on MANHWAS.`.slice(0, 155)

  return {
    title,
    description,
    path,
    ogImage: args.coverUrl,
    ogType: 'article',
    jsonLd: [
      {
        '@context': 'https://schema.org',
        '@type': 'Article',
        headline: `${args.title} Chapter ${args.chapter}`,
        url: absoluteUrl(path),
        mainEntityOfPage: absoluteUrl(path),
        ...(args.coverUrl ? { image: [args.coverUrl] } : {}),
        ...(args.date ? { datePublished: args.date } : {}),
        inLanguage: 'en',
        isPartOf: {
          '@type': 'Book',
          name: args.title,
          url: absoluteUrl(`/${args.kind}/${args.slug}`),
        },
        ...(args.author && args.author !== 'Unknown'
          ? { author: { '@type': 'Person', name: args.author } }
          : {}),
        publisher: { '@type': 'Organization', name: 'MANHWAS', url: SITE_ORIGIN },
      },
      breadcrumb([
        { name: 'Home', path: '/' },
        { name: args.title, path: `/${args.kind}/${args.slug}` },
        { name: `Chapter ${args.chapter}`, path },
      ]),
    ],
  }
}

export function buildGenreMeta(genre: string, count: number): SeoMeta {
  const path = `/genres/${encodeURIComponent(slugify(genre))}`;
  const label = genre.trim();
  const description =
    count > 0
      ? `The best ${label.toLowerCase()} manhwa to read free — ${count} series ranked by what readers follow this week, with new chapters updated daily on MANHWAS.`
      : `The best ${label.toLowerCase()} manhwa to read free on MANHWAS — hand-catalogued series with ratings, chapter counts, and reading order.`;

  return {
    title: `Best ${label} Manhwa – Read Free Online | MANHWAS`,
    description,
    path,
    jsonLd: breadcrumb([
      { name: 'Home', path: '/' },
      { name: 'Genres', path: '/genres' },
      { name: label, path },
    ]),
  };
}

export function buildStatusMeta(status: 'ongoing' | 'completed', count: number): SeoMeta {
  const isOngoing = status === 'ongoing';
  const label = isOngoing ? 'Ongoing' : 'Completed';
  const path = `/status/${status}`;

  const description = isOngoing
    ? count > 0
      ? `Browse ${count} ongoing manhwa still releasing chapters — read the latest updates free the day they drop.`
      : 'Browse every ongoing manhwa on MANHWAS — series still releasing new chapters, sorted by the latest updates.'
    : count > 0
      ? `Browse ${count} completed manhwa you can read free from first chapter to last — finished series, no cliffhangers, full chapter lists.`
      : 'Browse completed manhwa you can read free from first chapter to last on MANHWAS — finished series, no cliffhangers, full chapter lists.';

  return {
    title: isOngoing
      ? 'Ongoing Manhwa – New Chapters Free, Updated Daily | MANHWAS'
      : 'Completed Manhwa to Binge – Read Finished Series | MANHWAS',
    description,
    path,
    jsonLd: breadcrumb([
      { name: 'Home', path: '/' },
      { name: `${label} Manhwa`, path },
    ]),
  };
}

/** Author pages: /author/{slug} — "manhwa by {author}" long-tail. */
export function buildAuthorMeta(
  author: string,
  count: number,
  /** Real series list when the caller has it — powers the ProfilePage
   *  schema (2026-09-28 audit: author pages had no Person entity). */
  works?: { title: string; href: string }[],
): SeoMeta {
  const path = `/author/${slugify(author)}`;
  const description =
    count > 0
      ? `Read ${count} manhwa and manhua by ${author} free online — every series, full chapter lists, new chapters the day they drop.`
      : `Read manhwa and manhua by ${author} free online on MANHWAS — full chapter lists, new chapters the day they drop.`;
  // Keep author titles aligned with the prerendered static page.
  const title = buildAuthorTitle(author);
  const jsonLd: Record<string, unknown>[] = [
    breadcrumb([
      { name: 'Home', path: '/' },
      { name: 'Authors', path: '/directory' },
      { name: author, path },
    ]),
  ];
  if (works?.length) {
    jsonLd.push({
      '@context': 'https://schema.org',
      '@type': 'ProfilePage',
      mainEntity: { '@type': 'Person', name: author, url: absoluteUrl(path) },
      hasPart: works.slice(0, 25).map((w) => ({
        '@type': 'Book',
        name: w.title,
        url: absoluteUrl(w.href),
      })),
    });
  }
  return {
    title,
    description,
    path,
    jsonLd,
  };
}

/** A–Z directory: /directory and /directory/{letter}. */
export function buildDirectoryMeta(isLetter: boolean, letter: string | null): SeoMeta {
  const path = isLetter && letter ? `/directory/${letter}` : '/directory';
  const title = isLetter && letter
    ? `${letter.toUpperCase()} Manhwa & Manhua – A to Z Directory | MANHWAS`
    : 'Manhwa & Manhua Directory – Browse A to Z | MANHWAS';
  const description = isLetter && letter
    ? `Browse every manhwa and manhua starting with "${letter.toUpperCase()}" on MANHWAS — free to read, sorted alphabetically, full chapter lists.`
    : 'Browse every manhwa and manhua on MANHWAS from A to Z — free to read, full chapter lists, daily updates. The complete series directory.';
  return {
    title,
    description,
    path,
    jsonLd: breadcrumb([
      { name: 'Home', path: '/' },
      { name: 'Directory', path: '/directory' },
      ...(isLetter && letter ? [{ name: letter.toUpperCase(), path }] : []),
    ]),
  };
}

/** Year pages: /years/{year} — "new manhwa {year}" queries. */
export function buildYearMeta(year: string, count: number): SeoMeta {
  const path = `/years/${year}`;
  const description =
    count > 0
      ? `${count} manhwa and manhua that started publishing in ${year} — read them free online, full chapter lists, on MANHWAS.`
      : `Manhwa and manhua that started publishing in ${year} — read them free online on MANHWAS.`;
  return {
    title: `New Manhwa & Manhua ${year} – Read Free Online | MANHWAS`,
    description,
    path,
    jsonLd: breadcrumb([
      { name: 'Home', path: '/' },
      { name: 'Years', path: '/directory' },
      { name: year, path },
    ]),
  };
}

/** Kind×genre combo hubs: /browse/{kind}/{genre}. */
export function buildBrowseMeta(genre: string, kind: 'manhwa' | 'manhua', count: number): SeoMeta {
  const path = `/browse/${kind}/${slugify(genre)}`;
  const kindLabel = kind === 'manhwa' ? 'Manhwa' : 'Manhua';
  const description =
    count > 0
      ? `Browse ${count} ${genre} ${kindLabel.toLowerCase()} free online — the best ${genre} titles, full chapter lists, new chapters daily on MANHWAS.`
      : `Browse the best ${genre} ${kindLabel.toLowerCase()} free online on MANHWAS — full chapter lists, new chapters daily.`;
  return {
    title: `Best ${genre} ${kindLabel} – Read Free Online | MANHWAS`,
    description,
    path,
    jsonLd: breadcrumb([
      { name: 'Home', path: '/' },
      { name: `${kindLabel}s`, path: `/${kind}` },
      { name: `${genre} ${kindLabel}`, path },
    ]),
  };
}

/** Kind hub pages: bare /manhwa and /manhua. */
export function buildKindMeta(kind: 'manhwa' | 'manhua', count: number): SeoMeta {
  const isManhwa = kind === 'manhwa';
  const path = `/${kind}`;

  const description = isManhwa
    ? count > 0
      ? `Browse ${count} Korean manhwa free — trending webtoons with full chapter lists and daily updates. Read any series online without an account.`
      : 'Browse every Korean manhwa on MANHWAS — trending webtoons with full chapter lists and daily updates, free to read online.'
    : count > 0
      ? `Browse the top manhua free — ${count} Chinese webcomics and cultivation favorites with full chapter lists, updated daily.`
      : 'Browse the top manhua on MANHWAS — Chinese webcomics and cultivation favorites with full chapter lists, free to read.';

  return {
    title: isManhwa
      ? 'Browse All Manhwa – Korean Webtoons Free to Read | MANHWAS'
      : 'Top Manhua – Chinese Webcomics Free to Read | MANHWAS',
    description,
    path,
    keywords: isManhwa ? undefined : 'top manhua, topmanhua',
    jsonLd: breadcrumb([
      { name: 'Home', path: '/' },
      { name: isManhwa ? 'Manhwa' : 'Manhua', path },
    ]),
  };
}

