import { useEffect, useState } from 'react'
import { useRoute } from '../lib/router'
import BannerAd from './BannerAd'

// Approved creatives: popunders live in index.html; banner zones in
// BannerAd.tsx. The approved text hyperlink remains as reader-aside +
// prerendered AD_ASIDE creative (api/read + prerender.mjs).

type SlotId = 'top' | 'bottom' | 'left' | 'right'

/**
 * Edge ads — banner-styled slots pinned around the viewport: top strip,
 * bottom bar, left rail, right rail. Never inside the content column.
 *
 * Rendered in two zones (see App.tsx):
 * - zone="top"    → the embedded strip, mounted directly under the Navbar
 * - zone="overlay" → fixed rails + bottom bar, mounted at the app root
 *
 * Reading-experience rules (user contract, 2026-09-24 rev):
 * - Reader route: NO top strip (ads never sit on top of the reading
 *   column) — the reader shows the BOTTOM bar (all viewports, after 600px
 *   scroll, matching the server-rendered banner in api/read) plus the
 *   side rails on ≥1520px screens, always outside the reading column.
 * - Non-reader routes: top strip + side rails + bottom bar (after scroll).
 * - Dismissal is per page view: closing a slot hides it until the next
 *   full page load or SPA navigation (state resets on route change).
 * - Bottom bar appears only after a 600px scroll (reader-intent signal),
 *   so a fresh visit is never greeted by an overlay.
 * - Side rails render only ≥1520px: (100vw − 1240px) / 2 leaves room, so
 *   they can never overlap content or cause horizontal scroll.
 *
 * Every slot is a full-surface click target for the approved hyperlink —
 * the whole banner is the ad, so slots never look "empty".
 */
export default function EdgeAds({ zone }: { zone: 'top' | 'overlay' }) {
  const route = useRoute()
  const isReader = route.segments[0] === 'read' && !!route.segments[1]

  // Dismissals live per page view — reset on every route change.
  const [closed, setClosed] = useState<Record<SlotId, boolean>>({
    top: false,
    bottom: false,
    left: false,
    right: false,
  })
  useEffect(() => {
    setClosed({ top: false, bottom: false, left: false, right: false })
  }, [route.path])

  // Bottom bar waits for a scroll-depth signal (all routes, reader included —
  // the server-rendered chapter banner behaves the same).
  const [scrolled, setScrolled] = useState(false)
  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 600)
    onScroll()
    window.addEventListener('scroll', onScroll, { passive: true })
    return () => window.removeEventListener('scroll', onScroll)
  }, [])

  const close = (slot: SlotId) => setClosed((c) => ({ ...c, [slot]: true }))

  const CloseBtn = ({ slot, corner }: { slot: SlotId; corner: 'edge' | 'float' }) => (
    <button
      type="button"
      onClick={() => close(slot)}
      aria-label="Close advertisement"
      className={
        corner === 'float'
          ? 'absolute -right-2 -top-2 z-10 flex h-6 w-6 items-center justify-center rounded-full border border-onyx-line bg-onyx-2 text-xs leading-none text-[#83817a] shadow hover:text-[#f0efeb]'
          : 'absolute right-2 top-1/2 -translate-y-1/2 p-2 text-base leading-none text-[#83817a] hover:text-[#f0efeb]'
      }
    >
      ×
    </button>
  )

  if (zone === 'top') {
    return closed.top || isReader ? null : (
      // No wrapper chrome — the banner box IS the whole strip (exactly ad-sized).
      <div className="relative z-30 mx-auto w-fit pt-2">
        {/* 728x90 on desktop, 320x50 on mobile — same zone slot */}
        <span className="hidden md:block"><BannerAd size="728x90" /></span>
        <span className="md:hidden"><BannerAd size="320x50" /></span>
        <CloseBtn slot="top" corner="float" />
      </div>
    )
  }

  // Literal class strings — Tailwind's scanner can't see classes built by
  // string interpolation (ponytail: two literals beat one template).
  const Rail = ({ slot, side }: { slot: SlotId; side: 'left' | 'right' }) =>
    closed[slot] ? null : (
      <aside
        aria-label="Advertisement"
        className={
          side === 'left'
            ? 'fixed left-4 top-1/2 z-40 hidden -translate-y-1/2 min-[1520px]:block'
            : 'fixed right-4 top-1/2 z-40 hidden -translate-y-1/2 min-[1520px]:block'
        }
      >
        <div className="relative">
          <CloseBtn slot={slot} corner="float" />
          {/* ponytail: real banner zone when the network dashboard offers a responsive format */}
          <BannerAd size={side === 'left' ? '160x600' : '160x300'} className="shadow-lg" />
        </div>
      </aside>
    )

  return (
    <>
      <span className="sr-only" aria-live="polite">Advertisements</span>
      {/* SIDES — fixed rails, desktop only, outside the 1240px column. */}
      <Rail slot="left" side="left" />
      <Rail slot="right" side="right" />

      {/* BOTTOM — fixed banner bar, after 600px scroll (reader included). */}
      {closed.bottom || !scrolled ? null : (
        <div className="fixed bottom-3 left-1/2 z-40 -translate-x-1/2">
          {/* Floating box, exactly ad-sized — no full-width bar behind it. */}
          <div className="relative">
            <span className="hidden md:block"><BannerAd size="468x60" className="shadow-lg" /></span>
            <span className="md:hidden"><BannerAd size="320x50" className="shadow-lg" /></span>
            <CloseBtn slot="bottom" corner="float" />
          </div>
        </div>
      )}
    </>
  )
}
