import type { PostHog } from 'posthog-js'
import type { Properties } from 'posthog-js'

const posthogKey = import.meta.env.VITE_POSTHOG_KEY
const posthogHost = import.meta.env.VITE_POSTHOG_HOST

export const isPostHogEnabled = Boolean(posthogKey && posthogHost)

if (!isPostHogEnabled && import.meta.env.DEV) {
  const missingVariable = posthogKey ? 'VITE_POSTHOG_HOST' : 'VITE_POSTHOG_KEY'
  throw new Error(
    `${missingVariable} variable required by PostHog is missing or un-configured, this causes events to be silently missed. This error stops appearing once ${missingVariable} is configured`,
  )
}

type DeferredCall = (client: PostHog) => void
type IdleWindow = Window & {
  requestIdleCallback?: (callback: () => void, options?: { timeout: number }) => number
  cancelIdleCallback?: (handle: number) => void
}

let client: PostHog | undefined
let queue: DeferredCall[] = []
let pendingLogs: { message: string; attributes?: Properties }[] = []
let started = false

function runOrQueue(call: DeferredCall) {
  if (!isPostHogEnabled) return
  if (client) {
    call(client)
    return
  }
  queue.push(call)
}

function initializePostHog() {
  if (started || !isPostHogEnabled) return
  started = true
  void import('posthog-js')
    .then(({ default: posthog }) => {
      posthog.init(posthogKey, {
        api_host: posthogHost,
        capture_pageview: 'history_change',
        capture_exceptions: {
          capture_unhandled_errors: true,
          capture_unhandled_rejections: true,
          capture_console_errors: false,
        },
        defaults: '2026-05-30',
        logs: {
          serviceName: 'manhwas-digital-comics-web',
          environment: import.meta.env.MODE,
        },
      })
      client = posthog
      for (const call of queue) call(posthog)
      queue = []
      for (const log of pendingLogs) posthog.logger.info(log.message, log.attributes)
      pendingLogs = []
    })
    .catch(() => {
      // Analytics must not prevent the catalogue or reader from working.
      queue = []
      pendingLogs = []
    })
}

// Keep PostHog off the critical path: load it after the browser has idle time,
// with a bounded fallback for browsers without requestIdleCallback.
if (isPostHogEnabled && typeof window !== 'undefined') {
  const idleWindow = window as IdleWindow
  if (idleWindow.requestIdleCallback) {
    idleWindow.requestIdleCallback(initializePostHog, { timeout: 4000 })
  } else {
    window.setTimeout(initializePostHog, 2000)
  }
  window.addEventListener('pointerdown', initializePostHog, { once: true, passive: true })
  window.addEventListener('keydown', initializePostHog, { once: true })
}

// Preserve the existing event/auth API and call order while the deferred SDK
// chunk is still loading. User actions and identify/reset calls are replayed
// in order once PostHog is ready.
const posthog = {
  capture: (...args: Parameters<PostHog['capture']>) =>
    runOrQueue((instance) => instance.capture(...args)),
  identify: (...args: Parameters<PostHog['identify']>) =>
    runOrQueue((instance) => instance.identify(...args)),
  reset: (...args: Parameters<PostHog['reset']>) =>
    runOrQueue((instance) => instance.reset(...args)),
  logger: {
    info: (message: string, attributes?: Properties) => {
      if (!isPostHogEnabled) return
      if (client) client.logger.info(message, attributes)
      else pendingLogs.push({ message, attributes })
    },
  },
}

export default posthog
