import { useRef, type ReactNode } from 'react'
import { ChevronLeft, ChevronRight } from 'lucide-react'

export default function Rail({ children }: { children: ReactNode }) {
  const ref = useRef<HTMLDivElement>(null)

  const scroll = (dir: -1 | 1) => {
    const el = ref.current
    if (!el) return
    el.scrollBy({ left: dir * Math.min(el.clientWidth * 0.8, 640), behavior: 'smooth' })
  }

  return (
    <div className="group/rail relative">
      <div
        ref={ref}
        className="no-scrollbar -mx-4 flex snap-x snap-mandatory gap-5 overflow-x-auto scroll-pl-4 px-4 pb-2 sm:mx-0 sm:scroll-pl-0 sm:px-0"
      >
        {children}
      </div>

      <button
        onClick={() => scroll(-1)}
        className="absolute -left-4 top-[38%] hidden h-10 w-10 -translate-y-1/2 place-items-center rounded-full border border-line-strong bg-paper/95 text-ink shadow-md backdrop-blur transition-all hover:border-ink hover:bg-paper group-hover/rail:grid lg:flex"
        aria-label="Scroll left"
        style={{ display: undefined }}
      >
        <ChevronLeft width={20} height={20} />
      </button>
      <button
        onClick={() => scroll(1)}
        className="absolute -right-4 top-[38%] hidden h-10 w-10 -translate-y-1/2 place-items-center rounded-full border border-line-strong bg-paper/95 text-ink shadow-md backdrop-blur transition-all hover:border-ink hover:bg-paper group-hover/rail:grid lg:flex"
        aria-label="Scroll right"
      >
        <ChevronRight width={20} height={20} />
      </button>
    </div>
  )
}
